local config = {
  ui_story_5051_50510101_X1_dialog_content = "Warning, warning, emergency situation.",
  ui_story_5051_50510101_X2_dialog_content = "Warning, warning, emergency situation.",
  ui_story_5051_50510101_1_dialog_content = "Not again.",
  ui_story_5051_50510101_2_dialog_content = "Why now, of all times?!",
  ui_story_5051_50510101_3_dialog_content = "The med... Ah, over here.",
  ui_story_5051_50510101_4_dialog_content = "Your condition's getting worse lately.",
  ui_story_5051_50510101_5_dialog_content = "From what I know, perhaps it's already...",
  ui_story_5051_50510101_6_dialog_content = "My lord, is something the matter?",
  ui_story_5051_50510101_7_dialog_content = "It's nothing! As I said before, I don't want to be disturbed!",
  ui_story_5051_50510101_8_dialog_content = "But your carriage to the Family Day banquet has arrived.",
  ui_story_5051_50510101_9_dialog_content = "I'll see myself down in a moment!",
  ui_story_5051_50510101_10_dialog_content = "<color=#FFB400>Family Day</color>? What a farce.",
  ui_story_5051_50510101_11_dialog_content = "He ruined your life and still has the gall to throw a party and call it a Family Day banquet?",
  ui_story_5051_50510101_12_dialog_content = "Don't worry, I won't fight him.",
  ui_story_5051_50510101_13_dialog_content = "This may be the last chance. I must bring <color=#FFB400>it</color> back.",
  ui_story_5051_50510101_14_dialog_content = "You never broke your promises to me, and neither will I.",
  ui_story_5051_50510101_15_dialog_content = "This time, I promise I'll...",
  ui_story_5051_50510101_16_dialog_content = "Jeez.",
  ui_story_5051_50510101_17_dialog_content = "We're gonna be late at this rate!",
  ui_story_5051_50510101_18_dialog_content = "I even changed into my outfit two hours early, so why isn't anyone here yet?!",
  ui_story_5051_50510101_19_dialog_content = "Where the heck is Queen Bethlehem's envoy?",
  ui_story_5051_50510101_20_dialog_content = "\"Dear PlayerName, an envoy from Northland will soon be visiting Lumopolis to attend the banquet.\"",
  ui_story_5051_50510101_21_dialog_content = "\"As you will most likely be in attendance as well, I humbly ask that you accompany her during her stay.\"",
  ui_story_5051_50510101_22_dialog_content = "\"She will be waiting for you outside of Umbraton at the predesignated time.\"",
  ui_story_5051_50510101_X22_dialog_content = "We're out of time. We're going to be late!",
  ui_story_5051_50510101_X23_dialog_content = "Where is the messenger mentioned in the correspondence?",
  ui_story_5051_50510101_23_dialog_content = "Queen Bethlehem's something else. She even knew that I was going to attend the <color=#FFB400>Schwartz Family Day</color> banquet today.",
  ui_story_5051_50510101_24_dialog_content = "<size=30>Um...</size>",
  ui_story_5051_50510101_25_dialog_content = "Even I was shocked to receive an invitation. I've never been to a banquet as formal as this.",
  ui_story_5051_50510101_26_dialog_content = "Is my outfit fancy enough for the occasion? They won't think I'm weird, right?",
  ui_story_5051_50510101_27_dialog_content = "Lady Sheol says this is the most trendy formalwear in Lumopolis right now. It cost me a fortune just to rent.",
  ui_story_5051_50510101_28_dialog_content = "And I don't know a thing about clothes, so I just paid for it without thinking...",
  ui_story_5051_50510101_29_dialog_content = "Sigh, if only Carleen were around, she'd know what to do.",
  ui_story_5051_50510101_30_dialog_content = "I haven't been able to get ahold of her recently. I wonder where she could've gone.",
  ui_story_5051_50510101_31_dialog_content = "Um... Pardon me...",
  ui_story_5051_50510101_32_dialog_content = "Oh yeah, there's also the present! I just hope it's good enough...",
  ui_story_5051_50510101_33_dialog_content = "E-Excuse me...!",
  ui_story_5051_50510101_34_dialog_content = "Bwaaaa!!! B-B-Baba Yaga! What are you doing here?!",
  ui_story_5051_50510101_35_dialog_content = "Hey!",
  ui_story_5051_50510101_36_dialog_content = "I-I'm sorry!",
  ui_story_5051_50510101_37_dialog_content = "Hang on, you're not Baba Yaga. You're her other personality, <color=#FFB400>Mia</color>! Right?",
  ui_story_5051_50510101_38_dialog_content = "Yes, it's me.",
  ui_story_5051_50510101_39_dialog_content = "Though to be precise, I'm the dominant personality, not her...",
  ui_story_5051_50510101_40_dialog_content = "I'm just not as strong as Baba Yaga, and I can't control my own powers as well, so I have to rely on her to get things done.",
  ui_story_5051_50510101_41_dialog_content = "Sorry if I scared you...",
  ui_story_5051_50510101_42_dialog_content = "Don't worry about it! So, did you need something?",
  ui_story_5051_50510101_X42_dialog_content = "Uh, so I heard you're going to the Schwartz Family Day banquet, PlayerName.",
  ui_story_5051_50510101_X43_dialog_content = "Do you mind... bringing me along?",
  ui_story_5051_50510101_X44_dialog_content = "Bring you? Sure, but what makes you suddenly want to go to a banquet?",
  ui_story_5051_50510101_X45_dialog_content = "Uh, I've been feeling a lot better lately from recent treatments.",
  ui_story_5051_50510101_43_dialog_content = "Well, I recently underwent some treatment, and now my condition has gotten much better.",
  ui_story_5051_50510101_44_dialog_content = "So much so, that I finally remembered something important...",
  ui_story_5051_50510101_45_dialog_content = "What would that be?",
  ui_story_5051_50510101_46_dialog_content = "That I'm... <color=#FFB400>Carleen's older sister</color>.",
  ui_story_5051_50510101_47_dialog_content = "C-Carleen's sister?!",
  ui_story_5051_50510101_48_dialog_content = "But I thought Lumopolis only had one princess?!",
  ui_story_5051_50510101_49_dialog_content = "Not to mention, you two don't really... No, wait, if I look closely, I can see a resemblance.",
  ui_story_5051_50510101_50_dialog_content = "It's hard to believe, isn't it?",
  ui_story_5051_50510101_51_dialog_content = "No one is willing to believe a word I say. Even Uncle Istvan just sat there in silence when I told him.",
  ui_story_5051_50510101_52_dialog_content = "But it's the truth. Even now, fragments of memories keep flashing through my mind.",
  ui_story_5051_50510101_53_dialog_content = "Some are as clear as day. Others have been all but forgotten...",
  ui_story_5051_50510101_54_dialog_content = "My mother, my sister... my father. My family.",
  ui_story_5051_50510101_55_dialog_content = "I think you mentioned something before...",
  ui_story_5051_50510101_56_dialog_content = "You once said that your father was a city lord, and that your mother and sister lived in the palace.",
  ui_story_5051_50510101_57_dialog_content = "On top of that, you and Baba Yaga have always paid close attention to Carleen.",
  ui_story_5051_50510101_58_dialog_content = "But since you usually forget everything you say, I had no way of knowing if you were telling the truth or not...",
  ui_story_5051_50510101_59_dialog_content = "Still, I'm glad that your treatment is working and that you're feeling much better, Mia.",
  ui_story_5051_50510101_60_dialog_content = "I heard that Lumopolis was hosting a banquet for Schwartz Family Day.",
  ui_story_5051_50510101_61_dialog_content = "From what I can piece together, it's a very special and important occasion.",
  ui_story_5051_50510101_62_dialog_content = "I imagine my sister Carleen will most likely be there.",
  ui_story_5051_50510101_X62_dialog_content = "I'd like to go to the party and see for myself if these lingering emotions are real.",
  ui_story_5051_50510101_X63_dialog_content = "Or maybe just a glimpse of her from afar would be enough...",
  ui_story_5051_50510101_63_dialog_content = "I want to attend. I want to see her and prove whether or not these fond memories are truly real.",
  ui_story_5051_50510101_64_dialog_content = "Even if I can't prove any of these things, as long as I can see that she's doing well, even from afar, that will be good enough for me...",
  ui_story_5051_50510101_65_dialog_content = "PlayerName, you are one of Carleen's closest friends, as well as a respected figure in Lumopolis...",
  ui_story_5051_50510101_X65_dialog_content = "That's why I came to see you...",
  ui_story_5051_50510101_X66_dialog_content = "I see. Oops, we're short on time!",
  ui_story_5051_50510101_X67_dialog_content = "Do you have a suitable gown? And a present as well...",
  ui_story_5051_50510101_66_dialog_content = "Do you think you could help me?",
  ui_story_5051_50510101_67_dialog_content = "It's true that I'm going to the banquet today, but I'm not sure if I'm allowed to bring friends along with me.",
  ui_story_5051_50510101_68_dialog_content = "Hmm... Does it have to be today?",
  ui_story_5051_50510101_69_dialog_content = "(Instead of finding Northland's envoy here, I ended up finding Mia in need of help.)",
  ui_story_5051_50510101_70_dialog_content = "(But will it really be okay if I bring her as a guest so suddenly?)",
  ui_story_5051_50510101_71_dialog_content = "(The Family Day banquet seems like a really important event. Wouldn't randomly bringing someone who claims to be a Schwartz be kind of...)",
  ui_story_5051_50510101_72_dialog_content = "(Not only that, the whole banquet will be ruined if Baba Yaga makes an unexpected appearance!)",
  ui_story_5051_50510101_73_dialog_content = "I'm making trouble for you, aren't I?",
  ui_story_5051_50510101_74_dialog_content = "I'm sorry. Forget I said anything.",
  ui_story_5051_50510101_75_dialog_content = "I have no right to pressure you with my own selfish demands.",
  ui_story_5051_50510101_76_dialog_content = "L-Let's just pretend this conversation never happened.",
  ui_story_5051_50510101_77_dialog_content = "Ah, whatever! Come on, Mia! You're coming with me to the Family Day banquet!",
  ui_story_5051_50510101_78_dialog_content = "H-Huh? But wouldn't it be too much trouble for you?",
  ui_story_5051_50510101_79_dialog_content = "This is the first time you've really opened up to me.",
  ui_story_5051_50510101_80_dialog_content = "Whenever there's a problem, Baba Yaga is usually the one who handles it.",
  ui_story_5051_50510101_81_dialog_content = "How could I possibly turn you down when you're clearly trying so hard?",
  ui_story_5051_50510101_82_dialog_content = "So just relax! I'm good friends with Carleen, as well as lots of people from Lumopolis.",
  ui_story_5051_50510101_83_dialog_content = "If we're not able to accomplish anything today, at least we can still have lots of fun at the banquet!",
  ui_story_5051_50510101_84_dialog_content = "Besides, I'm sure there will be plenty of opportunities in the future too!",
  ui_story_5051_50510101_85_dialog_content = "PlayerName... Thank you!",
  ui_story_5051_50510101_86_dialog_content = "(I still have plenty of questions about all of this.)",
  ui_story_5051_50510101_87_dialog_content = "(But Mia seems really intent on talking to Carleen. At the very least, I should introduce them to one another.)",
  ui_story_5051_50510101_88_dialog_content = "(Still, I can't help but notice that she only wants to see Carleen. Why didn't she ask about the City Lord...?)",
  ui_story_5051_50510101_89_dialog_content = "<size=45>Sorry I'm late!</size>",
  ui_story_5051_50510101_90_dialog_content = "Hey!",
  ui_story_5051_50510101_91_dialog_content = "Wh-Who are you?!",
  ui_story_5051_50510101_92_dialog_content = "My, oh my! Umbraton is full of all kinds of bizarre and interesting things!",
  ui_story_5051_50510101_93_dialog_content = "Though to be fair, I've been amazed by almost everything ever since I left Northland!",
  ui_story_5051_50510101_94_dialog_content = "I got so enchanted by the sights along the way, and before I knew it... I got lost! Heehee!",
  ui_story_5051_50510101_95_dialog_content = "But it's fine. My cute little crystal ball always finds the way!",
  ui_story_5051_50510101_96_dialog_content = "Sure, it might sometimes lead me right off a cliff...",
  ui_story_5051_50510101_97_dialog_content = "But traveling is all about excitement and thrills! At least that's what Lady Jeriah says!",
  ui_story_5051_50510101_98_dialog_content = "Now what was I talking about just now? Oh right, Umbraton!",
  ui_story_5051_50510101_99_dialog_content = "The streets in Umbraton look like a complicated mess, but they follow their own principles.",
  ui_story_5051_50510101_X99_dialog_content = "People here who understand those principles know exactly where to place their shops for prosperity.",
  ui_story_5051_50510101_100_dialog_content = "Ah, I heard that from travelers I met on the way.",
  ui_story_5051_50510101_101_dialog_content = "I'd love to learn more sometime when I'm free... Hey, what's that flying thing?!",
  ui_story_5051_50510101_102_dialog_content = "Um, pardon me...",
  ui_story_5051_50510101_103_dialog_content = "Who are you again?",
  ui_story_5051_50510101_104_dialog_content = "Whoops! Silly me, I forgot to introduce myself!",
  ui_story_5051_50510101_105_dialog_content = "My name is <color=#FFB400>Jakine</color>. I'm the envoy from Northland!",
  ui_story_5051_50510101_106_dialog_content = "Sorry for being a little tardy, but you know what they say: the greatest heroes are always fashionably late!",
  ui_story_5051_50510101_107_dialog_content = "<size=45>... I think you've far exceeded what one would consider \"fashionably\" late!</size>",
  ui_story_5051_50510101_X107_dialog_content = "Well, you know what they say. The protagonist always shows up last!",
  ui_story_5051_50510101_X108_dialog_content = "Ahem, good evening, lords and ladies!",
  ui_story_5051_50510101_X109_dialog_content = "Tonight, we've gathered here under one roof...",
  ui_story_5051_50510101_X110_dialog_content = "For the once-a-year banquet.",
  ui_story_5051_50510101_X111_dialog_content = "Enjoy the sumptuous meal.",
  ui_story_5051_50510101_X112_dialog_content = "But even though the servings will eventually satiate.",
  ui_story_5051_50510101_X113_dialog_content = "And the libations will run out.",
  ui_story_5051_50510101_X114_dialog_content = "We can still mingle and carouse.",
  ui_story_5051_50510101_X115_dialog_content = "While enjoying the delightful entertainment.",
  ui_story_5051_50510101_108_dialog_content = "Greetings, esteemed guests.",
  ui_story_5051_50510101_109_dialog_content = "We are the Keating Choir,",
  ui_story_5051_50510101_110_dialog_content = "and now we're going to sing a song.",
  ui_story_5051_50510101_111_dialog_content = "We call it, \"Ode to Lumopolis.\"",
  ui_story_5051_50510101_112_dialog_content = "We hope you enjoy it!",
  ui_story_5051_50510101_113_dialog_content = "The sun and the stars rise into the sky! ♪",
  ui_story_5051_50510101_114_dialog_content = "Shining their light on a throne so high! ♪",
  ui_story_5051_50510101_115_dialog_content = "Our unwavering shield! ♪",
  ui_story_5051_50510101_116_dialog_content = "Our unstoppable spear! ♪",
  ui_story_5051_50510101_117_dialog_content = "Glory and nobility, a testament of faith! ♪",
  ui_story_5051_50510101_118_dialog_content = "Resounding splendor, to drive the darkness away! ♪",
  ui_story_5051_50510101_119_dialog_content = "A castle on high that shall always remain! ♪",
  ui_story_5051_50510101_120_dialog_content = "A font of sweet memories! ♪",
  ui_story_5051_50510101_121_dialog_content = "The object of our praise! ♪",
  ui_story_5051_50510101_122_dialog_content = "Its radiance defeats the darkness, ♪",
  ui_story_5051_50510101_123_dialog_content = "And brings us endless, joyous days! ♪",
  ui_story_5051_50510101_124_dialog_content = "White Night up high! Thank you, everyone.",
  ui_story_5051_50510101_125_dialog_content = "Wow, nice, what a great song!",
  ui_story_5051_50510101_X125_dialog_content = "These kids have a special talent for the arts!",
  ui_story_5051_50510101_126_dialog_content = "They really know how to clean up and put on a good show, huh?",
  ui_story_5051_50510101_127_dialog_content = "Naturally. Otherwise who would invite them to an occasion as important as this?",
  ui_story_5051_50510101_128_dialog_content = "If only they could be this well-behaved all the time...",
  ui_story_5051_50510101_129_dialog_content = "...",
  ui_story_5051_50510101_130_dialog_content = "Hmm? Ooh, I guess Michael agrees!",
  ui_story_5051_50510101_131_dialog_content = "\"Resounding splendor, to drive the darkness away. A castle on high that shall always remain.\"",
  ui_story_5051_50510101_132_dialog_content = "—The Darkover Crisis.",
  ui_story_5051_50510101_133_dialog_content = "That nightmarish catastrophe is but a part of our history now.",
  ui_story_5051_50510101_134_dialog_content = "The Darkover Crisis... Father... Mother...",
  ui_story_5051_50510101_135_dialog_content = "Ah! Stop it, stop it, stop it! This is supposed to be a happy banquet, so no more gloomy thoughts!",
  ui_story_5051_50510101_136_dialog_content = "...",
  ui_story_5051_50510101_137_dialog_content = "See? Even Michael's nodding in agreement!",
  ui_story_5051_50510101_138_dialog_content = "Forgive me, Uriel. I misspoke just now.",
  ui_story_5051_50510101_139_dialog_content = "It's fine, I'm used to this kind of pain. What I'm not used to is banquets.",
  ui_story_5051_50510101_140_dialog_content = "Y-Yeah, no kidding! It's so stuffy in here with all of these people!",
  ui_story_5051_50510101_141_dialog_content = "Come on, let's go get some ice cream!",
  ui_story_5051_50510101_142_dialog_content = "<size=30>Don't just stand there, Michael! Help me with Uriel!</size>",
  ui_story_5051_50510101_143_dialog_content = "...",
  ui_story_5051_50510101_144_dialog_content = "My, what naughty children. I look away for a second and they're nowhere to be seen.",
  ui_story_5051_50510101_145_dialog_content = "But the suffering it has brought is still as indelible and persistent as before.",
  ui_story_5051_50510101_146_dialog_content = "Those who survived the ordeal have no way of letting go of that pain. Even the powerful Four Angels are no exception.",
  ui_story_5051_50510101_147_dialog_content = "Come now, Irridon! Why don't you cheer up a little?",
  ui_story_5051_50510101_148_dialog_content = "Tonight's banquet won't be a long one.",
  ui_story_5051_50510101_149_dialog_content = "Keep moping around like this, and you'll miss the rest of it!",
  ui_story_5051_50510101_150_dialog_content = "Schwartz Family Day was originally a commemoration of the many achievements of the Schwartz family.",
  ui_story_5051_50510101_151_dialog_content = "On this day <color=#FFB400>twelve years ago</color>, the current city lord overcame a series of perilous situations, ultimately proving the Schwartz family's power to all of Lumopolis.",
  ui_story_5051_50510101_152_dialog_content = "But ever since the Darkover Crisis, the celebration banquet has been reduced in both size and grandeur.",
  ui_story_5051_50510101_153_dialog_content = "I still recall a time when marching bands and parade floats were the norm for this holiday.",
  ui_story_5051_50510101_154_dialog_content = "Is that so? I don't remember all that clearly.",
  ui_story_5051_50510101_155_dialog_content = "But I recall that people complain about Schwartz Family Day every year.",
  ui_story_5051_50510101_156_dialog_content = "What were their words again... Oh, right.",
  ui_story_5051_50510101_157_dialog_content = "\"An occasion like this demands a proper celebration, one that conveys the loyalty and respect of Lumopolis' young talents to their city lord,\" or something like that!",
  ui_story_5051_50510101_158_dialog_content = "Which is why a less-ostentatious version of the banquet was ultimately preserved.",
  ui_story_5051_50510101_159_dialog_content = "I fully agree with the City Lord's decision to keep things simple. In terms of labor and monetary costs, this is a much more reasonable choice.",
  ui_story_5051_50510101_160_dialog_content = "But a celebration does give many hard-working people a chance to get some much-needed rest.",
  ui_story_5051_50510101_161_dialog_content = "And to catch up on the latest gossip!",
  ui_story_5051_50510101_162_dialog_content = "That's not necessary.",
  ui_story_5051_50510101_163_dialog_content = "Are we allowed to go in now?",
  ui_story_5051_50510101_164_dialog_content = "Of course we are!",
  ui_story_5051_50510101_165_dialog_content = "By the way, why didn't we go inside while the choir was singing?",
  ui_story_5051_50510101_166_dialog_content = "Everyone was quietly enjoying the choir's performance, so I didn't want to distract anyone by barging in. It would've been rude.",
  ui_story_5051_50510101_167_dialog_content = "Huh? Is that a thing?",
  ui_story_5051_50510101_168_dialog_content = "Well... yes... interrupting a performance is quite rude.",
  ui_story_5051_50510101_169_dialog_content = "Mia, if you were wearing this outfit when you told me that you were Carleen's older sister...",
  ui_story_5051_50510101_170_dialog_content = "I totally would've believed you in an instant.",
  ui_story_5051_50510101_171_dialog_content = "You look exactly like a Lumopolis princess right now!",
  ui_story_5051_50510101_172_dialog_content = "Th-This is just a normal dress. I'm only dressing up to look the part for the banquet...",
  ui_story_5051_50510101_173_dialog_content = "That's three times now! You've said the exact same thing three times on the way here!",
  ui_story_5051_50510101_174_dialog_content = "Would you stop ogling her like a creep?",
  ui_story_5051_50510101_175_dialog_content = "I-I wasn't ogling! I'm just that amazed, is all!",
  ui_story_5051_50510101_176_dialog_content = "I don't buy it! Besides, didn't you promise that other girl that you would take her to the banquet? The one in the purple dress?",
  ui_story_5051_50510101_177_dialog_content = "How could you ditch her for another girl so easily?!",
  ui_story_5051_50510101_178_dialog_content = "What are you talking about? The girl in the purple dress back on the Colossus was Mia! She's just wearing a white dress now!",
  ui_story_5051_50510101_179_dialog_content = "Are you kidding me? I couldn't even tell! What kind of magical Luminatics did she use?!",
  ui_story_5051_50510101_180_dialog_content = "Huh?! Wh-Why are you getting so close, all of a sudden...?",
  ui_story_5051_50510101_181_dialog_content = "You were with us the entire time! How could you fail to notice?!",
  ui_story_5051_50510101_182_dialog_content = "Heehee, guess I was too distracted by the views of Lumopolis!",
  ui_story_5051_50510101_183_dialog_content = "Shouldn't we go inside now, you two...?",
  ui_story_5051_50510101_184_dialog_content = "Y-Yeah, you're right.",
  ui_story_5051_50510101_185_dialog_content = "We should check our gifts, just to be safe. We all remembered to bring one, right?",
  ui_story_5051_50510101_186_dialog_content = "But of course! As the Queen's envoy, I brought quite an unforgettable gift!",
  ui_story_5051_50510101_187_dialog_content = "I brought one too, but...",
  ui_story_5051_50510101_188_dialog_content = "(A jar of dandelion honey might be too shabby for this kind of event...)",
  ui_story_5051_50510101_189_dialog_content = "(It's the best batch of the year, but it just doesn't seem to fit in this mansion.)",
  ui_story_5051_50510101_190_dialog_content = "That jar of honey looks amazing. I bet it would taste great with a cup of tea.",
  ui_story_5051_50510101_191_dialog_content = "Who knows? It might even start a new trend among the nobles!",
  ui_story_5051_50510101_192_dialog_content = "(Mia saw right through me! She's even trying to console me already!)",
  ui_story_5051_50510101_193_dialog_content = "I-I just hope the City Lord likes it. Anyway, I'm ready whenever you guys are! Let's go!",
  ui_story_5051_50510101_194_dialog_content = "To all of our respected guests, welcome to this year's Schwartz Family Day.",
  ui_story_5051_50510101_195_dialog_content = "Please prepare your invitations and sign in over here.",
  ui_story_5051_50510101_196_dialog_content = "Invitation, invitation... got mine right here! Now to just sign my name!",
  ui_story_5051_50510101_197_dialog_content = "Envoy from Northland? Yes, you appear to be on the list.",
  ui_story_5051_50510101_198_dialog_content = "For the safety of those around you, I ask that you please keep your pet under close supervision. Enjoy the banquet.",
  ui_story_5051_50510101_199_dialog_content = "Not a problem! Whisper is perfectly well-behaved, isn't that right?",
  ui_story_5051_50510101_200_dialog_content = "Hiss!",
  ui_story_5051_50510101_X200_dialog_content = "Please enjoy tonight's festivities.",
  ui_story_5051_50510101_X201_dialog_content = "Of course. Thanks!",
  ui_story_5051_50510101_201_dialog_content = "Here's my invitation.",
  ui_story_5051_50510101_202_dialog_content = "PlayerName of Eraveil. We are honored to have you here today.",
  ui_story_5051_50510101_203_dialog_content = "Thank you for sparing an evening of your time to join us for Schwartz Family Day. Please enjoy yourself tonight.",
  ui_story_5051_50510101_204_dialog_content = "Our servants are at your beck and call, should you require anything. We shall gladly offer you only our finest service.",
  ui_story_5051_50510101_205_dialog_content = "Hey, what gives? Why are they treating you like royalty instead? I thought I was the envoy from Northland!",
  ui_story_5051_50510101_206_dialog_content = "And I'm the last Caelestite!",
  ui_story_5051_50510101_207_dialog_content = "(I had no idea I was so well-respected around here!)",
  ui_story_5051_50510101_208_dialog_content = "Pardon me, miss, but who might you be? Do you have an invitation?",
  ui_story_5051_50510101_209_dialog_content = "!",
  ui_story_5051_50510101_210_dialog_content = "(Mia's comfortable enough with Jakine and me to talk to us, but she's still too shy to talk to strangers.)",
  ui_story_5051_50510101_211_dialog_content = "(She's been acting strange ever since we arrived, as if she's afraid of the people gathered here today.)",
  ui_story_5051_50510101_212_dialog_content = "Sh-She's my friend!",
  ui_story_5051_50510101_213_dialog_content = "I see. Any friend of yours needs no invitation.",
  ui_story_5051_50510101_214_dialog_content = "Please come in.",
  ui_story_5051_50510101_215_dialog_content = "(Did he really have to say it that way? Or is this just the way people talk in the upper class?)",
  ui_story_5051_50510101_216_dialog_content = "Thank you, PlayerName...",
  ui_story_5051_50510101_217_dialog_content = "Piece of cake! I got you.",
  ui_story_5051_50510101_218_dialog_content = "Tch! Everyone's so busy fawning over PlayerName that they've forgotten all about me!",
  ui_story_5051_50510101_219_dialog_content = "Pardon me, but you're Miss Jakine, the envoy from Northland?",
  ui_story_5051_50510101_220_dialog_content = "That's right! I'm the one and only, Queen of the North's newest messenger, Jakine!",
  ui_story_5051_50510101_221_dialog_content = "I see. So the rumors were true—Northland's new envoy has the same beautiful, crimson locks as her predecessor.",
  ui_story_5051_50510101_222_dialog_content = "Wait, you've met <color=#FFB400>Boaz</color> before? That's my mom, you know!",
  ui_story_5051_50510101_223_dialog_content = "Excellent...",
  ui_story_5051_50510101_224_dialog_content = "Allow me to introduce myself. I'm Caleb, a Lumopolis noble. Much like yourself, I'm here at Lord Schwartz's invitation.",
  ui_story_5051_50510101_225_dialog_content = "I was just on my way to see him. Would you care to accompany me?",
  ui_story_5051_50510101_226_dialog_content = "Well...",
  ui_story_5051_50510101_227_dialog_content = "We could talk about your mother on the way, if you'd like?",
  ui_story_5051_50510101_228_dialog_content = "R-Really? That's great!",
  ui_story_5051_50510101_X225_dialog_content = "Do you the honor? Mind putting that in plain language?",
  ui_story_5051_50510101_X226_dialog_content = "Hahaha... Simply put, the City Lord sent me specifically for you.",
  ui_story_5051_50510101_X227_dialog_content = "He sent people to come escort me?!",
  ui_story_5051_50510101_X228_dialog_content = "I knew it! How could a Northland envoy not have clout?",
  ui_story_5051_50510101_X229_dialog_content = "Hold on, let me tell my friends who came with me!",
  ui_story_5051_50510101_229_dialog_content = "Heehee! Check it out, PlayerName! This nice nobleman's taking me to see the City Lord! Buh-bye!",
  ui_story_5051_50510101_230_dialog_content = "Wait, where are you—and she's gone, just like that.",
  ui_story_5051_50510101_231_dialog_content = "She really is something else. How could she run off with a stranger like that, when Queen Bethlehem specifically asked me to accompany her?",
  ui_story_5051_50510101_X231_dialog_content = "(Well, I only came here because I didn't want to turn down the invite.)",
  ui_story_5051_50510101_X232_dialog_content = "(But since Mia is counting on me to reach out to her family, I can't let her down.)",
  ui_story_5051_50510101_X233_dialog_content = "Are you okay, Mia?",
  ui_story_5051_50510101_232_dialog_content = "I, uh...",
  ui_story_5051_50510101_233_dialog_content = "(Oh no, this place is full of Lumopolis nobles. It looks like Mia's already at her limit.)",
  ui_story_5051_50510101_234_dialog_content = "How about we find somewhere quiet for now?",
  ui_story_5051_50510101_235_dialog_content = "But I still have yet to see Carleen...",
  ui_story_5051_50510101_236_dialog_content = "Don't worry! For now, just stay here and rest. I promise I'll bring her to see you soon!",
  ui_story_5051_50510101_237_dialog_content = "PlayerName...",
  ui_story_5051_50510101_238_dialog_content = "There's a reception room to the left...",
  ui_story_5051_50510101_239_dialog_content = "To the left! Got it!",
  ui_story_5051_50510101_240_dialog_content = "The door opens towards the other side. There's no use pulling on it...",
  ui_story_5051_50510101_241_dialog_content = "Oh, right! And there we go!",
  ui_story_5051_50510101_X238_dialog_content = "There are three doors. The reception room door has two white vases by it...",
  ui_story_5051_50510101_X239_dialog_content = "When Carleen was young, she inadvertently scratched the door frame...",
  ui_story_5051_50510101_X240_dialog_content = "Make a left out of the door... You're right, there are three doors here.",
  ui_story_5051_50510101_X241_dialog_content = "The one with two white vases by it is... the leftmost door.",
  ui_story_5051_50510101_X242_dialog_content = "Yeah, it's the reception room for sure!",
  ui_story_5051_50510101_X243_dialog_content = "(There's a rather inconspicuous scratch on the inner part of the door, just like Mia said.)",
  ui_story_5051_50510101_242_dialog_content = "(Mia seems awfully familiar with this place. It's as if she's been here before.)",
  ui_story_5051_50510101_243_dialog_content = "(Could she actually be a princess of Lumopolis...?)",
  ui_story_5051_50510201_1_dialog_content = "The choir's rendition of Ode to Lumopolis is now finished.",
  ui_story_5051_50510201_2_dialog_content = "The rest of the performances tonight are mostly songs and dances presented by talented young nobles.",
  ui_story_5051_50510201_3_dialog_content = "Many of our distinguished guests are hoping that you'll make an appearance and enjoy them.",
  ui_story_5051_50510201_4_dialog_content = "A number of them would also like to make changes to tonight's program.",
  ui_story_5051_50510201_5_dialog_content = "\"My son's instrument solo should be the finale,\" \"My daughter's dance needs to be postponed until we find a suitable background for it,\" and so on.",
  ui_story_5051_50510201_6_dialog_content = "I've already taken care of these requests in a... fitting manner. Would you care to take a look?",
  ui_story_5051_50510201_7_dialog_content = "It is fine, I trust you.",
  ui_story_5051_50510201_8_dialog_content = "Thank you for taking care of the banquet's planning and security in Carleen's absence.",
  ui_story_5051_50510201_9_dialog_content = "It is supposed to be Carleen's duty to organize Family Day.",
  ui_story_5051_50510201_10_dialog_content = "But all these years, she's always chosen to ignore it.",
  ui_story_5051_50510201_11_dialog_content = "To me, today is the day Mother passed away.",
  ui_story_5051_50510201_12_dialog_content = "I couldn't be with her during her final moments, so I won't remain in the city now.",
  ui_story_5051_50510201_13_dialog_content = "She says the same thing every year, and then she disappears from Lumopolis.",
  ui_story_5051_50510201_14_dialog_content = "Though she wasn't with her for very long, the loss of her mother still pains her to this day.",
  ui_story_5051_50510201_15_dialog_content = "Is it your belief that Lady Carleen lacks maturity?",
  ui_story_5051_50510201_16_dialog_content = "On the contrary, all this is rooted in foolish mistakes I made in my youth.",
  ui_story_5051_50510201_17_dialog_content = "I'm merely reaping what I sowed.",
  ui_story_5051_50510201_18_dialog_content = "You place too much blame on yourself.",
  ui_story_5051_50510201_19_dialog_content = "We're only mortal, my lord. All we can do is strive to achieve greatness with the small amount of time given to us.",
  ui_story_5051_50510201_20_dialog_content = "You need only look at the current state of Lumopolis to see what you have achieved.",
  ui_story_5051_50510201_21_dialog_content = "Without you, even the best guides would have no way of presenting the glory of Lumopolis to its many visitors.",
  ui_story_5051_50510201_22_dialog_content = "I couldn't have said it better myself, Ms. Blanc!",
  ui_story_5051_50510201_23_dialog_content = "Or, judging by your attire, should I call you the venerable Ms. Rot instead?",
  ui_story_5051_50510201_24_dialog_content = "Hello, Duke Otto. Today's banquet is a celebration of Lord Schwartz and his many achievements.",
  ui_story_5051_50510201_25_dialog_content = "My role is small, and does not merit any praise. You may address me as you please.",
  ui_story_5051_50510201_26_dialog_content = "Small, you say? Hahaha! You have quite the sense of humor, Ms. Rot of the Nightwatch.",
  ui_story_5051_50510201_27_dialog_content = "Forgive me for being late, my lord. I pray that I didn't interrupt your reminiscing?",
  ui_story_5051_50510201_28_dialog_content = "There's no need to observe the usual formalities tonight. You need only enjoy the banquet.",
  ui_story_5051_50510201_29_dialog_content = "But that won't do at all, my lord. After all, tonight commemorates your grand contributions to our fair Lumopolis.",
  ui_story_5051_50510201_30_dialog_content = "A pity that the people closest to you fail to see it that way.",
  ui_story_5051_50510201_31_dialog_content = "This must be what it means to be \"lonely at the top of the mountain.\"",
  ui_story_5051_50510201_32_dialog_content = "But you must know the feeling as well, Otto.",
  ui_story_5051_50510201_33_dialog_content = "After all, you've sacrificed so much over the years for the sake of the Troy family and the Elder Council.",
  ui_story_5051_50510201_34_dialog_content = "You flatter me, my lord. My achievements are nothing compared to your own.",
  ui_story_5051_50510201_35_dialog_content = "My son will be delivering a speech after the current performance ends. He would be honored if you were there to hear it.",
  ui_story_5051_50510201_36_dialog_content = "Unfortunately, an honored guest has requested an audience with me.",
  ui_story_5051_50510201_37_dialog_content = "However, I'm certain that your son's little talent show will not go unappreciated by tonight's guests.",
  ui_story_5051_50510201_38_dialog_content = "For now, my presence is required elsewhere.",
  ui_story_5051_50510201_39_dialog_content = "My lord, a servant is here with the guest who requested to see you.",
  ui_story_5051_50510201_40_dialog_content = "We were just talking about it too. Please enjoy the banquet, Otto.",
  ui_story_5051_50510201_41_dialog_content = "Very well, my lord.",
  ui_story_5051_50510201_42_dialog_content = "... This is why I always say that dragons are such a magical race!",
  ui_story_5051_50510201_43_dialog_content = "They fit in the palm of your hand when they're young, but then they grow up to be as big as a Colossus!",
  ui_story_5051_50510201_44_dialog_content = "Now that I think about it, dragons and Colossi kinda look alike. Could they be related somehow?",
  ui_story_5051_50510201_45_dialog_content = "Ahem, Miss Jakine?",
  ui_story_5051_50510201_46_dialog_content = "Yeah, what is it?",
  ui_story_5051_50510201_47_dialog_content = "I was told that your predecessor, Lady Boaz, was quite the master of divination.",
  ui_story_5051_50510201_48_dialog_content = "I have always been captivated by Northland's divination arts. Do you have any knowledge on the subject, by chance?",
  ui_story_5051_50510201_49_dialog_content = "Of course I do! In fact, I'm a master of—",
  ui_story_5051_50510201_50_dialog_content = "*Ahem* Y-yes, I dabble a bit in divination.",
  ui_story_5051_50510201_51_dialog_content = "Queen Bethlehem sent me here specifically to replenish the <color=#FFB400>Crystal of Eternal Memory</color> with water from Lake Mirror.",
  ui_story_5051_50510201_52_dialog_content = "I believe I've heard of this object before.",
  ui_story_5051_50510201_53_dialog_content = "But why does this Crystal of Eternal Memory require water from Lake Mirror?",
  ui_story_5051_50510201_54_dialog_content = "I was under the impression that it was merely a vessel for storing Lumina...",
  ui_story_5051_50510201_55_dialog_content = "Greetings, Miss Jakine. I've found you at last.",
  ui_story_5051_50510201_56_dialog_content = "Oh, hello!",
  ui_story_5051_50510201_57_dialog_content = "<size=30>Psst! Who's this lady supposed to be, Mr. Caleb?</size>",
  ui_story_5051_50510201_58_dialog_content = "It's been a long time, Ms. Blanc.",
  ui_story_5051_50510201_59_dialog_content = "It has been quite some time, yes. I do believe this is my first time seeing you at the Family Day banquet. Thank you for gracing us with your attendance.",
  ui_story_5051_50510201_60_dialog_content = "This is Ms. Blanc. Think of her as a personal assistant to the City Lord himself.",
  ui_story_5051_50510201_61_dialog_content = "Right...",
  ui_story_5051_50510201_62_dialog_content = "Miss Jakine, Lord Schwartz is waiting for you in the reception room. This way, please.",
  ui_story_5051_50510201_63_dialog_content = "H-How do you do! I'm Jakine, Queen Bethlehem's envoy!",
  ui_story_5051_50510201_64_dialog_content = "It's been over twelve years since an emissary from the north has come to visit Lumopolis!",
  ui_story_5051_50510201_65_dialog_content = "By order of Her Majesty, I have come to replenish the Crystal of Eternal Memory with <color=#FFB400>water from Lake Mirror</color>.",
  ui_story_5051_50510201_66_dialog_content = "Thank you for coming here today, envoy of Northland.",
  ui_story_5051_50510201_67_dialog_content = "Her Majesty has already apprised me of the details. On behalf of Lumopolis, I thank you for traveling so far to carry out your mission.",
  ui_story_5051_50510201_68_dialog_content = "All in a day's work! It's my responsibility, after all!",
  ui_story_5051_50510201_69_dialog_content = "Ms. Rot, could you please bring us the Crystal of Eternal Memory?",
  ui_story_5051_50510201_70_dialog_content = "As you wish.",
  ui_story_5051_50510201_71_dialog_content = "...",
  ui_story_5051_50510201_72_dialog_content = "As I recall, I specifically asked Ms. Rot to receive Northland's envoy today.",
  ui_story_5051_50510201_73_dialog_content = "Did you perhaps make friends with the envoy during the banquet, Caleb?",
  ui_story_5051_50510201_74_dialog_content = "Forgive me, my lord.",
  ui_story_5051_50510201_75_dialog_content = "As a member of the Magnus family, I simply thought that I had a duty to uphold. After all, this involves a <color=#FFB400>relic of my sister's</color>.",
  ui_story_5051_50510201_76_dialog_content = "I had no idea you would object to my presence like this.",
  ui_story_5051_50510201_77_dialog_content = "(A relic of his sister's? The Magnus family? What are these guys talking about?! And why does the atmosphere feel so awkward all of a sudden?!)",
  ui_story_5051_50510201_78_dialog_content = "(I screwed up, PlayerName, Mia...)",
  ui_story_5051_50510201_X78_dialog_content = "(I shouldn't have gone on my own to complete this mission... Someone come save me!)",
  ui_story_5051_50510201_79_dialog_content = "My lord, I invited Mr. Caleb here today.",
  ui_story_5051_50510201_80_dialog_content = "He wished to seek your audience over a certain matter. As you'll be quite busy later this evening, I thought it best to let him come here and speak his mind.",
  ui_story_5051_50510201_81_dialog_content = "As a member of your family, he deserves to be prioritized, I'd imagine.",
  ui_story_5051_50510201_82_dialog_content = "Ms. Rot... Sometimes, I think you are too good at your job.",
  ui_story_5051_50510201_83_dialog_content = "Thank you for your praise.",
  ui_story_5051_50510201_84_dialog_content = "Here is the Crystal of Eternal Memory. Thank you once again for your help.",
  ui_story_5051_50510201_85_dialog_content = "Alright, just leave it to me!",
  ui_story_5051_50510201_86_dialog_content = "(I-I'm saved! Oh, thank you, Ms. Blanc!)",
  ui_story_5051_50510201_87_dialog_content = "Mr. Caleb, this Umbraton wine was given to us by a certain guest tonight.",
  ui_story_5051_50510201_88_dialog_content = "It has a very special calming effect. Please have a glass.",
  ui_story_5051_50510201_89_dialog_content = "... Thank you.",
  ui_story_5051_50510201_90_dialog_content = "If I'm not mistaken, Caleb, your reason for coming here today is the Crystal of Eternal Memory. Am I correct?",
  ui_story_5051_50510201_91_dialog_content = "This special <color=#FFB400>recording device</color> was given to me and Joshua by the Queen of the North as a gift.",
  ui_story_5051_50510201_92_dialog_content = "Twelve years ago, it was my wife, your sister, who activated it on her own.",
  ui_story_5051_50510201_93_dialog_content = "But all it contains are a few scattered memories from that year.",
  ui_story_5051_50510201_94_dialog_content = "I simply took care of it after she passed, but I had no intention of keeping it for myself.",
  ui_story_5051_50510201_95_dialog_content = "If the Queen wants it back, I would not object.",
  ui_story_5051_50510201_96_dialog_content = "... Do the memories of your wife and daughters really mean so little to you?",
  ui_story_5051_50510201_97_dialog_content = "H-Her Majesty never said anything about taking it back, you know!",
  ui_story_5051_50510201_98_dialog_content = "Besides, the world within the crystal is powered by the Lumina of the person who activated it. Queen Bethlehem would have no use for it!",
  ui_story_5051_50510201_99_dialog_content = "The world within the crystal?",
  ui_story_5051_50510201_100_dialog_content = "That's right! The Crystal of Eternal Memory is no ordinary recording device!",
  ui_story_5051_50510201_101_dialog_content = "There's an entirely <color=#FFB400>real world</color> preserved inside of it!",
  ui_story_5051_50510201_102_dialog_content = "But how is that possible?",
  ui_story_5051_50510201_103_dialog_content = "I guess you're not all that familiar with it, Mr. Caleb.",
  ui_story_5051_50510201_104_dialog_content = "Allow me to explain how it works!",
  ui_story_5051_50510201_105_dialog_content = "First, the Crystal of Eternal Memory requires a sufficient amount of Lake Mirror's water to operate properly.",
  ui_story_5051_50510201_106_dialog_content = "Once ready, the crystal must be activated by infusing it with the user's Lumina.",
  ui_story_5051_50510201_107_dialog_content = "Afterward, the crystal will begin recording everything that happens in <color=#FFB400>a single day</color>, within a certain radius.",
  ui_story_5051_50510201_108_dialog_content = "It's preserved in the Crystal of Eternal Memory, forever looping in an endless reenactment.",
  ui_story_5051_50510201_109_dialog_content = "By infusing it with Lumina once again, users can enter the crystal's world and experience the memory themselves!",
  ui_story_5051_50510201_110_dialog_content = "And that's basically how the Crystal of Eternal Memory and its pocket universe works.",
  ui_story_5051_50510201_111_dialog_content = "But there's a catch! The crystal is extremely fragile...",
  ui_story_5051_50510201_112_dialog_content = "Once inside, users must keep themselves hidden and avoid interacting with anyone or anything at all costs.",
  ui_story_5051_50510201_113_dialog_content = "<size=42>Otherwise, even the smallest of changes to the established story could result in an unimaginable catastrophe!</size>",
  ui_story_5051_50510201_114_dialog_content = "So this is what Northland's enigmatic Luminatics are like...",
  ui_story_5051_50510201_115_dialog_content = "<size=30>How obnoxiously complicated.</size>",
  ui_story_5051_50510201_116_dialog_content = "Phew! There we go, the crystal is now full of water and ready to go!",
  ui_story_5051_50510201_117_dialog_content = "Here you go, Lord Schwartz.",
  ui_story_5051_50510201_118_dialog_content = "You can use it whenever you want now!",
  ui_story_5051_50510201_119_dialog_content = "You have my gratitude, envoy.",
  ui_story_5051_50510201_120_dialog_content = "But unfortunately... The person who activated it is no longer with us.",
  ui_story_5051_50510201_121_dialog_content = "Before she left us, no one was willing to revisit the past recorded within the crystal.",
  ui_story_5051_50510201_122_dialog_content = "And now that she's gone, I have no right to wallow in my own remorse once more.",
  ui_story_5051_50510201_123_dialog_content = "I am afraid no one is able to activate it again.",
  ui_story_5051_50510201_124_dialog_content = "Err...",
  ui_story_5051_50510201_125_dialog_content = "Th-That's okay! As a practitioner of divination from Northland, I'm sure I can find another way to use it!",
  ui_story_5051_50510201_126_dialog_content = "Let me see... The incantation goes something like this...",
  ui_story_5051_50510201_127_dialog_content = "...",
  ui_story_5051_50510201_128_dialog_content = "Let me see, the incantation goes something like this...",
  ui_story_5051_50510201_129_dialog_content = "Joshua, didn't we agree to learn how to use the Crystal of Eternal Memory together?",
  ui_story_5051_50510201_130_dialog_content = "I know how much you love learning, but when you rush into things like this, I can't help but feel a bit left behind.",
  ui_story_5051_50510201_131_dialog_content = "Oh? I had no idea I could make you feel so lonely.",
  ui_story_5051_50510201_132_dialog_content = "I thought I was the only one who had to suffer such an emotion.",
  ui_story_5051_50510201_133_dialog_content = "Forgive me, my love. I've been so busy with my work that I've neglected you and the girls.",
  ui_story_5051_50510201_134_dialog_content = "Heheh. I'm only teasing you.",
  ui_story_5051_50510201_135_dialog_content = "It's only thanks to your efforts that we have the peace and prosperity needed to feel all kinds of emotions.",
  ui_story_5051_50510201_136_dialog_content = "Joy, excitement, love... And loneliness too.",
  ui_story_5051_50510201_137_dialog_content = "But now, I have this gift from the Queen of the North.",
  ui_story_5051_50510201_138_dialog_content = "If I ever feel lonely, I can always come to find you inside this Crystal of Eternal Memory.",
  ui_story_5051_50510201_139_dialog_content = "Joshua...",
  ui_story_5051_50510201_140_dialog_content = "So please just let me activate it?",
  ui_story_5051_50510201_141_dialog_content = "Very well, my dear. As long as it makes you happy.",
  ui_story_5051_50510201_142_dialog_content = "Have you decided which day you want to record?",
  ui_story_5051_50510201_143_dialog_content = "<color=#FFB400>Veronica's</color> birthday? Or maybe Carleen's first performance? Or perhaps...",
  ui_story_5051_50510201_144_dialog_content = "It's a secret!",
  ui_story_5051_50510201_145_dialog_content = "Won't you please just tell me? I'd rather not make a fool of myself when you decide to activate it.",
  ui_story_5051_50510201_146_dialog_content = "Heavens, I didn't know the City Lord of Lumopolis was capable of making a fool of himself!",
  ui_story_5051_50510201_147_dialog_content = "Of course I am... Remember when I accidentally stepped on Carleen's toy and broke it?",
  ui_story_5051_50510201_148_dialog_content = "I didn't think she cared very much at the time, since she hardly reacted when it happened. Little did I know she spent the rest of the day crying in her bedroom...",
  ui_story_5051_50510201_149_dialog_content = "Oh yes, I remember you standing outside her door with a new toy, not daring to go inside. The look on your face scared more than a few of our servants.",
  ui_story_5051_50510201_150_dialog_content = "Are there any other instances that come to mind?",
  ui_story_5051_50510201_151_dialog_content = "... There was the time I left the rose wreath Veronica gifted me in the reception room.",
  ui_story_5051_50510201_152_dialog_content = "I was so busy with a guest that day that I carelessly left her gift on the table, not realizing she thought I didn't like it and tossed it aside...",
  ui_story_5051_50510201_153_dialog_content = "And then you ordered the gardeners to plant an entire garden of roses just for her.",
  ui_story_5051_50510201_154_dialog_content = "Unfortunately, our daughter's preoccupation with her training left her with neither the time nor the interest for weaving flower wreaths ever again...",
  ui_story_5051_50510201_155_dialog_content = "(Sighs)",
  ui_story_5051_50510201_156_dialog_content = "You didn't make a fool of yourself back then, my sweet Daniel.",
  ui_story_5051_50510201_157_dialog_content = "This world is both vast and complex, and we're so very limited in the things we can see and do.",
  ui_story_5051_50510201_158_dialog_content = "Which is why I believe this Crystal of Eternal Memory is such a wonderful thing... It offers us a chance to record those moments in our lives, and cherish them for as long as we live.",
  ui_story_5051_50510201_159_dialog_content = "Memories can be so unreliable, but with this crystal, our true selves will be preserved for all eternity.",
  ui_story_5051_50510201_160_dialog_content = "Good, bad, right, wrong... A day will come when our family feels lost and confused.",
  ui_story_5051_50510201_161_dialog_content = "When that day comes, this crystal will show us the <color=#FFB400>answers we need</color>. I'm sure of it.",
  ui_story_5051_50510201_162_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50510201_163_dialog_content = "...",
  ui_story_5051_50510201_164_dialog_content = "You there, hiding in the shadows. Show yourself.",
  ui_story_5051_50510201_165_dialog_content = "I-It's me, PlayerName! Sorry to interrupt! Hahaha...",
  ui_story_5051_50510201_166_dialog_content = "Let me see if I understand this correctly.",
  ui_story_5051_50510201_167_dialog_content = "You wanted to present the City Lord with your gift, so you barged into his reception room without asking.",
  ui_story_5051_50510201_168_dialog_content = "But when Lord Schwartz and his guests entered the room, you instinctively hid yourself instead of greeting anyone.",
  ui_story_5051_50510201_169_dialog_content = "Ever since then, you've been eavesdropping from behind the curtains.",
  ui_story_5051_50510201_170_dialog_content = "Is that correct?",
  ui_story_5051_50510201_171_dialog_content = "Er, yes, that's correct. Sorry...",
  ui_story_5051_50510201_172_dialog_content = "(I mean, I only did it because Mia's first reaction was to hide, so I just followed...)",
  ui_story_5051_50510201_173_dialog_content = "(We probably shouldn't have brought her here so soon... She's in no condition to meet new people right now.)",
  ui_story_5051_50510201_174_dialog_content = "I appreciate your honesty and good intentions, young one.",
  ui_story_5051_50510201_175_dialog_content = "But it is not righteous to eavesdrop.",
  ui_story_5051_50510201_176_dialog_content = "Don't let it happen again, understood?",
  ui_story_5051_50510201_177_dialog_content = "Understood. Thank you, sir...",
  ui_story_5051_50510201_178_dialog_content = "Now then, I have yet another question for you.",
  ui_story_5051_50510201_179_dialog_content = "Is the other person lurking in the shadows a friend of yours, as well?",
  ui_story_5051_50510201_180_dialog_content = "If not, Ms. Rot will dispose of them without hesitation.",
  ui_story_5051_50510201_X177_dialog_content = "Well then, allow me to ask you another question.",
  ui_story_5051_50510201_X178_dialog_content = "Is the mouse hiding under the table a friend of yours?",
  ui_story_5051_50510201_X179_dialog_content = "If not, I shall shoo it away.",
  ui_story_5051_50510201_181_dialog_content = "Ahahaha! S-She is!",
  ui_story_5051_50510201_182_dialog_content = "Come on out, Mia. Don't be afraid, these are all good people.",
  ui_story_5051_50510201_183_dialog_content = "W-Wait! My veil... I can't find my veil!",
  ui_story_5051_50510201_184_dialog_content = "A Lumopolis noble? But she looks...",
  ui_story_5051_50510201_185_dialog_content = "Oh...?",
  ui_story_5051_50510201_186_dialog_content = "...",
  ui_story_5051_50510201_187_dialog_content = "Is this yet another one of your surprises for me, Ms. Rot?",
  ui_story_5051_50510201_188_dialog_content = "Never mind, just clear my schedule before anything else happens.",
  ui_story_5051_50510201_189_dialog_content = "I'm terribly sorry, my lord. I'll go cancel the rest of your appointments for the day.",
  ui_story_5051_50510201_190_dialog_content = "Please do.",
  ui_story_5051_50510201_191_dialog_content = "So if I use this one... and combine it with this one... Bingo!",
  ui_story_5051_50510201_192_dialog_content = "I think I found the exact incantation we need right now!",
  ui_story_5051_50510201_193_dialog_content = "That won't be necessary. Please return to the banquet with PlayerName and enjoy yourselves.",
  ui_story_5051_50510201_194_dialog_content = "The three of us must speak in private...",
  ui_story_5051_50510201_195_dialog_content = "Ahem, Jakine, let's go first—Jakine?",
  ui_story_5051_50510201_196_dialog_content = "Ad praeteritum! Ad praeteritum! Ad praeteritum!",
  ui_story_5051_50510201_197_dialog_content = "Let us relive the golden days of the past!",
  ui_story_5051_50510201_198_dialog_content = "<size=45>Abrahadabra!</size>",
  ui_story_5051_50510201_199_dialog_content = "What in the...?",
  ui_story_5051_50510201_200_dialog_content = "<size=45>Wh-What's going on?!</size>",
  ui_story_5051_50510201_201_dialog_content = "Help me... PlayerName...",
  ui_story_5051_50510201_202_dialog_content = "Mia! Grab my hand!!",
  ui_story_5051_50510201_203_dialog_content = "Okay...!",
  ui_story_5051_50510201_204_dialog_content = "Ugh... Huh?",
  ui_story_5051_50510201_205_dialog_content = "Where am I...?",
  ui_story_5051_50510201_206_dialog_content = "Th-Thank goodness, you're finally awake!",
  ui_story_5051_50510201_207_dialog_content = "Mia, where are we?",
  ui_story_5051_50510201_208_dialog_content = "I don't know either... But we need to run! The Eclipsites are coming!",
  ui_story_5051_50510201_209_dialog_content = "—!!!",
  ui_story_5051_50510201_210_dialog_content = "Eclipsites?!",
  ui_story_5051_50510201_211_dialog_content = "This way, Mia! Hurry!",
  ui_story_5051_50510201_212_dialog_content = "B-But PlayerName, that way is also—",
  ui_story_5051_50510201_213_dialog_content = "—!!!",
  ui_story_5051_50510201_214_dialog_content = "We're surrounded!!",
  ui_story_5051_50510201_215_dialog_content = "B-Baba Yaga! Baba Yaga, help!!",
  ui_story_5051_50510201_216_dialog_content = "Baba Yaga? Why aren't you saying anything...?",
  ui_story_5051_50510201_217_dialog_content = "Drat... Whatever you do, Mia, don't leave my side!",
  ui_story_5051_50510201_218_dialog_content = "Bring it on, you filthy Eclipsites!",
  ui_story_5051_50510201_219_dialog_content = "<size=45>Gahhhh!</size>",
  ui_story_5051_50510201_220_dialog_content = "Please don't...",
  ui_story_5051_50510201_221_dialog_content = "No...",
  ui_story_5051_50510201_222_dialog_content = "<size=45>Don't you dare hurt PlayerName!!!</size>",
  ui_story_5051_50510201_223_dialog_content = "Graagh!?",
  ui_story_5051_50510201_224_dialog_content = "M-Mia...?",
  ui_story_5051_50510201_225_dialog_content = "Huff... huff...",
  ui_story_5051_50510201_226_dialog_content = "Did I... Did I just use... Luminatics?",
  ui_story_5051_50510201_227_dialog_content = "I had no idea you could use Luminatics too, Mia!",
  ui_story_5051_50510201_228_dialog_content = "I used to be able to... But that was a long time ago. I haven't been able to ever since...",
  ui_story_5051_50510201_229_dialog_content = "—!!!",
  ui_story_5051_50510201_230_dialog_content = "More Eclipsites?! Just how many of them are there?",
  ui_story_5051_50510201_231_dialog_content = "Can you still fight?",
  ui_story_5051_50510201_232_dialog_content = "I-I don't know...",
  ui_story_5051_50510201_233_dialog_content = "But if I don't fight, you'll be in danger.",
  ui_story_5051_50510201_234_dialog_content = "I have to protect you!",
  ui_story_5051_50510201_235_dialog_content = "You can do it, Mia!",
  ui_story_5051_50510201_236_dialog_content = "As long as you're able to use Luminatics, I can boost your power!",
  ui_story_5051_50510201_237_dialog_content = "Trust me, and trust in yourself!",
  ui_story_5051_50510201_238_dialog_content = "Trust you... And myself?",
  ui_story_5051_50510201_239_dialog_content = "Alright! I'll do my best!",
  ui_story_5051_50510301_1_dialog_content = "Are you all right?",
  ui_story_5051_50510301_2_dialog_content = "I'm fine. Even though I still feel shaken...",
  ui_story_5051_50510301_3_dialog_content = "I think I'm a little more confident now!",
  ui_story_5051_50510301_4_dialog_content = "You didn't get hurt in all the fighting, did you?",
  ui_story_5051_50510301_5_dialog_content = "Not at all, so don't worry about me!",
  ui_story_5051_50510301_6_dialog_content = "I gotta say, Mia, that was impressive! Not a lot of people can fight off that many Eclipsites on their own.",
  ui_story_5051_50510301_7_dialog_content = "R-Really? But it was all thanks to you, I think.",
  ui_story_5051_50510301_8_dialog_content = "The power of the Last Caelestite is really something...",
  ui_story_5051_50510301_9_dialog_content = "Speaking of, I haven't been able to sense anyone around us ever since I woke up.",
  ui_story_5051_50510301_10_dialog_content = "Where on earth are we? And where did everyone else go?",
  ui_story_5051_50510301_11_dialog_content = "Look over there, in the distance! It's <color=#FFB400>Lumopolis</color>!",
  ui_story_5051_50510301_12_dialog_content = "So does this mean we're on the <color=#FFB400>outskirts of Lumopolis</color>?",
  ui_story_5051_50510301_13_dialog_content = "How did we end up over here...?",
  ui_story_5051_50510301_14_dialog_content = "Could this be the world within the <color=#FFB400>Crystal of Eternal Memory</color>?",
  ui_story_5051_50510301_15_dialog_content = "I think you're probably right!",
  ui_story_5051_50510301_16_dialog_content = "Ad praeteritum! Ad praeteritum! Ad praeteritum!",
  ui_story_5051_50510301_17_dialog_content = "Let us relive the golden days of the past!",
  ui_story_5051_50510301_18_dialog_content = "Abrahadabra!",
  ui_story_5051_50510301_19_dialog_content = "I remember now... I guess Jakine really is a divination master, after all.",
  ui_story_5051_50510301_20_dialog_content = "But even so, it looks like she got way too ahead of herself this time.",
  ui_story_5051_50510301_21_dialog_content = "Yeah...",
  ui_story_5051_50510301_22_dialog_content = "I remember her mentioning something else too.",
  ui_story_5051_50510301_23_dialog_content = "\"Once inside, users must keep themselves hidden and avoid interacting with anyone or anything at all costs.\"",
  ui_story_5051_50510301_24_dialog_content = "\"Otherwise, even the smallest changes to the established story could result in an unimaginable catastrophe!\"",
  ui_story_5051_50510301_25_dialog_content = "Oh no... We just got into a fight with a bunch of Eclipsites!",
  ui_story_5051_50510301_26_dialog_content = "Are we gonna be okay...?",
  ui_story_5051_50510301_27_dialog_content = "<size=45>Aaaah!!</size>",
  ui_story_5051_50510301_28_dialog_content = "S-Someone's in trouble!",
  ui_story_5051_50510301_29_dialog_content = "Who's that...?",
  ui_story_5051_50510301_30_dialog_content = "Captain! There are too many Eclipsites, we can't hold out much longer...",
  ui_story_5051_50510301_31_dialog_content = "Focus, men! Even if your fellow soldiers fall before your eyes, don't you dare drop your weapons!",
  ui_story_5051_50510301_32_dialog_content = "Damn it all!!!",
  ui_story_5051_50510301_33_dialog_content = "A freight vehicle defended by Lumopolis soldiers... And they're being attacked by Eclipsites!",
  ui_story_5051_50510301_34_dialog_content = "But why are there so many Eclipsites outside of Lumopolis? Just what's going on?!",
  ui_story_5051_50510301_35_dialog_content = "W-We need to go rescue them!",
  ui_story_5051_50510301_36_dialog_content = "Wait! Jakine said we can't interfere with anything once inside the Crystal of Eternal Memory!",
  ui_story_5051_50510301_37_dialog_content = "If we take those Eclipsites on, there's no telling what the consequences will be!",
  ui_story_5051_50510301_38_dialog_content = "But...",
  ui_story_5051_50510301_39_dialog_content = "Resist until you are dragged into your grave!",
  ui_story_5051_50510301_40_dialog_content = "—?!",
  ui_story_5051_50510301_41_dialog_content = "The Lumopolis soldiers are safe now, sir. We can pull out at any time.",
  ui_story_5051_50510301_42_dialog_content = "I still don't understand why we're rescuing Schwartz's loyal dogs, considering he doesn't give a damn whether we live or die.",
  ui_story_5051_50510301_43_dialog_content = "Even on a holiday like this, he didn't offer us so much as a scrap of food or a place to rest. He just took our gifts and kicked us all out.",
  ui_story_5051_50510301_44_dialog_content = "What kind of City Lord is that?",
  ui_story_5051_50510301_45_dialog_content = "Don't let such small slights cloud your vision. When the time is right, the answer will be clear to you.",
  ui_story_5051_50510301_46_dialog_content = "It's <color=#FFB400>Uncle Istvan</color>...!",
  ui_story_5051_50510301_47_dialog_content = "Wait, that's Istvan?! He looks so young!",
  ui_story_5051_50510301_48_dialog_content = "What...?",
  ui_story_5051_50510301_49_dialog_content = "<color=#e8d9bb>Rumble—Crash!</color>",
  ui_story_5051_50510301_50_dialog_content = "(Thunder? Is it gonna storm in the middle of a clear day?)",
  ui_story_5051_50510301_51_dialog_content = "PlayerName! Look out!!",
  ui_story_5051_50510301_52_dialog_content = "Don't tell me there are more Eclipsites?!",
  ui_story_5051_50510301_53_dialog_content = "There's just no end to these monsters!",
  ui_story_5051_50510302_1_dialog_content = "Ha... Ha... Ha...",
  ui_story_5051_50510302_2_dialog_content = "I hope there are no more of them. I'm at my limit...",
  ui_story_5051_50510302_3_dialog_content = "Princess <color=#FFB400>Veronica</color>! Are you alright?",
  ui_story_5051_50510302_4_dialog_content = "Princess Veronica! It's really Princess Veronica!",
  ui_story_5051_50510302_5_dialog_content = "Why would you be here, Your Highness?!",
  ui_story_5051_50510302_6_dialog_content = "I, er, I'm fine.",
  ui_story_5051_50510302_7_dialog_content = "That's good to hear.",
  ui_story_5051_50510302_8_dialog_content = "But I must say, that display of strength and bravery was not like you at all.",
  ui_story_5051_50510302_9_dialog_content = "I didn't dare assume your identity earlier. Please forgive my ignorance, Your Highness.",
  ui_story_5051_50510302_10_dialog_content = "P-Please don't say that!",
  ui_story_5051_50510302_11_dialog_content = "Today is just a special occasion, is all.",
  ui_story_5051_50510302_12_dialog_content = "(Huh? What are you looking at me for, Mia?)",
  ui_story_5051_50510302_13_dialog_content = "I couldn't agree more, which is why I'm confused by your being out here in the first place.",
  ui_story_5051_50510302_14_dialog_content = "Then again... It's not my place to worry about such things. Please be more careful when setting foot outside the city, Your Highness.",
  ui_story_5051_50510302_15_dialog_content = "Th-Thank you for your concern.",
  ui_story_5051_50510302_16_dialog_content = "Lord Schwartz and I just finished our meeting some time ago. We were so busy that I had no time to chat with Lady Joshua.",
  ui_story_5051_50510302_17_dialog_content = "Please give her my most heartfelt apologies.",
  ui_story_5051_50510302_18_dialog_content = "And if at all possible... Please ask your father to give me his response as soon as he can.",
  ui_story_5051_50510302_19_dialog_content = "Very well... I'll be sure to deliver your messages to them. Thank you again for all of your help.",
  ui_story_5051_50510302_20_dialog_content = "I'm simply doing what's right, Your Highness. No thanks are necessary.",
  ui_story_5051_50510302_21_dialog_content = "(So Mia really is a princess!)",
  ui_story_5051_50510302_22_dialog_content = "Pardon me, young man.",
  ui_story_5051_50510302_23_dialog_content = "Me?",
  ui_story_5051_50510302_24_dialog_content = "Yes, you. I can only assume that you're a close friend of Her Highness, correct?",
  ui_story_5051_50510302_25_dialog_content = "Not just anyone can claim the honor of being protected by her, you know.",
  ui_story_5051_50510302_26_dialog_content = "You should rely on your own power to succeed in life.",
  ui_story_5051_50510302_27_dialog_content = "Rather than hiding behind someone else.",
  ui_story_5051_50510302_28_dialog_content = "O-Okay...",
  ui_story_5051_50510302_29_dialog_content = "Uh, pardon me, but have we met somewhere before?",
  ui_story_5051_50510302_30_dialog_content = "Hahaha! I wasn't expecting to hear that as your opening remark, my friend.",
  ui_story_5051_50510302_31_dialog_content = "The answer is no.",
  ui_story_5051_50510302_32_dialog_content = "But should you ever wish to meet again, feel free to visit me in Umbraton.",
  ui_story_5051_50510302_33_dialog_content = "Soon, it will become an empire of shadows.",
  ui_story_5051_50510302_34_dialog_content = "The shadows surround us all, but whether or not you can survive in them depends on your own strength.",
  ui_story_5051_50510302_35_dialog_content = "The shadows surround us all... How right you are.",
  ui_story_5051_50510302_36_dialog_content = "I'm sure Umbraton will become a much better place under your leadership, Uncle... I mean, Mr. Istvan.",
  ui_story_5051_50510302_37_dialog_content = "I'm honored to receive such words of praise from you, milady.",
  ui_story_5051_50510302_38_dialog_content = "It's getting late. We should be on our way now.",
  ui_story_5051_50510302_39_dialog_content = "Till next we meet, Princess Veronica. You as well, my interesting young friend.",
  ui_story_5051_50510302_40_dialog_content = "Take care... You know, this Istvan seems a lot nicer than the one I know.",
  ui_story_5051_50510302_41_dialog_content = "Not gonna lie, it feels pretty intriguing.",
  ui_story_5051_50510302_42_dialog_content = "That's right, I remember Uncle Istvan being much more cheery in the past too.",
  ui_story_5051_50510302_43_dialog_content = "But with everything that's happened since then... It's no surprise that everyone has changed so much.",
  ui_story_5051_50510302_44_dialog_content = "So you really are Princess Veronica, aren't you?",
  ui_story_5051_50510302_45_dialog_content = "When Istvan called you that, you answered as though it was the most normal thing in the world. It was completely different from your usual, shy responses.",
  ui_story_5051_50510302_46_dialog_content = "R-Really?",
  ui_story_5051_50510302_47_dialog_content = "I still haven't been able to piece all of my memories together. I can only recall tidbits of the past right now.",
  ui_story_5051_50510302_48_dialog_content = "But for some reason, when I saw Uncle Istvan's younger self...",
  ui_story_5051_50510302_49_dialog_content = "It's as if my body remembered the right speech and etiquette before my mind could catch up.",
  ui_story_5051_50510302_50_dialog_content = "Sorry, I know that doesn't make much sense.",
  ui_story_5051_50510302_51_dialog_content = "Don't worry about it! We came to find answers about your past, and a lot more has happened than we expected. It's normal for you to feel a little confused.",
  ui_story_5051_50510302_52_dialog_content = "Could you tell me more about Princess Veronica in your memories, Mia?",
  ui_story_5051_50510302_53_dialog_content = "Sure, no problem.",
  ui_story_5051_50510302_54_dialog_content = "Veronica was a <color=#FFB400>princess</color> of Lumopolis, as well as Lord Schwartz's <color=#FFB400>oldest daughter</color>.",
  ui_story_5051_50510302_55_dialog_content = "But many years ago, Lumopolis declared to the rest of the world that she had <color=#FFB400>passed away</color>...",
  ui_story_5051_50510302_56_dialog_content = "Passed away? But why?",
  ui_story_5051_50510302_57_dialog_content = "Because she had tarnished the Schwartz family's reputation.",
  ui_story_5051_50510302_58_dialog_content = "As a result of her disgrace, Veronica lost the right to continue living.",
  ui_story_5051_50510302_59_dialog_content = "Reputation? Disgrace? Are those things really important enough to cost someone their life?",
  ui_story_5051_50510302_60_dialog_content = "That's just how the nobility operates. To them, nothing is more important than maintaining their reputation...",
  ui_story_5051_50510302_61_dialog_content = "You know about <color=#FFB400>Lumina Summonings</color>, right PlayerName?",
  ui_story_5051_50510302_62_dialog_content = "Aside from Baba Yaga, I remember having another scary friend named Hippoca.",
  ui_story_5051_50510302_63_dialog_content = "He was my Lumina Summoning. As a child, I wanted to get stronger more than anything else, so I trained and trained as hard as I could...",
  ui_story_5051_50510302_64_dialog_content = "And the result of my training was Hippoca.",
  ui_story_5051_50510302_65_dialog_content = "But everyone disliked the way he looked. A spider with a horse's head... Everyone called him a monster.",
  ui_story_5051_50510302_66_dialog_content = "But the one who hated him the most... was my father. He would always say that Hippoca brought unwarranted criticism on our family.",
  ui_story_5051_50510302_67_dialog_content = "That Hippoca was an ill omen and that he should never have existed... Before long, I started to fear him, too.",
  ui_story_5051_50510302_68_dialog_content = "Hippoca was the manifestation of my own powers, yet I rejected him because of everyone's disapproval.",
  ui_story_5051_50510302_69_dialog_content = "In the end, I lost the ability to use Luminatics.",
  ui_story_5051_50510302_70_dialog_content = "And Baba Yaga, who shares some similarities with Hippoca, inherited my forfeited powers instead.",
  ui_story_5051_50510302_71_dialog_content = "In a way, I got exactly what I deserved.",
  ui_story_5051_50510302_72_dialog_content = "Poor Princess Veronica...",
  ui_story_5051_50510302_73_dialog_content = "But since everyone here is still calling you by that name, does this mean...",
  ui_story_5051_50510302_74_dialog_content = "Your Highness! How could we ever repay you for saving our lives?",
  ui_story_5051_50510302_75_dialog_content = "I-It was nothing, really.",
  ui_story_5051_50510302_76_dialog_content = "Is everyone alright?",
  ui_story_5051_50510302_77_dialog_content = "Put your mind at ease, Your Highness. Thanks to you, we only suffered minor injuries, and are ready to continue at any time.",
  ui_story_5051_50510302_78_dialog_content = "You and your friend are welcome to ride with us back to the city, if you wish?",
  ui_story_5051_50510302_79_dialog_content = "That would be wonderful, thank you.",
  ui_story_5051_50510302_80_dialog_content = "Uh, pardon me, but could you tell me what year it is?",
  ui_story_5051_50510302_81_dialog_content = "What year? It's <color=#FFB400>Morning Calendar Year 1988</color>. Why do you ask?",
  ui_story_5051_50510302_82_dialog_content = "(1988? So that means... This is <color=#FFB400>twelve years in the past</color>!)",
  ui_story_5051_50510302_83_dialog_content = "(If so, Eraveil would have been destroyed already.)",
  ui_story_5051_50510302_84_dialog_content = "(This means I still won't find any of my kin within this Crystal of Eternal Memory...)",
  ui_story_5051_50510302_85_dialog_content = "Is something wrong, PlayerName?",
  ui_story_5051_50510302_86_dialog_content = "It's nothing. Mia, could you come here for a second?",
  ui_story_5051_50510302_87_dialog_content = "Wh-What is it?",
  ui_story_5051_50510302_88_dialog_content = "It looks like the world within the crystal is <color=#FFB400>Lumopolis from twelve years ago</color>.",
  ui_story_5051_50510302_89_dialog_content = "If my hunch is right, the others who were in the reception room with us should have been transported here as well.",
  ui_story_5051_50510302_90_dialog_content = "I know Jakine said that we're not supposed to interfere with the world around us.",
  ui_story_5051_50510302_91_dialog_content = "But I don't think we have a choice. We have no way of hiding out here anymore, and I can't sense the others with my psychic abilities.",
  ui_story_5051_50510302_92_dialog_content = "We should use your status as a princess to find them and look for a way back.",
  ui_story_5051_50510302_93_dialog_content = "...",
  ui_story_5051_50510302_94_dialog_content = "What's the matter, Mia?",
  ui_story_5051_50510302_95_dialog_content = "Um, PlayerName?",
  ui_story_5051_50510302_96_dialog_content = "W-Would it be alright if I went to see my mother one last time before we left?",
  ui_story_5051_50510302_97_dialog_content = "When I was hiding under the table earlier, I heard them say that she had passed away while I was gone.",
  ui_story_5051_50510302_98_dialog_content = "I had wanted to return to Lumopolis to see her and my little sister. I had so much I wanted to share with them.",
  ui_story_5051_50510302_99_dialog_content = "I wanted to show them that I had all grown up and that I'm braver than before, and tell them all about the friends I made outside of the city.",
  ui_story_5051_50510302_100_dialog_content = "And... I wanted to tell my mother that I missed her every day...",
  ui_story_5051_50510302_101_dialog_content = "But it's too late.",
  ui_story_5051_50510302_102_dialog_content = "... Your mother is the City Lord's wife.",
  ui_story_5051_50510302_103_dialog_content = "If we manage to find her, I'm sure she'll be able to help us return to the real world!",
  ui_story_5051_50510302_104_dialog_content = "Paying her a visit would be in everyone's best interest, right?",
  ui_story_5051_50510302_105_dialog_content = "Uh, PlayerName? It sounds like you're just twisting things to work in our favor...",
  ui_story_5051_50510302_106_dialog_content = "Heheheh, but it makes sense, doesn't it?",
  ui_story_5051_50510302_107_dialog_content = "You can thank all of our friends on the Colossus for teaching me how to do this!",
  ui_story_5051_50510302_108_dialog_content = "O-Okay then, I'll just follow your lead.",
  ui_story_5051_50510302_109_dialog_content = "Somehow this feels like I'm setting a bad example for you, Mia...",
  ui_story_5051_50510302_110_dialog_content = "Pardon me, but... are you ready to go? We're on a tight schedule.",
  ui_story_5051_50510302_111_dialog_content = "Ah, sorry about that! We're ready to go when you are!",
  ui_story_5051_50510302_112_dialog_content = "It sounds like your team is in a hurry. Could you tell us what you're transporting?",
  ui_story_5051_50510302_113_dialog_content = "It's nothing particularly sensitive, just a few special items that need to be delivered in advance. Namely...",
  ui_story_5051_50510302_114_dialog_content = "Items that are needed for this year's <color=#FFB400>Schwartz Family Day</color>.",
  ui_story_5051_50510302_115_dialog_content = "(Schwartz Family Day? That's a little too much of a coincidence.)",
  ui_story_5051_50510302_116_dialog_content = "<color=#e8d9bb>*rumbles*</color>",
  ui_story_5051_50510302_117_dialog_content = "More thunder...",
  ui_story_5051_50510302_118_dialog_content = "Is something the matter?",
  ui_story_5051_50510302_119_dialog_content = "No, nothing. We should get going before it starts to rain!",
  ui_story_5051_50510302_120_dialog_content = "Rain? I had no idea it was going to rain today. Anyway, we will depart immediately.",
  ui_story_5051_50510302_121_dialog_content = "<anim type=Shake><size=32>... Sch...</size></anim>",
  ui_story_5051_50510302_122_dialog_content = "<anim type=Shake><size=32>... Schwartz...</size></anim>",
  ui_story_5051_50510302_123_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510402_1_dialog_content = "...",
  ui_story_5051_50510402_2_dialog_content = "Hmph... So there are Eclipsites lurking in places like this too.",
  ui_story_5051_50510402_3_dialog_content = "Since when did Lumopolis become a breeding ground for these wretched monsters?",
  ui_story_5051_50510402_4_dialog_content = "Phew! I'm saved!",
  ui_story_5051_50510402_5_dialog_content = "Thanks, Mr. Caleb! If it wasn't for you showing up just in the nick of time, I would've been supper for those Eclipsites...",
  ui_story_5051_50510402_6_dialog_content = "No, wait, make that lunch! It's still daytime, after all.",
  ui_story_5051_50510402_7_dialog_content = "I'm a little confused about that, as well.",
  ui_story_5051_50510402_8_dialog_content = "It was clearly nighttime when we were still back at the palace, Miss Jakine.",
  ui_story_5051_50510402_9_dialog_content = "But now it's daytime, and we've found ourselves in the middle of a forest.",
  ui_story_5051_50510402_10_dialog_content = "Could it be that we've been transported into the Crystal of Eternal Memory?",
  ui_story_5051_50510402_11_dialog_content = "That's right! Though to be perfectly honest, I didn't think slapping together a bunch of incantations would work so well!",
  ui_story_5051_50510402_12_dialog_content = "Maybe I am a genius, after all...",
  ui_story_5051_50510402_13_dialog_content = "(Oh yes, only a genius could have done something like this...)",
  ui_story_5051_50510402_14_dialog_content = "Judging from those structures in the distance, it appears we're somewhere on the outskirts of Lower Lumopolis.",
  ui_story_5051_50510402_15_dialog_content = "As for that crate, which you just crushed by sitting on it—",
  ui_story_5051_50510402_16_dialog_content = "The label indicates that it was prepared specifically for Schwartz Family Day.",
  ui_story_5051_50510402_17_dialog_content = "Yeah, and scared me silly just now!",
  ui_story_5051_50510402_18_dialog_content = "It looked sturdy enough, but it broke as soon as I put my weight on it!",
  ui_story_5051_50510402_19_dialog_content = "How was I supposed to know a bunch of Eclipsites would come running out?!",
  ui_story_5051_50510402_20_dialog_content = "Just what's going on around here? Don't tell me the folks in Lumopolis like to keep these things as pets?!",
  ui_story_5051_50510402_21_dialog_content = "I can assure you that my people have absolutely no interest in raising violent, mindless beasts such as these.",
  ui_story_5051_50510402_22_dialog_content = "Eclipsites prepared just for Schwartz Family Day... I see. This must be Lumopolis from twelve years ago.",
  ui_story_5051_50510402_23_dialog_content = "Stashing crates of Eclipsites in a transport full of goods for the Schwartz family... A bold move on the part of the culprits behind this attack.",
  ui_story_5051_50510402_24_dialog_content = "Wait... Does that mean the Eclipsites managed to invade Lumopolis twelve years ago?",
  ui_story_5051_50510402_25_dialog_content = "That's right. While I don't know for certain how the rest of the world sees our bastion in the sky...",
  ui_story_5051_50510402_26_dialog_content = "In reality, it's not nearly as impenetrable as it seems.",
  ui_story_5051_50510402_27_dialog_content = "Uh, Mr. Caleb...",
  ui_story_5051_50510402_28_dialog_content = "Did you happen to see anyone else before we ran into each other?",
  ui_story_5051_50510402_29_dialog_content = "No. In fact, I had just woken up when our paths crossed.",
  ui_story_5051_50510402_30_dialog_content = "Oh. Hahaha... Well, the incantation was supposed to teleport all of us to the same place.",
  ui_story_5051_50510402_31_dialog_content = "On top of that, the Eclipsites here shouldn't have been able to notice us.",
  ui_story_5051_50510402_32_dialog_content = "Looks like I made a teeny-tiny mistake, after all!",
  ui_story_5051_50510402_33_dialog_content = "... Miss Jakine, I feel that I must ask you something.",
  ui_story_5051_50510402_34_dialog_content = "A-Ahem! But don't worry! I'll take full responsibility and make sure everyone gets back safe and sound!",
  ui_story_5051_50510402_35_dialog_content = "That's not what I was going to ask.",
  ui_story_5051_50510402_36_dialog_content = "The Lumina of the person who activated this Crystal of Eternal Memory... Is it somewhere in here?",
  ui_story_5051_50510402_37_dialog_content = "Yeah, of course it is!",
  ui_story_5051_50510402_38_dialog_content = "Do you happen to know where, exactly?",
  ui_story_5051_50510402_39_dialog_content = "Y-You want to know where it is? Let me see...",
  ui_story_5051_50510402_40_dialog_content = "\"The Crystal of Eternal Memory must be activated with the Lumina of its owner. It is the source of power which maintains the world within the crystal.\"",
  ui_story_5051_50510402_41_dialog_content = "<size=30>Is that really all of it?!</size>",
  ui_story_5051_50510402_42_dialog_content = "A-Ahem! In my professional opinion, the Lumina used to power this entire world is probably being housed somewhere extremely important!",
  ui_story_5051_50510402_43_dialog_content = "And the most important place I can think of—",
  ui_story_5051_50510402_44_dialog_content = "—is the Crystal of Eternal Memory inside of this world!",
  ui_story_5051_50510402_45_dialog_content = "I suppose that makes sense...",
  ui_story_5051_50510402_46_dialog_content = "I have another question. If Lumina is what sustains this world, then naturally, it would have to run out someday, yes?",
  ui_story_5051_50510402_47_dialog_content = "It's already been twelve years since this crystal was activated. How much longer does it have?",
  ui_story_5051_50510402_48_dialog_content = "Oh, there's no need to worry about that!",
  ui_story_5051_50510402_49_dialog_content = "As long as a crystal is replenished with water from Lake Mirror once every twelve years, its Lumina won't fade away for a long, long time!",
  ui_story_5051_50510402_50_dialog_content = "However, tampering with the order of things in a crystal's world can easily accelerate its Lumina consumption.",
  ui_story_5051_50510402_51_dialog_content = "In extreme cases, a single action can cause it to exhaust all of its Lumina in an instant.",
  ui_story_5051_50510402_52_dialog_content = "If that happens, I can't guarantee that we'll survive!",
  ui_story_5051_50510402_53_dialog_content = "Is this what you meant by an \"unimaginable catastrophe\"?",
  ui_story_5051_50510402_54_dialog_content = "Yeah, more or less. Naturally, there can be other unintended consequences, as well...",
  ui_story_5051_50510402_55_dialog_content = "Which is why we need to find the others right away!",
  ui_story_5051_50510402_56_dialog_content = "We can't stay long in places where we can't keep ourselves hidden.",
  ui_story_5051_50510402_57_dialog_content = "You're absolutely right, which is why I'm leaving this important task in your \"capable\" hands, Miss Jakine.",
  ui_story_5051_50510402_58_dialog_content = "I have other matters to attend to. Best of luck.",
  ui_story_5051_50510402_59_dialog_content = "Huh?! Wait, you can't just dump this on me and leave like that!",
  ui_story_5051_50510402_60_dialog_content = "Also, didn't I just say that we have to be careful? Changing even the smallest thing in this world could spell disaster for all of us!",
  ui_story_5051_50510402_61_dialog_content = "You did, and I have no intention of breaking the rules. The others, however, require your close supervision.",
  ui_story_5051_50510402_62_dialog_content = "There's still a bit of Lumina left in this world. I'd prefer to keep it that way until we're safe.",
  ui_story_5051_50510402_63_dialog_content = "Ugh, aren't you listening? You said it yourself: this is Lumopolis! What are you gonna do if you run into your past self?!",
  ui_story_5051_50510402_64_dialog_content = "Don't worry about that. On this day, I was escorting my niece to Umbraton, along with a number of our knights. I was nowhere near the city.",
  ui_story_5051_50510402_65_dialog_content = "Surely the Crystal of Eternal Memory's range doesn't reach that far?",
  ui_story_5051_50510402_66_dialog_content = "Well, that's true...",
  ui_story_5051_50510402_67_dialog_content = "I plan on entering the city disguised as a guest. I'll come to find you once I've had the chance to see someone.",
  ui_story_5051_50510402_68_dialog_content = "So you're willing to risk all of our lives just to see this person?",
  ui_story_5051_50510402_69_dialog_content = "Precisely. While we can never truly return to the past, how often do we get the chance to reclaim what was lost?",
  ui_story_5051_50510402_70_dialog_content = "Please gather the others as quickly as you can, Miss Jakine. Farewell.",
  ui_story_5051_50510402_71_dialog_content = "Wait! You haven't even told me where we're supposed to meet later!",
  ui_story_5051_50510402_72_dialog_content = "Great, he's already gone...",
  ui_story_5051_50510402_73_dialog_content = "What happened to that all-refined and gentleman-like person? Was it all just an act?",
  ui_story_5051_50510402_74_dialog_content = "How could he be so selfish and inconsiderate at a time like this?!",
  ui_story_5051_50510402_75_dialog_content = "Ahhh—I'm so mad I could spit!",
  ui_story_5051_50510402_76_dialog_content = "Sigh... \"The chance to reclaim what was lost,\" huh?",
  ui_story_5051_50510402_77_dialog_content = "I wonder if I'll get that kind of chance too?",
  ui_story_5051_50510402_78_dialog_content = "Mom... Twelve years ago, you came to Lumopolis to deliver this Crystal of Eternal Memory to the City Lord, and then you went straight back to Northland.",
  ui_story_5051_50510402_79_dialog_content = "Dad always said he could never understand you. Leaving your family behind to practice divination, running off into the mountains without so much as a goodbye.",
  ui_story_5051_50510402_80_dialog_content = "But Her Majesty says that you're a genius and ascended beyond our worldly limitations... In that respect, I guess we're nothing alike.",
  ui_story_5051_50510402_81_dialog_content = "I wonder what you'd say if we saw each other in here?",
  ui_story_5051_50510402_82_dialog_content = "... Oh, what am I thinking?!",
  ui_story_5051_50510402_83_dialog_content = "Focus, Jakine! You're here as Northland's envoy, remember?",
  ui_story_5051_50510402_84_dialog_content = "You can't rely on anybody but yourself right now! It's your job to get everyone out of here safely!",
  ui_story_5051_50510402_85_dialog_content = "*inhale* *exhale*",
  ui_story_5051_50510402_86_dialog_content = "Alright! Northland Envoy Jakine is ready to roll!",
  ui_story_5051_50510501_1_dialog_content = "(There aren't many places where Schwartz could have hidden the Crystal of Eternal Memory. If I'm right, it should be somewhere in his home.)",
  ui_story_5051_50510501_2_dialog_content = "(This year's Family Day banquet was much larger in scale, so most of the guards were posted over there to help maintain order.)",
  ui_story_5051_50510501_3_dialog_content = "(Once the holiday ceremony begins, I should be able to sneak in through one of the less-guarded areas.)",
  ui_story_5051_50510501_4_dialog_content = "(Until then, I just need to keep a low profile and wait patiently.)",
  ui_story_5051_50510501_5_dialog_content = "(The garden over there should be fairly empty...)",
  ui_story_5051_50510501_6_dialog_content = "(Irises... A symbol of good tidings, as well as longing.)",
  ui_story_5051_50510501_7_dialog_content = "(I remember my sister planted these just for her older daughter.)",
  ui_story_5051_50510501_8_dialog_content = "... I know your time is nearly over, little ones.",
  ui_story_5051_50510501_9_dialog_content = "But won't you please keep your flowers for just a few more days?",
  ui_story_5051_50510501_10_dialog_content = "My daughter will be home soon. I would love it if she had a chance to see your beauty.",
  ui_story_5051_50510501_11_dialog_content = "She used to be so fond of flowers. I'm certain she would smile again at the sight of you.",
  ui_story_5051_50510501_12_dialog_content = "Is it... Is it really you...?",
  ui_story_5051_50510501_13_dialog_content = "<color=#FFB400>Joshua</color>...?",
  ui_story_5051_50510501_14_dialog_content = "Oh!",
  ui_story_5051_50510501_15_dialog_content = "Why hello there, Mister.",
  ui_story_5051_50510501_16_dialog_content = "What brings you to my garden on this lovely afternoon?",
  ui_story_5051_50510501_17_dialog_content = "Er, forgive me for asking, but...",
  ui_story_5051_50510501_18_dialog_content = "Have we met before?",
  ui_story_5051_50510501_19_dialog_content = "... I'm afraid not. I'm but a low-ranking noble, undeserving of such an honor.",
  ui_story_5051_50510501_20_dialog_content = "But even so, it's a pleasure to meet you, Lady Joshua.",
  ui_story_5051_50510501_21_dialog_content = "Is that so?",
  ui_story_5051_50510501_22_dialog_content = "I could have sworn... Never mind, my eyes must be playing tricks on me.",
  ui_story_5051_50510501_23_dialog_content = "(Joshua...)",
  ui_story_5051_50510501_24_dialog_content = "(I was only lying to that Northland fortune-teller about seeing someone.)",
  ui_story_5051_50510501_25_dialog_content = "(In truth, I never expected to see you here.)",
  ui_story_5051_50510501_26_dialog_content = "(After twelve years, I finally have the chance to speak to you again.)",
  ui_story_5051_50510501_27_dialog_content = "(And yet, I can only do so while pretending to be a stranger...)",
  ui_story_5051_50510501_28_dialog_content = "(I came to this world to take back the Lumina my sister left behind.)",
  ui_story_5051_50510501_29_dialog_content = "(This is all just an illusion created by Northland's secret tricks. I can't let it distract me from my goal.)",
  ui_story_5051_50510501_30_dialog_content = "(I need to put an end to this farce, once and for all...!)",
  ui_story_5051_50510501_31_dialog_content = "Are you alright? You look as though you're in pain...",
  ui_story_5051_50510501_32_dialog_content = "My apologies.",
  ui_story_5051_50510501_33_dialog_content = "I am merely in disbelief at my own good fortune, that I have been blessed with a chance to meet you.",
  ui_story_5051_50510501_34_dialog_content = "My, that's quite a flattering lie.",
  ui_story_5051_50510501_35_dialog_content = "The tears in the corners of your eyes say otherwise. Are you hurting somewhere, by chance? Or maybe your pain resides in your heart?",
  ui_story_5051_50510501_36_dialog_content = "You shouldn't bear it all by yourself, you know.",
  ui_story_5051_50510501_37_dialog_content = "...",
  ui_story_5051_50510501_38_dialog_content = "I-I said I'm fine!",
  ui_story_5051_50510501_39_dialog_content = "I just have something in my eye!",
  ui_story_5051_50510501_40_dialog_content = "What do they know anyways... Everyone in that academy is an idiot! The professors, the students, all of them!",
  ui_story_5051_50510501_41_dialog_content = "Always saying things like, \"You may be smart, Caleb, but without your parents, you've become haughty and arrogant!\"",
  ui_story_5051_50510501_42_dialog_content = "<size=30>So what if I don't have my parents anymore? The only person I need is my sister...</size>",
  ui_story_5051_50510501_43_dialog_content = "Someday, I'm going to change everything about this place! Just you wait!",
  ui_story_5051_50510501_44_dialog_content = "I believe in you, Caleb.",
  ui_story_5051_50510501_45_dialog_content = "You've never been one to brag. I know you can accomplish anything you set your mind to.",
  ui_story_5051_50510501_46_dialog_content = "You really believe in me?",
  ui_story_5051_50510501_47_dialog_content = "Of course I do.",
  ui_story_5051_50510501_48_dialog_content = "Thank you... Tell me something, Joshua. If there ever comes a day when nobody has to worry about food or safety ever again...",
  ui_story_5051_50510501_49_dialog_content = "Does that mean you won't have to keep helping Daniel anymore?",
  ui_story_5051_50510501_50_dialog_content = "Hmm... While it's true that our lives would be much more simple if that ever happened, I have a duty to be with him. He's my husband, after all.",
  ui_story_5051_50510501_51_dialog_content = "...",
  ui_story_5051_50510501_52_dialog_content = "But should that day ever come, I promise I'll help you with all of your research, and attend every single one of your presentations. How does that sound?",
  ui_story_5051_50510501_53_dialog_content = "Really?",
  ui_story_5051_50510501_54_dialog_content = "Really.",
  ui_story_5051_50510501_55_dialog_content = "Then... Then I'll present my research all over the world!",
  ui_story_5051_50510501_56_dialog_content = "You used to say that you wanted to travel the world all the time, but you haven't talked about it ever since you got married.",
  ui_story_5051_50510501_57_dialog_content = "So I'm going to do my best to make your dream come true.",
  ui_story_5051_50510501_58_dialog_content = "Oh my, it looks like I've been tricked again. What am I going to do with you, Caleb?",
  ui_story_5051_50510501_59_dialog_content = "You already promised you'd come to all of my presentations! No going back on your word now!",
  ui_story_5051_50510501_60_dialog_content = "I know, I know. It's a deal, then.",
  ui_story_5051_50510501_61_dialog_content = "I... I just have something in my eye.",
  ui_story_5051_50510501_62_dialog_content = "I don't think so. Just look at you, crinkling your nose to cover up your sadness.",
  ui_story_5051_50510501_63_dialog_content = "You look just like my younger brother...",
  ui_story_5051_50510501_64_dialog_content = "He possesses an intellect far beyond his years, but he's no different than a sweet, little child in many ways.",
  ui_story_5051_50510501_65_dialog_content = "For example, every time he cries, he lies about having something in his eye.",
  ui_story_5051_50510501_66_dialog_content = "... Oh, but where are my manners?",
  ui_story_5051_50510501_67_dialog_content = "Please forgive me for speaking so casually to you, sir. It's just that you reminded me so much of my brother.",
  ui_story_5051_50510501_68_dialog_content = "I should be embarrassed to have treated you so disrespectfully.",
  ui_story_5051_50510501_69_dialog_content = "Th-There's no need to apologize...",
  ui_story_5051_50510501_70_dialog_content = "Still, it feels so uncanny. The two of you are so far apart in age...",
  ui_story_5051_50510501_71_dialog_content = "And yet somehow, I can sense his presence about you.",
  ui_story_5051_50510501_72_dialog_content = "Regardless, I would like to make amends for my rudeness just now. Please join us as a guest of honor for our banquet tonight.",
  ui_story_5051_50510501_73_dialog_content = "Should anyone question your presence at our table, you need only mention my name.",
  ui_story_5051_50510501_74_dialog_content = "And should you find yourself in any trouble, you can always come to me.",
  ui_story_5051_50510501_75_dialog_content = "No one should bear any kind of suffering on their own.",
  ui_story_5051_50510501_76_dialog_content = "Thank you for your gracious offer, but I feel I must decline. I came here on business, and had no intention of attending the banquet in the first place.",
  ui_story_5051_50510501_77_dialog_content = "It's just that these flowers called some fond memories to mind, and I couldn't help but linger for a while. Forgive me for disturbing you, Your Highness.",
  ui_story_5051_50510501_78_dialog_content = "With your leave, I must be going now... Take care, Lady Joshua.",
  ui_story_5051_50510501_79_dialog_content = "Oh, you seem to be in quite a hurry...",
  ui_story_5051_50510501_80_dialog_content = "May I at least know your name?",
  ui_story_5051_50510501_81_dialog_content = "Though people are different in this world...",
  ui_story_5051_50510501_82_dialog_content = "Lumopolis is always the same.",
  ui_story_5051_50510501_83_dialog_content = "It's true. Holiness and stability are the hallmarks of Lumopolis, as well as the source of its people's faith.",
  ui_story_5051_50510501_84_dialog_content = "That's why people have sacrificed so much over the years to protect its purity... In the end, seeing its majesty in the sky above makes it all worth it.",
  ui_story_5051_50510501_85_dialog_content = "Please present your entry passes. That means you, kid!",
  ui_story_5051_50510501_86_dialog_content = "Oh, I...",
  ui_story_5051_50510501_87_dialog_content = "Sorry, he's a friend of mine.",
  ui_story_5051_50510501_88_dialog_content = "P-Princess Veronica?!",
  ui_story_5051_50510501_89_dialog_content = "Please forgive my ignorance, Your Highness! Go right ahead!",
  ui_story_5051_50510501_90_dialog_content = "It's no trouble at all. Thank you for keeping watch over our fair city.",
  ui_story_5051_50510501_91_dialog_content = "I-It's my honor!",
  ui_story_5051_50510501_92_dialog_content = "Phew! Having a princess around sure comes in handy!",
  ui_story_5051_50510501_93_dialog_content = "The last time I got held up at the gates, I had to use Carleen's name to get through too...",
  ui_story_5051_50510501_94_dialog_content = "It's fine, PlayerName. You're a good person, which is why everyone is always willing to help you.",
  ui_story_5051_50510501_95_dialog_content = "R-Really? Heheh, I can't help but feel a little embarrassed...",
  ui_story_5051_50510501_96_dialog_content = "Oh, that reminds me! Hang on a second!",
  ui_story_5051_50510501_97_dialog_content = "Pardon me, but have you seen our friends pass through the gates today? One of them is a serious-looking older gentleman with white hair and an eyepatch, the other is a young noble with blonde hair and violet eyes...",
  ui_story_5051_50510501_98_dialog_content = "Oh, and there was a red-haired divination master from Northland with them too! Do you know if they're in Lumopolis?",
  ui_story_5051_50510501_99_dialog_content = "I haven't seen the first two, sorry.",
  ui_story_5051_50510501_100_dialog_content = "But an envoy from Northland arrived just yesterday, and she seems to fit your description.",
  ui_story_5051_50510501_101_dialog_content = "(An envoy from Northland? That must be Jakine's predecessor.)",
  ui_story_5051_50510501_102_dialog_content = "Understood. Thank you for your time!",
  ui_story_5051_50510501_103_dialog_content = "Is everything alright, PlayerName?",
  ui_story_5051_50510501_104_dialog_content = "I just asked the guard if he's seen the others, but it looks like he hasn't.",
  ui_story_5051_50510501_105_dialog_content = "Guess we'll have to find them ourselves.",
  ui_story_5051_50510501_106_dialog_content = "—!!!",
  ui_story_5051_50510501_107_dialog_content = "Eclipsites! How did they get into the cargo?!",
  ui_story_5051_50510501_108_dialog_content = "There are Eclipsites in here too?!",
  ui_story_5051_50510501_109_dialog_content = "D-Don't worry, I'll take care of them...!",
  ui_story_5051_50510502_1_dialog_content = "What's the situation?",
  ui_story_5051_50510502_2_dialog_content = "Captain <color=#FFB400>Mime</color>! A number of Eclipsites were hidden within a recently-received shipment, and ambushed us upon being discovered!",
  ui_story_5051_50510502_3_dialog_content = "The vendor in charge of the shipment has already been taken in for questioning. No casualties have been reported.",
  ui_story_5051_50510502_4_dialog_content = "And on the day of the Family Day banquet, of all days.",
  ui_story_5051_50510502_5_dialog_content = "Have the suspects delivered to me. For committing such a heinous crime, I'll escort them to the Hall of Justice myself.",
  ui_story_5051_50510502_6_dialog_content = "Yes, sir!",
  ui_story_5051_50510502_7_dialog_content = "What about the Eclipsites? Have all of them been eliminated?",
  ui_story_5051_50510502_8_dialog_content = "Yes, sir! Not a single one managed to escape!",
  ui_story_5051_50510502_9_dialog_content = "And it was all thanks to Princess Veronica, no less!",
  ui_story_5051_50510502_10_dialog_content = "Princess Veronica was absolutely incredible!",
  ui_story_5051_50510502_11_dialog_content = "But I thought Princess Carleen was the warrior between the two of them?",
  ui_story_5051_50510502_12_dialog_content = "No, no, no! That was Princess Veronica just now, no doubt about it!",
  ui_story_5051_50510502_13_dialog_content = "I had no idea she was so gifted as well. The Schwartz family is truly blessed to have such talented children...",
  ui_story_5051_50510502_14_dialog_content = "<size=30>Uh, PlayerName? Everyone keeps staring... It's starting to scare me.</size>",
  ui_story_5051_50510502_15_dialog_content = "That's because you're everyone's hero, Mia!",
  ui_story_5051_50510502_16_dialog_content = "You wiped the floor with those Eclipsites like you've been doing it all your life!",
  ui_story_5051_50510502_17_dialog_content = "Was I... really that impressive?",
  ui_story_5051_50510502_18_dialog_content = "Of course you were!",
  ui_story_5051_50510502_19_dialog_content = "O-Oh, okay... Thank you...",
  ui_story_5051_50510502_20_dialog_content = "Good work, everyone. You can leave the suspect with us now.",
  ui_story_5051_50510502_21_dialog_content = "Understood. Thank you for your help.",
  ui_story_5051_50510502_22_dialog_content = "(Hang on a second...)",
  ui_story_5051_50510502_23_dialog_content = "(Is that <color=#FFB400>Sharona</color>?!)",
  ui_story_5051_50510502_24_dialog_content = "You there! Who are you, and why are you staring at me like that?",
  ui_story_5051_50510502_25_dialog_content = "If you require assistance, you need only ask. I may only be a reserve knight, but I am duty-bound to lend my aid, all the same.",
  ui_story_5051_50510502_26_dialog_content = "If you have no further business here, then I suggest you be on your way now.",
  ui_story_5051_50510502_27_dialog_content = "(Crap, she spotted me! We need to get out of here before we interfere too much with the past!)",
  ui_story_5051_50510502_28_dialog_content = "(Still, if this is twelve years ago, doesn't that mean Sharona is only fourteen years old? Guess she's always been this serious, huh.)",
  ui_story_5051_50510502_29_dialog_content = "I-It's nothing, sorry about that. Your eyes just looked kind of familiar, is all.",
  ui_story_5051_50510502_30_dialog_content = "My eyes, you say? How cliché.",
  ui_story_5051_50510502_31_dialog_content = "You should save that kind of talk for someone who actually wants to hear it.",
  ui_story_5051_50510502_32_dialog_content = "Haha... Again, sorry to bother you.",
  ui_story_5051_50510502_33_dialog_content = "If our paths ever cross again, maybe I'll have more time to listen to your crazy rambling.",
  ui_story_5051_50510502_34_dialog_content = "Feel free to keep hoping for that day to come, stranger.",
  ui_story_5051_50510502_35_dialog_content = "Don't worry, I know we'll meet again someday!",
  ui_story_5051_50510502_36_dialog_content = "(After all, I happen to be pretty good friends with the future you!)",
  ui_story_5051_50510502_37_dialog_content = "Hmph. Lunatic...",
  ui_story_5051_50510502_38_dialog_content = "Hey, see that, Sharona struck up a conversation on her patrol!",
  ui_story_5051_50510502_39_dialog_content = "She's just a teen, it's par for the course.",
  ui_story_5051_50510502_40_dialog_content = "You're right. She's usually so precocious that it hurts to see her so uptight.",
  ui_story_5051_50510502_41_dialog_content = "Sigh, I'd love to sneak off to see the parade...",
  ui_story_5051_50510502_42_dialog_content = "<size=45>Knights!</size>",
  ui_story_5051_50510502_43_dialog_content = "Today is a joyous time of celebration for our entire city. As members of the prestigious Kartima family, we have been entrusted with the safety of our people.",
  ui_story_5051_50510502_44_dialog_content = "As such, you must carry yourselves with dignity and professionalism as you carry out your orders!",
  ui_story_5051_50510502_45_dialog_content = "...",
  ui_story_5051_50510502_46_dialog_content = "(Hahaha... Even after all these years, it looks like Sharona hasn't changed a bit.)",
  ui_story_5051_50510502_47_dialog_content = "Um, PlayerName? Mr. Mime says he can escort us to see my mother.",
  ui_story_5051_50510502_48_dialog_content = "W-We shouldn't waste our time talking to that girl anymore. Let's go.",
  ui_story_5051_50510502_49_dialog_content = "(Whoops, guess I let the festive atmosphere get the better of me...)",
  ui_story_5051_50510502_50_dialog_content = "(We're still in serious danger. I can't keep dropping my guard like this.)",
  ui_story_5051_50510502_51_dialog_content = "Sorry, I was being careless just now. I'll do my best not to talk to anyone else if it's not necessary.",
  ui_story_5051_50510502_52_dialog_content = "That's not what I meant. It's just... Ugh, I don't really know how to describe this feeling.",
  ui_story_5051_50510502_53_dialog_content = "My chest feels tight, and my heart... it kind of hurts a little.",
  ui_story_5051_50510502_54_dialog_content = "Oh no, are you okay?! Ah, if only I could use my powers right now!",
  ui_story_5051_50510502_55_dialog_content = "Then I could look into your mind and see if you're alright...",
  ui_story_5051_50510502_56_dialog_content = "N-No way! Please don't look inside my mind right now...!",
  ui_story_5051_50510502_57_dialog_content = "Oh, PlayerName! For how smart you are, you can be really dense sometimes!",
  ui_story_5051_50510502_58_dialog_content = "That's great. Oh, I have a favor to ask of the Lumo Knights. I'll be right back!",
  ui_story_5051_50510502_59_dialog_content = "Huh? PlayerName?",
  ui_story_5051_50510502_60_dialog_content = "Hello! Mr. Mime, I presume?",
  ui_story_5051_50510502_61_dialog_content = "The one and the same. Do you need something?",
  ui_story_5051_50510502_62_dialog_content = "I'm looking for my three friends. We're all Princess Veronica's guests, but we got separated on the way here.",
  ui_story_5051_50510502_63_dialog_content = "Would it be possible for you and your knights to help us find them? Here's a description of what they look like...",
  ui_story_5051_50510502_64_dialog_content = "Very well, we'll do what we can. I still have to report to the City Lord, so if you'll excuse me.",
  ui_story_5051_50510502_65_dialog_content = "Thank you, Mr. Mime.",
  ui_story_5051_50510502_66_dialog_content = "Uh, when you see my father later, can you not mention my friend and what happened...?",
  ui_story_5051_50510502_67_dialog_content = "If that's all you ask of me, then I see no problem doing as you wish.",
  ui_story_5051_50510502_68_dialog_content = "However, my knights are still responsible for patrolling the city during the holiday. In return, I must ask that you and your friends avoid causing problems today.",
  ui_story_5051_50510502_69_dialog_content = "I understand. I promise we'll be on our best behavior.",
  ui_story_5051_50510502_70_dialog_content = "Are you all done, Mia?",
  ui_story_5051_50510502_71_dialog_content = "Yep! I just made sure that Mr. Mime wouldn't mention us to my father in his report.",
  ui_story_5051_50510502_72_dialog_content = "After all, I'm supposed to be in a lot of trouble today. If he found out I was back in the city, he would be furious...",
  ui_story_5051_50510502_73_dialog_content = "Veronica?",
  ui_story_5051_50510502_74_dialog_content = "Mother...?",
  ui_story_5051_50510502_75_dialog_content = "Mother!",
  ui_story_5051_50510502_76_dialog_content = "Oh, my little girl! What's the matter?",
  ui_story_5051_50510502_77_dialog_content = "Mother... It's really you! Oh, I miss you so much, Mother...",
  ui_story_5051_50510502_78_dialog_content = "Me too, my dear. But don't worry, I'm here now.",
  ui_story_5051_50510502_79_dialog_content = "Let me take a look at you. Did the Lumo Knights hurt you during your training?",
  ui_story_5051_50510502_80_dialog_content = "Or maybe... Did you get into a fight with one of your friends?",
  ui_story_5051_50510502_81_dialog_content = "(She's looking right at me! Mia's mom thinks I did that to her! No, no, you've got it all wrong! It wasn't me!!!)",
  ui_story_5051_50510502_82_dialog_content = "No, Mother, PlayerName would never do something like that. He brought me here to see you...",
  ui_story_5051_50510502_83_dialog_content = "I see. It seems you've made a very good friend, my love.",
  ui_story_5051_50510502_84_dialog_content = "Hmm? What happened to your knees, Veronica? What are these patterns...?",
  ui_story_5051_50510502_85_dialog_content = "I'm fine, Mother! Really! I've...",
  ui_story_5051_50510502_86_dialog_content = "I've gotten much braver than before.",
  ui_story_5051_50510502_87_dialog_content = "So now... now you don't have to worry about me!",
  ui_story_5051_50510502_88_dialog_content = "Is that so? That sad little face of yours isn't very convincing, you know.",
  ui_story_5051_50510502_89_dialog_content = "Come, let's wash your face while you tell me all about how brave you are now.",
  ui_story_5051_50510601_1_dialog_content = "(The ladies went inside...)",
  ui_story_5051_50510601_2_dialog_content = "(Mia's mom smiled at me when they left, probably hinting at me to wait here.)",
  ui_story_5051_50510601_3_dialog_content = "(What's that again? \"Never peek at a lady getting ready\"? So I gotta wait.)",
  ui_story_5051_50510601_4_dialog_content = "(I've met Istvan and Sharona along the way, and now Mia's mother...)",
  ui_story_5051_50510601_5_dialog_content = "(They all chatted with us like they were the actual person.)",
  ui_story_5051_50510601_6_dialog_content = "(The Crystal of Eternal Memory is simply marvelous...)",
  ui_story_5051_50510601_7_dialog_content = "(But it was never designed for us to interact with them.)",
  ui_story_5051_50510601_8_dialog_content = "(So contacts like this must be taxing the crystal's limits.)",
  ui_story_5051_50510601_9_dialog_content = "(Sigh, it's hard to gauge if the situation is good or bad. I hope we find Jakine and others soon...)",
  ui_story_5051_50510601_10_dialog_content = "You there.",
  ui_story_5051_50510601_11_dialog_content = "This is the private property of the Schwartz family.",
  ui_story_5051_50510601_12_dialog_content = "How did you manage to sneak in here?",
  ui_story_5051_50510601_13_dialog_content = "Huh? Who's there?",
  ui_story_5051_50510601_14_dialog_content = "Look down, insolent fool! Carleen is speaking to you!",
  ui_story_5051_50510601_15_dialog_content = "<size=45>Carleen?!</size>",
  ui_story_5051_50510601_16_dialog_content = "You dare address me by name?",
  ui_story_5051_50510601_17_dialog_content = "As much as I do not enjoy flaunting one's nobility, on this ground, slighting me is tantamount to slighting House Schwartz!",
  ui_story_5051_50510601_18_dialog_content = "Sneaking into our land on Schwartz Family Day...",
  ui_story_5051_50510601_19_dialog_content = "... and exhibiting such rudeness and besmirching a member. You will suffer the consequences!",
  ui_story_5051_50510601_20_dialog_content = "Wait, I was caught off-guard!",
  ui_story_5051_50510601_21_dialog_content = "Please let me explain, Princess Carleen!",
  ui_story_5051_50510601_22_dialog_content = "Guess who?",
  ui_story_5051_50510601_23_dialog_content = "<size=45>Whoa!</size>",
  ui_story_5051_50510601_24_dialog_content = "W-What?!",
  ui_story_5051_50510601_25_dialog_content = "You even bring an accomplice, despicable intruder?!",
  ui_story_5051_50510601_26_dialog_content = "Huh? Yeah...",
  ui_story_5051_50510601_27_dialog_content = "That's right, we're working together to get you, little Carleen!",
  ui_story_5051_50510601_28_dialog_content = "D-Despicable! Where's my lance? Hey, let go, I can't find my lance!",
  ui_story_5051_50510601_29_dialog_content = "Wait a second... you sound familiar, are you Veronica?",
  ui_story_5051_50510601_30_dialog_content = "Ah-ha! No, I'm definitely not Veronica!",
  ui_story_5051_50510601_31_dialog_content = "Please do not attempt to fool me with such a poor vocal disguise! I-I'm not a child anymore!",
  ui_story_5051_50510601_32_dialog_content = "Are you sure, little Carleen?",
  ui_story_5051_50510601_33_dialog_content = "Heh, despite a maturity beyond her age, Carleen will still panic when her eyes are covered.",
  ui_story_5051_50510601_34_dialog_content = "Mother? Are you here as well, Mother? Please ask Veronica to release me!",
  ui_story_5051_50510601_35_dialog_content = "Oh? Why do you call me Mother again? I would love to hear you call me mommy or I won't help you.",
  ui_story_5051_50510601_36_dialog_content = "W-Why?!",
  ui_story_5051_50510601_37_dialog_content = "That's what you get for being mean to the guest, Carleen.",
  ui_story_5051_50510601_38_dialog_content = "You're being so unpleasant toward someone you meet for the first time—that's not very nice.",
  ui_story_5051_50510601_39_dialog_content = "It's all your fault, shameless intruder! What have you done to beguile my sister and mother?!",
  ui_story_5051_50510601_40_dialog_content = "Nothing, I didn't do anything!",
  ui_story_5051_50510601_41_dialog_content = "Heehee, I wonder how long you can hold up.",
  ui_story_5051_50510601_42_dialog_content = "Boo-hoo—I'm sorry that I was being mean. Let me off the hook, please!",
  ui_story_5051_50510601_43_dialog_content = "Heehee, I haven't teased Carleen like this for a very long time. I'm out of breath from laughing so hard...",
  ui_story_5051_50510601_44_dialog_content = "Hmph... Bad Veronica...",
  ui_story_5051_50510601_45_dialog_content = "There you go, Veronica. You're at your cutest when you laugh.",
  ui_story_5051_50510601_46_dialog_content = "But Carleen is still grumpy... Should I tickle you?",
  ui_story_5051_50510601_47_dialog_content = "N-No, there's no need!",
  ui_story_5051_50510601_48_dialog_content = "This is what family should be like. Now only if Daniel is here too...",
  ui_story_5051_50510601_49_dialog_content = "Sorry for the trouble.",
  ui_story_5051_50510601_50_dialog_content = "I heard Veronica called you PlayerName. May I address you likewise?",
  ui_story_5051_50510601_51_dialog_content = "No problem, call me whatever you like.",
  ui_story_5051_50510601_52_dialog_content = "Similar to how you addressed Veronica as Mia?",
  ui_story_5051_50510601_53_dialog_content = "What? Uh...",
  ui_story_5051_50510601_54_dialog_content = "(Her mother heard the conversation between Mia and I?!)",
  ui_story_5051_50510601_X54_dialog_content = "Well, Mother, actually... PlayerName is a friend I made in Umbraton...",
  ui_story_5051_50510601_56_dialog_content = "It's okay, I would run around under an alias when I was young, too.",
  ui_story_5051_50510601_57_dialog_content = "I understand. There's always room for harmless secrets, no matter who it is.",
  ui_story_5051_50510601_58_dialog_content = "Thank you, Mother...",
  ui_story_5051_50510601_59_dialog_content = "Ah, I see. So little Mia saw our friend here as a brave knight in shining armor.",
  ui_story_5051_50510601_60_dialog_content = "Whose presence is sufficient to return a lost princess home, am I right?",
  ui_story_5051_50510601_61_dialog_content = "Oh, mother...",
  ui_story_5051_50510601_62_dialog_content = "So you're my sister's royal guard? But are you sure you can protect her with your scrawny, cowardly body?",
  ui_story_5051_50510601_63_dialog_content = "You got it wrong, little Carleen. Not a royal guard, but possibly Prince Charming!",
  ui_story_5051_50510601_64_dialog_content = "Mom! PlayerName is just a friend I met in Umbraton!",
  ui_story_5051_50510601_65_dialog_content = "A gentle, patient person who's helped me a lot, that's it...",
  ui_story_5051_50510601_66_dialog_content = "Harmless secrets? I don't get it...",
  ui_story_5051_50510601_67_dialog_content = "Surrender your secrets, despicable intruder!",
  ui_story_5051_50510601_68_dialog_content = "Uh, my name is PlayerName...",
  ui_story_5051_50510601_69_dialog_content = "(She stomps my foot...!)",
  ui_story_5051_50510601_70_dialog_content = "(This younger Carleen is also serious and precocious, but her face is more animated and more spirited overall.)",
  ui_story_5051_50510601_71_dialog_content = "(Her mother passed away, her sister disappeared, and the relationship with her father... She's gone through a lot of sorrow.)",
  ui_story_5051_50510601_72_dialog_content = "(Without all that, Carleen probably would smile more.)",
  ui_story_5051_50510601_73_dialog_content = "(And maybe she would still stomp my foot when she's angry.)",
  ui_story_5051_50510601_74_dialog_content = "Why are you staring at me? Do you wish for another stomp?",
  ui_story_5051_50510601_75_dialog_content = "No, not at all. Please spare me, Princess Carleen.",
  ui_story_5051_50510601_76_dialog_content = "Sorry, Carleen comes off so blunt only because she doesn't know how to express herself properly. She means no malice.",
  ui_story_5051_50510601_77_dialog_content = "Are you able to regain full memories of your family, Mi... Veronica?",
  ui_story_5051_50510601_78_dialog_content = "Yes. After reuniting with mother and Carleen, the memories came flooding back.",
  ui_story_5051_50510601_79_dialog_content = "Carleen and I loved to swing in the garden together...",
  ui_story_5051_50510601_80_dialog_content = "We'll never get tired of playing Guess Who?",
  ui_story_5051_50510601_81_dialog_content = "The memories, the emotions, the joy... They're all real, after all...",
  ui_story_5051_50510601_82_dialog_content = "Really? That's wonderful!",
  ui_story_5051_50510601_83_dialog_content = "(But Mia has yet to mention her father, and it was rather awkward when they met in the reception room.)",
  ui_story_5051_50510601_84_dialog_content = "(Could it be that she has a tepid relationship with him like Carleen?)",
  ui_story_5051_50510601_85_dialog_content = "Can I offer you a snack or a drink? It's available in the hall.",
  ui_story_5051_50510601_86_dialog_content = "Come on, Veronica, let's go grab some snack.",
  ui_story_5051_50510601_87_dialog_content = "Oh, don't yank me so hard...",
  ui_story_5051_50510601_88_dialog_content = "Don't just stand there, PlayerName, come with us.",
  ui_story_5051_50510601_89_dialog_content = "Haha... It's rare for the whole family to be together and I should not intrude.",
  ui_story_5051_50510601_90_dialog_content = "It's all right, child.",
  ui_story_5051_50510601_91_dialog_content = "I'm very familiar with that look in your eyes.",
  ui_story_5051_50510601_92_dialog_content = "It may seem determined, but it's also tainted with the glares of a lost child.",
  ui_story_5051_50510601_93_dialog_content = "You did not live in hardship in Umbraton, did you?",
  ui_story_5051_50510601_94_dialog_content = "No! Actually, I'm not from Umbraton. I'm...",
  ui_story_5051_50510601_95_dialog_content = "(No, can't tell the truth. Caelestite is a closed society, very few outsiders knew anything about us.)",
  ui_story_5051_50510601_96_dialog_content = "(So, mentioning I'm a Caelestite would only stress the crystal even more.)",
  ui_story_5051_50510601_97_dialog_content = "I'm just your nameless Joe Average.",
  ui_story_5051_50510601_98_dialog_content = "I don't have a family, so I like to travel and make new friends.",
  ui_story_5051_50510601_99_dialog_content = "Travel? I also like traveling. A shame I don't get the chance now.",
  ui_story_5051_50510601_100_dialog_content = "Are you happy with your life now, child?",
  ui_story_5051_50510601_101_dialog_content = "Yes, I feel very happy.",
  ui_story_5051_50510601_102_dialog_content = "That's good to hear.",
  ui_story_5051_50510601_103_dialog_content = "You're Veronica's friend and a kind child.",
  ui_story_5051_50510601_104_dialog_content = "Feel free to make yourself at home during your stay here.",
  ui_story_5051_50510601_105_dialog_content = "Thank you, My Lady...",
  ui_story_5051_50510601_106_dialog_content = "My name is Joshua and you may call me that.",
  ui_story_5051_50510601_107_dialog_content = "Yes. Well, I'd feel better addressing you as Lady Joshua.",
  ui_story_5051_50510601_108_dialog_content = "You went on a secret mission in Umbraton with Lumo Knights, Veronica?",
  ui_story_5051_50510601_109_dialog_content = "What kind of mission is that? And how do you and Lumo Knights fight? Can you tell me about it?",
  ui_story_5051_50510601_110_dialog_content = "Well...",
  ui_story_5051_50510601_111_dialog_content = "Yes, Veronica, can you explain it to me?",
  ui_story_5051_50510601_112_dialog_content = "<size=45>F-Father!</size>",
  ui_story_5051_50510601_113_dialog_content = "I would not object if you had a warrior's prowess to volunteer for a battle.",
  ui_story_5051_50510601_114_dialog_content = "But you deserted your post again and returned home to participate in the festivity.",
  ui_story_5051_50510601_115_dialog_content = "How are you going to atone for the farce, especially on the day of commemoration?",
  ui_story_5051_50510601_116_dialog_content = "...",
  ui_story_5051_50510601_117_dialog_content = "I recalled Veronica, dear.",
  ui_story_5051_50510601_118_dialog_content = "Today is the day all members of House Schwartz reunite, so shouldn't she be here with us?",
  ui_story_5051_50510601_119_dialog_content = "Joshua, just like you said, it's House Schwartz, not a family.",
  ui_story_5051_50510601_120_dialog_content = "House Schwartz has never had the precedence of a spoiled child and never will.",
  ui_story_5051_50510601_121_dialog_content = "Yes, we are a house, but much more of a family.",
  ui_story_5051_50510601_122_dialog_content = "How can we maintain a house if we can't even maintain the hearts of those closest to us?",
  ui_story_5051_50510601_123_dialog_content = "(Is that Schwartz?)",
  ui_story_5051_50510601_124_dialog_content = "(He's no less impressive in the future, but he definitely aged over the years and totally different than this.)",
  ui_story_5051_50510601_125_dialog_content = "(The tension is so thick and Mia doesn't look like she wants to be here... And my psychic powers pick now to abandon me!)",
  ui_story_5051_50510601_126_dialog_content = "Excuse me.",
  ui_story_5051_50510601_127_dialog_content = "(Ms. Blanc! In the same gown I saw earlier! So she was also working for the City Lord twelve years ago.)",
  ui_story_5051_50510601_128_dialog_content = "Who are you?",
  ui_story_5051_50510601_129_dialog_content = "Me? I'm Veronica's friend...",
  ui_story_5051_50510601_130_dialog_content = "Friend?",
  ui_story_5051_50510601_131_dialog_content = "Daniel.",
  ui_story_5051_50510601_132_dialog_content = "Fine. Treat the person as an honored guest, Ms. Rot.",
  ui_story_5051_50510601_133_dialog_content = "Okay.",
  ui_story_5051_50510601_134_dialog_content = "The Elder Council still awaits your presence, my lord.",
  ui_story_5051_50510601_135_dialog_content = "Since you brought Veronica back, Joshua, look after her.",
  ui_story_5051_50510601_136_dialog_content = "Do not allow her and her friend to raise any other trouble.",
  ui_story_5051_50510601_137_dialog_content = "No problem, I will watch after these children.",
  ui_story_5051_50510601_138_dialog_content = "So then, how about you stop being so mean, yourself?",
  ui_story_5051_50510601_139_dialog_content = "All right...",
  ui_story_5051_50510601_140_dialog_content = "The parade is about to begin. Get the children ready.",
  ui_story_5051_50510601_141_dialog_content = "Sigh...",
  ui_story_5051_50510601_142_dialog_content = "Are you feeling okay, Veronica?",
  ui_story_5051_50510601_143_dialog_content = "Your father isn't angry at you, he just has a lot on his table today.",
  ui_story_5051_50510601_144_dialog_content = "I... I...",
  ui_story_5051_50510601_145_dialog_content = "It's okay now, my child...",
  ui_story_5051_50510601_146_dialog_content = "Veronica...",
  ui_story_5051_50510601_147_dialog_content = "There's time before the parade, My Lady. You still have a chance to catch up with your family, just leave the rest to me.",
  ui_story_5051_50510601_148_dialog_content = "Thank you, Ms. Rot.",
  ui_story_5051_50510601_149_dialog_content = "Just doing my job.",
  ui_story_5051_50510601_150_dialog_content = "As for you, please come with me to get acclimated with the parade process and prepare for the upcoming events.",
  ui_story_5051_50510601_151_dialog_content = "Rest assured, Lady Joshua is adept at comforting others. Princess Veronica is in good hands.",
  ui_story_5051_50510601_152_dialog_content = "All right... Thank you, Ms. Blanc.",
  ui_story_5051_50510601_153_dialog_content = "Ms. Blanc? I didn't expect anyone to call me by that name here.",
  ui_story_5051_50510601_154_dialog_content = "May I ask how did you know about that name?",
  ui_story_5051_50510601_155_dialog_content = "(So Ms. Blanc didn't go by that twelve years ago?)",
  ui_story_5051_50510601_156_dialog_content = "(Come to think of it, the City Lord in the real world called her Ms. Rot too.)",
  ui_story_5051_50510601_157_dialog_content = "(That has to be the name when she's working for the City Lord... So how am I going to pass this off?)",
  ui_story_5051_50510601_158_dialog_content = "It is okay. Just like I have my secrets to keep, you have yours. That's only fair.",
  ui_story_5051_50510601_159_dialog_content = "You are an honored guest personally entrusted to me by the City Lord, therefore it is my duty to make sure your day is pleasant.",
  ui_story_5051_50510601_160_dialog_content = "However, I hope you will call me Ms. Rot in the meantime to expedite my obligations.",
  ui_story_5051_50510601_161_dialog_content = "Sure, Ms. Rot, I'm not going to make trouble for you.",
  ui_story_5051_50510601_162_dialog_content = "Thank you for your understanding. This way, please.",
  ui_story_5051_50510701_1_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50510701_2_dialog_content = "Please tell me where is the person in mind right now?",
  ui_story_5051_50510701_3_dialog_content = "<size=45>Abrahadabra!</size>",
  ui_story_5051_50510701_4_dialog_content = "Aha, up ahead!",
  ui_story_5051_50510701_5_dialog_content = "I heard another knight unit was transferred to Umbraton.",
  ui_story_5051_50510701_6_dialog_content = "What? What are they doing in Umbraton?",
  ui_story_5051_50510701_7_dialog_content = "Fighting the Eclipsite invasion, I guess. Umbraton in under Lumopolis' defense, after all.",
  ui_story_5051_50510701_8_dialog_content = "So why aren't we going?",
  ui_story_5051_50510701_9_dialog_content = "Are you stupid? We're the knights of <color=#FFB400>Kartima</color>. We can't go to a dump like that!",
  ui_story_5051_50510701_10_dialog_content = "Shh, keep it down! Don't let Sharona catch us slacking off again.",
  ui_story_5051_50510701_11_dialog_content = "Kartima is still the best. We're on even footing with the City Lord.",
  ui_story_5051_50510701_12_dialog_content = "I see...",
  ui_story_5051_50510701_13_dialog_content = "I see...",
  ui_story_5051_50510701_14_dialog_content = "Hey, who are you?",
  ui_story_5051_50510701_15_dialog_content = "Suspicious person! Quick, get her!",
  ui_story_5051_50510701_16_dialog_content = "Sorry, wrong place. Bye!",
  ui_story_5051_50510701_17_dialog_content = "Abrahadabra!",
  ui_story_5051_50510701_18_dialog_content = "Where am I now?",
  ui_story_5051_50510701_19_dialog_content = "Irridon got first place for the semester again...",
  ui_story_5051_50510701_20_dialog_content = "Irridon is not just pretty and a good student, she also enjoys prestige before the instructors of Dawn Academy.",
  ui_story_5051_50510701_21_dialog_content = "I'm green with envy.",
  ui_story_5051_50510701_22_dialog_content = "Maybe she'll even skip grades and go straight to graduation later.",
  ui_story_5051_50510701_23_dialog_content = "She's just too perfect.",
  ui_story_5051_50510701_24_dialog_content = "Irridon? Who's that?",
  ui_story_5051_50510701_25_dialog_content = "Who's that girl in the strange get-up? Her red hair is ravishing, though.",
  ui_story_5051_50510701_26_dialog_content = "What kind of costume is that? I'll have to report her to the Hall of Justice!",
  ui_story_5051_50510701_27_dialog_content = "Oops, wrong place again, sorry!",
  ui_story_5051_50510701_28_dialog_content = "Abra... hadabra...",
  ui_story_5051_50510701_29_dialog_content = "Is this... a restaurant?",
  ui_story_5051_50510701_30_dialog_content = "But I don't see anyone here.",
  ui_story_5051_50510701_31_dialog_content = "<color=#e8d9bb>Growl—</color>",
  ui_story_5051_50510701_32_dialog_content = "So, crystal ball, you brought me here because you knew I was hungry, right?",
  ui_story_5051_50510701_33_dialog_content = "But it's more urgent to find everyone! Not to mention it's useless to eat in the crystal!",
  ui_story_5051_50510701_34_dialog_content = "One more time!",
  ui_story_5051_50510701_35_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50510701_36_dialog_content = "Please tell me where is the person in mind right now?",
  ui_story_5051_50510701_37_dialog_content = "Abrahadabra!",
  ui_story_5051_50510701_38_dialog_content = "<size=45>Hahahahahaha!</size>",
  ui_story_5051_50510701_39_dialog_content = "W-Who's there?! You laugh is too loud and you freaked me out!",
  ui_story_5051_50510701_40_dialog_content = "Your divination skills are *hiccup* lame, girl.",
  ui_story_5051_50510701_41_dialog_content = "How dare you call my divination lame!",
  ui_story_5051_50510701_42_dialog_content = "I learned it from my mother, and she was the best divination master ever!",
  ui_story_5051_50510701_43_dialog_content = "Don't tell me you've never heard of <color=#FFB400>Boaz</color> of Northland!",
  ui_story_5051_50510701_44_dialog_content = "Boras? That sounds familiar... *hiccup*",
  ui_story_5051_50510701_45_dialog_content = "So what! Lame is still lame. You should just admit it!",
  ui_story_5051_50510701_46_dialog_content = "How rude! I'll show you—!",
  ui_story_5051_50510701_47_dialog_content = "*hiccup* You talk big for someone who can't back it up.",
  ui_story_5051_50510701_48_dialog_content = "How about we see whose divination is more accurate?",
  ui_story_5051_50510701_49_dialog_content = "You're on!",
  ui_story_5051_50510701_50_dialog_content = "Please pay your check, ladies.",
  ui_story_5051_50510701_51_dialog_content = "Huh? Uh, I got no money on me... *hiccup*",
  ui_story_5051_50510701_52_dialog_content = "What about you?",
  ui_story_5051_50510701_53_dialog_content = "Me? I don't know her, why should I pay?",
  ui_story_5051_50510701_54_dialog_content = "If you can't pay, wait here for the guards to take you in.",
  ui_story_5051_50510701_55_dialog_content = "What? No way, I got important things to do!",
  ui_story_5051_50510701_56_dialog_content = "You, say something! You started all this!",
  ui_story_5051_50510701_57_dialog_content = "Whew...",
  ui_story_5051_50510701_58_dialog_content = "She dozed off...",
  ui_story_5051_50510701_59_dialog_content = "Pay or go with the guards, your choice.",
  ui_story_5051_50510701_60_dialog_content = "All right... How much is it?",
  ui_story_5051_50510701_61_dialog_content = "127,938 Nightium.",
  ui_story_5051_50510701_62_dialog_content = "<size=45>How much?!</size>",
  ui_story_5051_50510701_63_dialog_content = "This lady imbibed many of our finest reserves, and a holiday discount is already included.",
  ui_story_5051_50510701_64_dialog_content = "Curses... My travel budget... My cache...",
  ui_story_5051_50510701_65_dialog_content = "(But all this in the Crystal of Eternal Memory probably isn't real so I should still have my money after I leave, right?)",
  ui_story_5051_50510701_66_dialog_content = "Here you go...",
  ui_story_5051_50510701_67_dialog_content = "Thank you.",
  ui_story_5051_50510701_68_dialog_content = "Hey, I just paid for you. Now you got no more excuses.",
  ui_story_5051_50510701_69_dialog_content = "I'll fight for my mother's honor today!",
  ui_story_5051_50510701_70_dialog_content = "Hey, where's she...?",
  ui_story_5051_50510701_71_dialog_content = "Over here... *hiccup*",
  ui_story_5051_50510701_72_dialog_content = "Hold it right there!",
  ui_story_5051_50510701_73_dialog_content = "Don't you try to get away through the crowd!",
  ui_story_5051_50510701_74_dialog_content = "All right, here it is...",
  ui_story_5051_50510701_75_dialog_content = "Got you!",
  ui_story_5051_50510701_76_dialog_content = "Not only was I forced to pay for you, now you tried to run...",
  ui_story_5051_50510701_77_dialog_content = "Let's see where can you run to now?",
  ui_story_5051_50510701_78_dialog_content = "Why should I run? Look, the one you're looking at is over there.",
  ui_story_5051_50510701_79_dialog_content = "The one I'm looking for...?",
  ui_story_5051_50510701_80_dialog_content = "Look, the parade is coming this way!",
  ui_story_5051_50510701_81_dialog_content = "See how impressive the City Lord is?",
  ui_story_5051_50510701_82_dialog_content = "And Princess Carleen and Princess Veronica are with him too!",
  ui_story_5051_50510701_83_dialog_content = "Lady Joshua—!",
  ui_story_5051_50510701_84_dialog_content = "Long live House Schwartz!",
  ui_story_5051_50510701_85_dialog_content = "Look up, Veronica, everyone is greeting you.",
  ui_story_5051_50510701_86_dialog_content = "Yes... right.",
  ui_story_5051_50510701_87_dialog_content = "Relax, here, hold my hand.",
  ui_story_5051_50510701_88_dialog_content = "(Mia still seems rather nervous.)",
  ui_story_5051_50510701_89_dialog_content = "(The parade will go on for a while. Will she hold up...?)",
  ui_story_5051_50510701_90_dialog_content = "(Never imagined Schwartz Family Day would be such a big celebration back then.)",
  ui_story_5051_50510701_91_dialog_content = "(Even though the banquet was extravagant enough, it still couldn't hold a candle to this celebration twelve years ago.)",
  ui_story_5051_50510701_92_dialog_content = "(What happened during the twelve years to change that?)",
  ui_story_5051_50510701_93_dialog_content = "(Also, the Eclipsites I ran across at the gate today certainly weren't transported by accident.)",
  ui_story_5051_50510701_94_dialog_content = "(Someone was taking advantage of the festivity to smuggle Eclipsites into Lumopolis.)",
  ui_story_5051_50510701_95_dialog_content = "(Can the Lumo Knights handle it? Or will it turn into a huge disaster in the end?)",
  ui_story_5051_50510701_96_dialog_content = "(Well, I hope it won't endanger anyone.)",
  ui_story_5051_50510701_97_dialog_content = "(Hmm, why do I get the feeling someone is watching me?)",
  ui_story_5051_50510701_98_dialog_content = "(Can't be, why watch me when I'm just along for the ride?)",
  ui_story_5051_50510701_99_dialog_content = "(And Ms. Rot did warn me not to wander around and ruin the parade.)",
  ui_story_5051_50510701_100_dialog_content = "(Stop wondering!)",
  ui_story_5051_50510701_101_dialog_content = "Hey, PlayerName! Mia!",
  ui_story_5051_50510701_102_dialog_content = "Hmm, the crowd is too noisy for them to hear me!",
  ui_story_5051_50510701_103_dialog_content = "Ah—Stop wasting effort.",
  ui_story_5051_50510701_104_dialog_content = "Even if they could hear you, they couldn't just leave the parade for you!",
  ui_story_5051_50510701_105_dialog_content = "I suppose...",
  ui_story_5051_50510701_106_dialog_content = "Say, how did you know they were the ones I was looking for?",
  ui_story_5051_50510701_107_dialog_content = "And how did you know they're gonna be here?",
  ui_story_5051_50510701_108_dialog_content = "Didn't you challenge me to a divination contest?",
  ui_story_5051_50510701_109_dialog_content = "I just won!",
  ui_story_5051_50510701_110_dialog_content = "...",
  ui_story_5051_50510701_111_dialog_content = "<size=45>Amazing!</size>",
  ui_story_5051_50510701_112_dialog_content = "<size=45>Please take me as your pupil!</size>",
  ui_story_5051_50510701_113_dialog_content = "Whoa, not so loud. You're giving me a headache...",
  ui_story_5051_50510701_114_dialog_content = "I don't take pupils. I'm just here for some odd jobs and to make booze money.",
  ui_story_5051_50510701_115_dialog_content = "Tonight... tomorrow, or maybe the day after that? Anyway, I'll leave whenever I have enough to drink.",
  ui_story_5051_50510701_116_dialog_content = "Then please at least tell me your name!",
  ui_story_5051_50510701_117_dialog_content = "(So I can track you down after I get out of this crystal!)",
  ui_story_5051_50510701_118_dialog_content = "All right, since you sprung for the meal...",
  ui_story_5051_50510701_119_dialog_content = "My name is Boaz.",
  ui_story_5051_50510701_120_dialog_content = "Huh?",
  ui_story_5051_50510701_121_dialog_content = "<color=#FFB400>Mom</color>?",
  ui_story_5051_50510701_122_dialog_content = "My gratitude goes out to all people of Lumopolis gathering here today to celebrate this special occasion.",
  ui_story_5051_50510701_123_dialog_content = "The House Schwartz is the city's crown jewel as well as the foundation.",
  ui_story_5051_50510701_124_dialog_content = "We defended you with the keen blades you forged for us.",
  ui_story_5051_50510701_125_dialog_content = "Today, we're here to praise the virtues of House Schwartz as well as those of the Lumopolis citizens!",
  ui_story_5051_50510701_126_dialog_content = "I hereby declare the commencement of Schwartz Family Day Celebration!",
  ui_story_5051_50510701_127_dialog_content = "Now, let the Showdown Ceremony begin!",
  ui_story_5051_50510701_128_dialog_content = "Wonderful opening speech, my lord!",
  ui_story_5051_50510701_129_dialog_content = "...",
  ui_story_5051_50510701_130_dialog_content = "This prosperity you are seeing now is the representation of Lumopolis' prowess.",
  ui_story_5051_50510701_131_dialog_content = "Only House Schwartz is fitting of such glory.",
  ui_story_5051_50510701_132_dialog_content = "There are accounts of Princess Veronica defeating Eclipsites attempting to infiltrate the city earlier today.",
  ui_story_5051_50510701_133_dialog_content = "She may be a trainee knight, but that's already just as impressive as an official knight.",
  ui_story_5051_50510701_134_dialog_content = "I heard that by the time the guards rushed to the scene, there was practically nothing left of the Eclipsites.",
  ui_story_5051_50510701_135_dialog_content = "If I recall correctly, the Kartimas are responsible for holiday security, don't they? I can't believe it...",
  ui_story_5051_50510701_136_dialog_content = "It is insignificant and not worth bringing up.",
  ui_story_5051_50510701_137_dialog_content = "I guess Veronica understood that as well, hence why she did not seek commendations from me.",
  ui_story_5051_50510701_138_dialog_content = "...",
  ui_story_5051_50510701_139_dialog_content = "It is much more than insignificant.",
  ui_story_5051_50510701_140_dialog_content = "The tale has spread throughout the city.",
  ui_story_5051_50510701_141_dialog_content = "\"Princess Veronica is more than she seems, resolving a crisis singlehandedly and effortlessly.\"",
  ui_story_5051_50510701_142_dialog_content = "I would imagine everybody would love to see how brilliant she fights.",
  ui_story_5051_50510701_143_dialog_content = "Upholding justice when there are wrongs to be righted is a commendable virtue.",
  ui_story_5051_50510701_144_dialog_content = "But she should not develop the habit of flaunting herself at this young age.",
  ui_story_5051_50510701_145_dialog_content = "Indulging in the facade will not get her anywhere.",
  ui_story_5051_50510701_146_dialog_content = "Please do not dismiss her thusly!",
  ui_story_5051_50510701_147_dialog_content = "Princess Veronica has maintained a low profile with hardly any fanfare.",
  ui_story_5051_50510701_148_dialog_content = "In comparison, Princess Carleen has been touted as a prodigal ruler since childhood.",
  ui_story_5051_50510701_149_dialog_content = "Princess Carleen will only continue to excel in the following years, whereas the prestige and authority of being the eldest for Princess Veronica will only...",
  ui_story_5051_50510701_150_dialog_content = "The affair of succession is not up to the likes of us to critique, Duke Troy!",
  ui_story_5051_50510701_151_dialog_content = "The City Lord has proven to be insightful and value talent.",
  ui_story_5051_50510701_152_dialog_content = "There must be sufficient thoughts behind recalling the princess from the frontline.",
  ui_story_5051_50510701_153_dialog_content = "Yes, you are right, putting someone in the position to succeed! I believe Princess Veronica will be better off back in the city.",
  ui_story_5051_50510701_154_dialog_content = "Please pardon my insolence, my lord.",
  ui_story_5051_50510701_155_dialog_content = "Father, I...",
  ui_story_5051_50510701_156_dialog_content = "Go get ready, Veronica.",
  ui_story_5051_50510701_157_dialog_content = "What, get ready?",
  ui_story_5051_50510701_158_dialog_content = "According to the schedule, you are up next.",
  ui_story_5051_50510701_159_dialog_content = "Do not keep the people waiting.",
  ui_story_5051_50510701_160_dialog_content = "Yeah, okay...!",
  ui_story_5051_50510701_161_dialog_content = "Both of you have been with me for years, and you seem to know exactly how I think.",
  ui_story_5051_50510701_162_dialog_content = "I had planned to save Veronica for the finale and show off the might of the new generation of House Schwartz.",
  ui_story_5051_50510701_163_dialog_content = "I just did not expect you two to see right through it.",
  ui_story_5051_50510701_164_dialog_content = "It was only a casual remark on my part, my lord.",
  ui_story_5051_50510701_165_dialog_content = "I'm very much looking forward to Princess Veronica's first outing.",
  ui_story_5051_50510701_166_dialog_content = "Are you really gonna do this, Mia?",
  ui_story_5051_50510701_167_dialog_content = "...",
  ui_story_5051_50510701_168_dialog_content = "I believe this is a good opportunity to run.",
  ui_story_5051_50510701_169_dialog_content = "We were supposed to just see Lady Joshua, but the City Lord's presence forced us to come here.",
  ui_story_5051_50510701_X169_dialog_content = "We missed the chance to ask Lady Joshua to help us find our friends, but we shouldn't keep involving ourselves deeper.",
  ui_story_5051_50510701_170_dialog_content = "Y-You're right... it's time we leave...",
  ui_story_5051_50510701_171_dialog_content = "The person up there is just an illusion and not my father... It's okay to decline... He won't get angry...",
  ui_story_5051_50510701_X171_dialog_content = "I have reiterated many times, Veronica, that you need not train for combat, for you have no talent in that domain.",
  ui_story_5051_50510701_X172_dialog_content = "Why do you shy from greeting others, Veronica? You are ten and not a young child anymore.",
  ui_story_5051_50510701_X173_dialog_content = "Join Lumo Knights? I'm not expecting you to stand out, Veronica, only for you not to worry your mother!",
  ui_story_5051_50510701_172_dialog_content = "Mia...?",
  ui_story_5051_50510701_173_dialog_content = "(Why is Mia shivering now? Is she afraid of bucking her father's orders?)",
  ui_story_5051_50510701_174_dialog_content = "(If that's the case, it'll only make her more stressed out if I force her to leave.)",
  ui_story_5051_50510701_175_dialog_content = "(And she has just gotten better lately!)",
  ui_story_5051_50510701_176_dialog_content = "OK...",
  ui_story_5051_50510701_177_dialog_content = "Do you want to join the duel, Mia?",
  ui_story_5051_50510701_178_dialog_content = "M-Me? I'm fine either way... Do you think I should, PlayerName?",
  ui_story_5051_50510701_179_dialog_content = "If fighting stops you from shivering, you should.",
  ui_story_5051_50510701_180_dialog_content = "What? Oh no, my condition...",
  ui_story_5051_50510701_181_dialog_content = "Your hand is so cold, Mia.",
  ui_story_5051_50510701_182_dialog_content = "Yeah, ever since I've been in this body, it's been feeling really cold.",
  ui_story_5051_50510701_183_dialog_content = "Your hand is very warm, PlayerName.",
  ui_story_5051_50510701_184_dialog_content = "And I can feel comfort and reassurance in the warmth...",
  ui_story_5051_50510701_185_dialog_content = "Thank you, I'm not afraid anymore.",
  ui_story_5051_50510701_X180_dialog_content = "Sorry to be a burden to you.",
  ui_story_5051_50510701_X181_dialog_content = "No, Mia, I promised to take you to the banquet and see your family, so I'm responsible for looking after you.",
  ui_story_5051_50510701_X182_dialog_content = "If fighting can ease your worries, you should do it!",
  ui_story_5051_50510701_X183_dialog_content = "All consequences are on me!",
  ui_story_5051_50510701_X184_dialog_content = "(We can still run after the fight, if nothing else!)",
  ui_story_5051_50510701_X185_dialog_content = "I know you're a gentle person, PlayerName... But why are you doing this...",
  ui_story_5051_50510701_X186_dialog_content = "Because we're friends.",
  ui_story_5051_50510701_X187_dialog_content = "What... Friends?",
  ui_story_5051_50510701_X188_dialog_content = "It's only natural for friends to lean on each other and make each other happy.",
  ui_story_5051_50510701_X189_dialog_content = "...",
  ui_story_5051_50510701_X190_dialog_content = "Uh, did you think that was weird?",
  ui_story_5051_50510701_X191_dialog_content = "Heehee, a little...",
  ui_story_5051_50510701_X192_dialog_content = "What's weird about that?",
  ui_story_5051_50510701_X193_dialog_content = "Because no one has treated me like a friend other than Baba Yaga.",
  ui_story_5051_50510701_X194_dialog_content = "Everyone saw me as Your Highness or Poor Mia...",
  ui_story_5051_50510701_X195_dialog_content = "Can I really enter the fight, PlayerName?",
  ui_story_5051_50510701_X196_dialog_content = "Yes, you can!",
  ui_story_5051_50510701_X197_dialog_content = "Thank you, I won't let you down.",
  ui_story_5051_50510701_X198_dialog_content = "Oh, dueling will also attract everyone's attention.",
  ui_story_5051_50510701_X199_dialog_content = "You can scan the crowd for my father and others in the meantime, PlayerName.",
  ui_story_5051_50510701_X200_dialog_content = "So we can find everybody even without my mother's help.",
  ui_story_5051_50510701_X201_dialog_content = "Judging from that, it's a pretty good decision to fight...",
  ui_story_5051_50510701_X202_dialog_content = "That's right, Mia! Guess my foolish optimism is rubbing off on you!",
  ui_story_5051_50510701_X203_dialog_content = "This way, Your Highness, the duel is about to begin.",
  ui_story_5051_50510701_X204_dialog_content = "Sure, I'm coming.",
  ui_story_5051_50510701_X205_dialog_content = "I'm off, then...!",
  ui_story_5051_50510701_X206_dialog_content = "You go, Mia!",
  ui_story_5051_50510701_186_dialog_content = "Go, Mia! And if you really can't win...",
  ui_story_5051_50510701_187_dialog_content = "If you should happen to come up short, I'll take a dive.",
  ui_story_5051_50510701_188_dialog_content = "What? And you are...",
  ui_story_5051_50510701_189_dialog_content = "Salutations, Princess Veronica, I'm your opponent.",
  ui_story_5051_50510701_190_dialog_content = "The City Lord has relayed instructions to me to spar with you while assuring your complete safety.",
  ui_story_5051_50510701_191_dialog_content = "Please pick out a ceremonial sword here. These training weapons will ensure that you do not hurt yourself accidentally.",
  ui_story_5051_50510701_192_dialog_content = "Also, as the opening event for Schwartz Family Day, you should not go down in defeat.",
  ui_story_5051_50510701_193_dialog_content = "All you have to do is work with me and knock me down when the time is right.",
  ui_story_5051_50510701_194_dialog_content = "Work with you and knock you down when the time is right?",
  ui_story_5051_50510701_195_dialog_content = "You mean it won't be a real match?",
  ui_story_5051_50510701_196_dialog_content = "Just a show like a stage play?",
  ui_story_5051_50510701_197_dialog_content = "I have reiterated many times, Veronica, that you need not train for combat, for you have no talent in that domain.",
  ui_story_5051_50510701_198_dialog_content = "Why do you shy from greeting others, Veronica? You are ten and not a young child anymore.",
  ui_story_5051_50510701_199_dialog_content = "Join Lumo Knights? I'm not expecting you to stand out, Veronica, only for you not to worry your mother!",
  ui_story_5051_50510701_200_dialog_content = "Snap out of it, Mia!",
  ui_story_5051_50510701_201_dialog_content = "PlayerName...",
  ui_story_5051_50510701_202_dialog_content = "You don't need your father's olive branch in order to prove yourself, Mia.",
  ui_story_5051_50510701_203_dialog_content = "The City Lord holds great authority, but that doesn't mean he can run your life for you.",
  ui_story_5051_50510701_204_dialog_content = "I don't know what kind of thoughts just ran through your mind...",
  ui_story_5051_50510701_205_dialog_content = "But I know you're not the person you were twelve years back!",
  ui_story_5051_50510701_206_dialog_content = "I...",
  ui_story_5051_50510701_207_dialog_content = "I'm sure you hate the fact this victory is predetermined.",
  ui_story_5051_50510701_208_dialog_content = "So prove to everybody you can win all on your own.",
  ui_story_5051_50510701_209_dialog_content = "But my opponent...",
  ui_story_5051_50510701_210_dialog_content = "If he's unwilling to fight you for real, make him!",
  ui_story_5051_50510701_211_dialog_content = "Make him? Push him to go all out? But can I manage that?",
  ui_story_5051_50510701_212_dialog_content = "Of course! Didn't they say the story of you wiping out the Eclipsites before the knights even showed up was already all over town?",
  ui_story_5051_50510701_213_dialog_content = "So how can an average guard be a match for you!",
  ui_story_5051_50510701_214_dialog_content = "Ahem, uh, I'm still here...",
  ui_story_5051_50510701_215_dialog_content = "Oh, oops, sorry...",
  ui_story_5051_50510701_216_dialog_content = "Since you heard all that, I guess we'll have it out in the open.",
  ui_story_5051_50510701_217_dialog_content = "Are you ready, Mia?",
  ui_story_5051_50510701_218_dialog_content = "You believe in me so much, PlayerName... This is the first time anyone has believed in me this much!",
  ui_story_5051_50510701_219_dialog_content = "I'm ready!",
  ui_story_5051_50510701_220_dialog_content = "Well then—",
  ui_story_5051_50510701_221_dialog_content = "\"White Night Up High. Valiant warrior, I hereby challenge you to a duel!\"",
  ui_story_5051_50510701_222_dialog_content = "\"Pick up a sword or lose your honor.\"",
  ui_story_5051_50510701_223_dialog_content = "\"Shall you accept my challenge, it constitutes a declaration of no regret even in the event of death!\"",
  ui_story_5051_50510701_224_dialog_content = "Uh, isn't death going a bit too far...?",
  ui_story_5051_50510701_225_dialog_content = "Yes, please spare me of a consequence I cannot bear the responsibility for...",
  ui_story_5051_50510701_226_dialog_content = "W-Well, I'm just repeating the lines from novels...",
  ui_story_5051_50510701_227_dialog_content = "Sigh... All right, I promise I will not go down or surrender easily.",
  ui_story_5051_50510701_228_dialog_content = "But if you can't defeat me, I'll still concede as instructed, since I'm just doing a job.",
  ui_story_5051_50510701_229_dialog_content = "That will be great. Thank you!",
  ui_story_5051_50510701_230_dialog_content = "So, the ceremonial sword...",
  ui_story_5051_50510701_231_dialog_content = "You should take that, Mia.",
  ui_story_5051_50510701_232_dialog_content = "Right. Please do not get yourself hurt.",
  ui_story_5051_50510701_233_dialog_content = "I thought that Mia might hurt you!",
  ui_story_5051_50510701_234_dialog_content = "W-What?",
  ui_story_5051_50510701_235_dialog_content = "That's true.",
  ui_story_5051_50510701_236_dialog_content = "You keep saying the name Mia...",
  ui_story_5051_50510701_237_dialog_content = "Is this mischievous girl before me truly the meek Princess Veronica herself?",
  ui_story_5051_50510701_238_dialog_content = "W-Why, of course! Mia is just...",
  ui_story_5051_50510701_239_dialog_content = "Mia is just a nickname between us!",
  ui_story_5051_50510701_240_dialog_content = "Oh, okay...",
  ui_story_5051_50510701_241_dialog_content = "It's about time. I will see you on the field soon, Your Highness.",
  ui_story_5051_50510701_242_dialog_content = "Okay. Just make sure you hold nothing back to the end!",
  ui_story_5051_50510701_243_dialog_content = "I-I shall...",
  ui_story_5051_50510701_244_dialog_content = "(Am I not just sent to do a job? Why do I feel like I just saw a teen dramedy?)",
  ui_story_5051_50510802_1_dialog_content = "(I can hear the crowd roaring even from here.)",
  ui_story_5051_50510802_2_dialog_content = "(Guess the celebration has started.)",
  ui_story_5051_50510802_3_dialog_content = "(Time to steal the Crystal of Eternal Memory...)",
  ui_story_5051_50510802_4_dialog_content = "Hey, you there, halt.",
  ui_story_5051_50510802_5_dialog_content = "(How come there still be a guard here?)",
  ui_story_5051_50510802_6_dialog_content = "I must ask you to clear your identity.",
  ui_story_5051_50510802_7_dialog_content = "My identity? I'm Sir Caleb Magnus! I don't need to prove who I am!",
  ui_story_5051_50510802_8_dialog_content = "Sir Caleb Magnus...?!",
  ui_story_5051_50510802_9_dialog_content = "No, he visited Lady Joshua a few days ago.",
  ui_story_5051_50510802_10_dialog_content = "You shared some resemblance, but his hair is much shorter and he has a different build!",
  ui_story_5051_50510802_11_dialog_content = "Surrender, intruder, or I will...",
  ui_story_5051_50510802_12_dialog_content = "Quiet, before you draw the attention of other soldiers!",
  ui_story_5051_50510802_13_dialog_content = "(This is the second time something unexpected happened. What a rough day.)",
  ui_story_5051_50510802_14_dialog_content = "(I must get the crystal before running out of Lumina...)",
  ui_story_5051_50510802_15_dialog_content = "I bought drinks!",
  ui_story_5051_50510802_16_dialog_content = "Oh, there you are.",
  ui_story_5051_50510802_17_dialog_content = "Hey, how come it's for hangovers?",
  ui_story_5051_50510802_18_dialog_content = "Well, you're still plastered and won't talk straight with me...",
  ui_story_5051_50510802_19_dialog_content = "That's because you just tackled me teary-eyed and got snot all over me.",
  ui_story_5051_50510802_20_dialog_content = "I don't care, I want booze!",
  ui_story_5051_50510802_21_dialog_content = "Fine, fine. I bought that too. Here.",
  ui_story_5051_50510802_22_dialog_content = "*Gulp* Yeah, good booze! Got a nice kick to it!",
  ui_story_5051_50510802_23_dialog_content = "So, ready to tell me more about divination?",
  ui_story_5051_50510802_24_dialog_content = "Sure, what do you want to hear?",
  ui_story_5051_50510802_25_dialog_content = "How much do you know about the spell to enter the Crystal of Eternal Memory?",
  ui_story_5051_50510802_26_dialog_content = "Why did those who went in not only weren't invisible, but scattered throughout the world?",
  ui_story_5051_50510802_27_dialog_content = "Crystal... Eternal Memories...?",
  ui_story_5051_50510802_28_dialog_content = "It's not something you ought to know, little girl.",
  ui_story_5051_50510802_29_dialog_content = "Who are you, really?",
  ui_story_5051_50510802_30_dialog_content = "Didn't I tell you I'm Jakine, your daughter?!",
  ui_story_5051_50510802_31_dialog_content = "Jakine? Are you joking?",
  ui_story_5051_50510802_32_dialog_content = "It's true I hardly go home, but it's impossible for Jakine who couldn't even walk...",
  ui_story_5051_50510802_33_dialog_content = "To be this tall in a blink of an eye!",
  ui_story_5051_50510802_34_dialog_content = "I'm the one who thinks this whole thing is a joke!",
  ui_story_5051_50510802_35_dialog_content = "But Mom, aren't you a mysterious, amazing, transcendent seer?",
  ui_story_5051_50510802_36_dialog_content = "Why are you a big wino?",
  ui_story_5051_50510802_37_dialog_content = "Who you calling big wino?!",
  ui_story_5051_50510802_38_dialog_content = "Call me *hiccup* a woman as inscrutable as the north wind—Boaz!",
  ui_story_5051_50510802_39_dialog_content = "What's that gotta do with anything?",
  ui_story_5051_50510802_40_dialog_content = "I'm not supposed to tell you this, but you're all I have right now.",
  ui_story_5051_50510802_41_dialog_content = "I'm only gonna say this once, so listen good!",
  ui_story_5051_50510802_42_dialog_content = "Huh?",
  ui_story_5051_50510802_43_dialog_content = "My mother is Boaz, and that's you.",
  ui_story_5051_50510802_44_dialog_content = "You created the Crystal of Eternal Memory, which we're in at this very moment.",
  ui_story_5051_50510802_45_dialog_content = "Twelve years from now, the Crystal's activator has passed away.",
  ui_story_5051_50510802_46_dialog_content = "To get into this world, I composed a spell according to the notes you left behind.",
  ui_story_5051_50510802_47_dialog_content = "But once I got here, not only wasn't I cloaked, but got separated from my friends...",
  ui_story_5051_50510802_48_dialog_content = "So what do I do now?",
  ui_story_5051_50510802_49_dialog_content = "I see...",
  ui_story_5051_50510802_50_dialog_content = "So you got it?",
  ui_story_5051_50510802_51_dialog_content = "I see your mom and I not only shared the same name, but she also plagiarized my work!",
  ui_story_5051_50510802_52_dialog_content = "My name is supposed to bring luck to people, but your mom... not quite.",
  ui_story_5051_50510802_53_dialog_content = "Why you—",
  ui_story_5051_50510802_54_dialog_content = "Get sloshed however you like, you wino!",
  ui_story_5051_50510802_55_dialog_content = "Booze has made you forget everything, even me and Dad! Don't you come home ever again!",
  ui_story_5051_50510802_56_dialog_content = "Don't speak with venom, girl.",
  ui_story_5051_50510802_57_dialog_content = "Did you say you made a spell to enter the crystal from your mom's notes?",
  ui_story_5051_50510802_58_dialog_content = "Who are you trying to fool? Even I couldn't do that!",
  ui_story_5051_50510802_59_dialog_content = "Anyone who could would be an unprecedented genius!",
  ui_story_5051_50510802_60_dialog_content = "G-Genius...?",
  ui_story_5051_50510802_61_dialog_content = "I'm an unprecedented genius?",
  ui_story_5051_50510802_62_dialog_content = "Hahaha, if I were your mother, I'd be happy as a clam!",
  ui_story_5051_50510802_63_dialog_content = "Hehe... You would?",
  ui_story_5051_50510802_64_dialog_content = "Wait, that's not the point!",
  ui_story_5051_50510802_65_dialog_content = "I want to know what do I do now?!",
  ui_story_5051_50510802_66_dialog_content = "Okay, recite the spell you made for me.",
  ui_story_5051_50510802_67_dialog_content = "Sure.",
  ui_story_5051_50510802_68_dialog_content = "Ad praeteritum! Ad praeteritum! Ad praeteritum!",
  ui_story_5051_50510802_69_dialog_content = "Let us relive the golden days of the past!",
  ui_story_5051_50510802_70_dialog_content = "Abrahadabra!",
  ui_story_5051_50510802_71_dialog_content = "That's it.",
  ui_story_5051_50510802_72_dialog_content = "Well, you mispronounced it.",
  ui_story_5051_50510802_73_dialog_content = "Huh?",
  ui_story_5051_50510802_74_dialog_content = "Not \"Abrahadabra,\" it's \"Abracadabra.\"",
  ui_story_5051_50510802_75_dialog_content = "What's the matter with you? So careless!",
  ui_story_5051_50510802_76_dialog_content = "But it's that way in the notes! See!",
  ui_story_5051_50510802_77_dialog_content = "Let me see... Such messy handwriting.",
  ui_story_5051_50510802_78_dialog_content = "Look it here, even went off the margin. No wonder you read it wrong.",
  ui_story_5051_50510802_79_dialog_content = "Did she write it under the influence?",
  ui_story_5051_50510802_80_dialog_content = "You're the one who wrote it!",
  ui_story_5051_50510802_81_dialog_content = "Hahahahah!",
  ui_story_5051_50510802_82_dialog_content = "This spell isn't half bad at all!",
  ui_story_5051_50510802_83_dialog_content = "But you still got a lot of details to look out for when you actually cast it.",
  ui_story_5051_50510802_84_dialog_content = "Did you hold hands when you came in?",
  ui_story_5051_50510802_85_dialog_content = "Nope...",
  ui_story_5051_50510802_86_dialog_content = "No wonder you weren't teleported together.",
  ui_story_5051_50510802_87_dialog_content = "I did tell everyone not to change this world in any way, though.",
  ui_story_5051_50510802_88_dialog_content = "So that shouldn't be a problem, right?",
  ui_story_5051_50510802_89_dialog_content = "Oh no, no, no...",
  ui_story_5051_50510802_90_dialog_content = "If you were not cloaked, even your breathing could change the world.",
  ui_story_5051_50510802_91_dialog_content = "What?",
  ui_story_5051_50510802_92_dialog_content = "If you've been noticed here, everything will make adjustments around you.",
  ui_story_5051_50510802_93_dialog_content = "Until at last...",
  ui_story_5051_50510802_94_dialog_content = "Until at last what?",
  ui_story_5051_50510802_95_dialog_content = "You become a part of this world and <color=#FFB400>can never leave</color>.",
  ui_story_5051_50510802_96_dialog_content = "<size=45>What?!</size>",
  ui_story_5051_50510802_97_dialog_content = "Not so loud, not so loud...",
  ui_story_5051_50510802_98_dialog_content = "Can we still make it? How much time do we have left?",
  ui_story_5051_50510802_99_dialog_content = "Well, the crystal can store up to about a day's worth...",
  ui_story_5051_50510802_100_dialog_content = "So as long as the day's not over, you should be okay! Maybe.",
  ui_story_5051_50510802_101_dialog_content = "We can still make it! Gotta meet back up with everybody and get out of here!",
  ui_story_5051_50510802_102_dialog_content = "Thanks, Mom! Bye, and I'll run you home one day!",
  ui_story_5051_50510802_103_dialog_content = "Hey, wait, where are you going?",
  ui_story_5051_50510802_104_dialog_content = "What are you doing? I-I got no money to buy you booze now!",
  ui_story_5051_50510802_105_dialog_content = "You've been trying to find them for a whole morning, right?",
  ui_story_5051_50510802_106_dialog_content = "And you wouldn't have found anyone without my help.",
  ui_story_5051_50510802_107_dialog_content = "Right.",
  ui_story_5051_50510802_108_dialog_content = "So, because your mom and I have the same name, I'll give you another nudge.",
  ui_story_5051_50510802_109_dialog_content = "I'll show you the proper technique.",
  ui_story_5051_50510802_110_dialog_content = "Really?!",
  ui_story_5051_50510802_111_dialog_content = "Yes, really. We ought to start before I change my mind.",
  ui_story_5051_50510901_1_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510901_2_dialog_content = "<anim type=Shake><size=32>Da...</size></anim>",
  ui_story_5051_50510901_3_dialog_content = "<anim type=Shake><size=32>an...</size></anim>",
  ui_story_5051_50510901_4_dialog_content = "<anim type=Shake><size=32>Daniel...</size></anim>",
  ui_story_5051_50510901_5_dialog_content = "<anim type=Shake><size=32>Veronica... Carleen...</size></anim>",
  ui_story_5051_50510901_6_dialog_content = "<anim type=Shake><size=37>Daniel... Veronica... Carleen...</size></anim>",
  ui_story_5051_50510901_7_dialog_content = "<anim type=Shake><size=42>Daniel! Veronica! Carleen!</size></anim>",
  ui_story_5051_50510901_8_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5051_50510901_9_dialog_content = "What?!",
  ui_story_5051_50510901_10_dialog_content = "PlayerName, are you okay?",
  ui_story_5051_50510901_11_dialog_content = "Why do you suddenly look ill?",
  ui_story_5051_50510901_12_dialog_content = "N-Nothing. The thunderclap made me jump, that's all.",
  ui_story_5051_50510901_13_dialog_content = "Thunderclap?",
  ui_story_5051_50510901_14_dialog_content = "I heard one this morning, but this one was louder than that.",
  ui_story_5051_50510901_15_dialog_content = "Maybe a storm is coming.",
  ui_story_5051_50510901_16_dialog_content = "How come I didn't hear any thunder?",
  ui_story_5051_50510901_17_dialog_content = "What? It wasn't loud enough for you to hear?",
  ui_story_5051_50510901_18_dialog_content = "Even if I did, I wouldn't be afraid.",
  ui_story_5051_50510901_19_dialog_content = "Eh, haha, Carleen... Princess Carleen truly is a courageous child.",
  ui_story_5051_50510901_20_dialog_content = "I am not a child anymore!",
  ui_story_5051_50510901_21_dialog_content = "...",
  ui_story_5051_50510901_22_dialog_content = "Carleen?",
  ui_story_5051_50510901_23_dialog_content = "(She ran back to Lady Joshua again.)",
  ui_story_5051_50510901_24_dialog_content = "(The look in her eyes stayed the same as now.)",
  ui_story_5051_50510901_25_dialog_content = "That's how Princess Carleen is. She might hold a grudge if you treated her like a child.",
  ui_story_5051_50510901_26_dialog_content = "However, you might be the first person she took an interest in.",
  ui_story_5051_50510901_27_dialog_content = "Interest?",
  ui_story_5051_50510901_28_dialog_content = "Didn't you notice that Her Highness has been observing you for a long while now?",
  ui_story_5051_50510901_29_dialog_content = "Is she still warning me...?",
  ui_story_5051_50510901_30_dialog_content = "Uh, Mia... Veronica is still fighting the soldier, I have to root her on!",
  ui_story_5051_50510901_31_dialog_content = "This is what I can do!",
  ui_story_5051_50510901_32_dialog_content = "Ugh... Cough, cough.",
  ui_story_5051_50510901_33_dialog_content = "Princess Veronica still hasn't applied full strength, yet she is outclassing her opponent.",
  ui_story_5051_50510901_34_dialog_content = "It's only been a few days and she has made astounding progress.",
  ui_story_5051_50510901_35_dialog_content = "I'm curious about what you have done for Princess Veronica, PlayerName.",
  ui_story_5051_50510901_36_dialog_content = "(Mia almost never believed in herself along the way.)",
  ui_story_5051_50510901_37_dialog_content = "(So she never had the rep as a good fighter to anyone in the past?)",
  ui_story_5051_50510901_38_dialog_content = "The silent treatment? I guess it's another one of those secrets I'm not meant to know.",
  ui_story_5051_50510901_39_dialog_content = "Actually, it's no secret.",
  ui_story_5051_50510901_40_dialog_content = "Veronica has always been formidable. She just never realized it in the past.",
  ui_story_5051_50510901_41_dialog_content = "Oh?",
  ui_story_5051_50510901_42_dialog_content = "That was close! Princess Veronica almost struck that guard.",
  ui_story_5051_50510901_43_dialog_content = "I can see the sparks off the clashing blades from here... What a genuine duel!",
  ui_story_5051_50510901_44_dialog_content = "We will only cheer for you from here forth, Princess Veronica!",
  ui_story_5051_50510901_45_dialog_content = "Hooray!",
  ui_story_5051_50510901_46_dialog_content = "Princess Veronica has garnered applause and cheers with her sword-fighting skills.",
  ui_story_5051_50510901_47_dialog_content = "Speaking of which, did you mistake the applauses for thunder?",
  ui_story_5051_50510901_48_dialog_content = "Is that so...?",
  ui_story_5051_50510901_49_dialog_content = "(Hey, wait!)",
  ui_story_5051_50510901_50_dialog_content = "(Why do I feel a chill running down my spine?)",
  ui_story_5051_50510901_51_dialog_content = "(Someone is watching me!)",
  ui_story_5051_50510901_52_dialog_content = "(It's not Carleen, the City Lord, or Lady Joshua who are both fixated on their daughter's fight.)",
  ui_story_5051_50510901_53_dialog_content = "(Don't tell me this vibe is...)",
  ui_story_5051_50510901_54_dialog_content = "Where are you going, PlayerName?",
  ui_story_5051_50510901_55_dialog_content = "I, uh, would like to use the restroom.",
  ui_story_5051_50510901_56_dialog_content = "Allow me to lead the way.",
  ui_story_5051_50510901_57_dialog_content = "I can manage myself, thank you!",
  ui_story_5051_50510901_58_dialog_content = "PlayerName sure runs fast.",
  ui_story_5051_50510901_59_dialog_content = "This friend of Princess Veronica's certainly is intriguing.",
  ui_story_5051_50510901_60_dialog_content = "The source ought to be here somewhere...",
  ui_story_5051_50510901_61_dialog_content = "Ahem.",
  ui_story_5051_50510901_62_dialog_content = "It was you, City Lord!",
  ui_story_5051_50510901_63_dialog_content = "You are very perceptive, PlayerName.",
  ui_story_5051_50510901_64_dialog_content = "How did you get here?",
  ui_story_5051_50510901_65_dialog_content = "Young people love celebrations, so I thought I would find you here.",
  ui_story_5051_50510901_66_dialog_content = "I just did not figure you would meet <color=#FFB400>this world's version of me</color> so soon.",
  ui_story_5051_50510901_67_dialog_content = "That's because...",
  ui_story_5051_50510901_68_dialog_content = "I should know by now that we are involved in history as recorded by the Crystal of Eternal Memory.",
  ui_story_5051_50510901_69_dialog_content = "We are seen by the world that we are supposed to be cloaked from.",
  ui_story_5051_50510901_70_dialog_content = "That's been bothering me too... What went wrong exactly?",
  ui_story_5051_50510901_71_dialog_content = "I believe it is too late to speculate on that now, young one.",
  ui_story_5051_50510901_72_dialog_content = "It has happened. What is urgent is trying to avoid all potential risks while searching for a solution.",
  ui_story_5051_50510901_73_dialog_content = "Jakine did say not to attempt to change the history in the Crystal or face potentially grave consequences.",
  ui_story_5051_50510901_74_dialog_content = "In order to keep things in order in this world, we must keep a low profile.",
  ui_story_5051_50510901_75_dialog_content = "Mia and I had to come into town to find the others...",
  ui_story_5051_50510901_76_dialog_content = "...",
  ui_story_5051_50510901_77_dialog_content = "Why are you frowning, City Lord?",
  ui_story_5051_50510901_78_dialog_content = "Did Mia meet them?",
  ui_story_5051_50510901_79_dialog_content = "Them as in...?",
  ui_story_5051_50510901_80_dialog_content = "You know who I am referring to.",
  ui_story_5051_50510901_81_dialog_content = "Ahem. If you mean Lady Joshua, young Carleen, and this world's Lord Schwartz...",
  ui_story_5051_50510901_82_dialog_content = "Yes, they met and accepted Mia, even calling her Veronica.",
  ui_story_5051_50510901_83_dialog_content = "Mia's appearance indeed has remained the same as back then.",
  ui_story_5051_50510901_84_dialog_content = "So... You're admitting it?",
  ui_story_5051_50510901_85_dialog_content = "That Mia is Princess Veronica, your daughter?",
  ui_story_5051_50510901_86_dialog_content = "Our action has disrupted this realm.",
  ui_story_5051_50510901_87_dialog_content = "And you... Why did you endanger Mia by allowing her to duel the guard?",
  ui_story_5051_50510901_88_dialog_content = "Have you ever considered the ramifications if she is hurt?",
  ui_story_5051_50510901_89_dialog_content = "As the Lumopolis City Lord's daughter, Mia has been hidden away in Umbraton.",
  ui_story_5051_50510901_90_dialog_content = "Has her father ever considered the ramifications if Mia got hurt in Umbraton?",
  ui_story_5051_50510901_91_dialog_content = "Remember this, young one.",
  ui_story_5051_50510901_92_dialog_content = "If you do not know every facet of a story, do not judge prematurely.",
  ui_story_5051_50510901_93_dialog_content = "Sorry. I confess, I have no idea what happened between you.",
  ui_story_5051_50510901_94_dialog_content = "But I don't think you realized Mia's true potential either.",
  ui_story_5051_50510901_95_dialog_content = "What?",
  ui_story_5051_50510901_96_dialog_content = "Nice move!",
  ui_story_5051_50510901_97_dialog_content = "Princess Veronica! Princess Veronica! Princess Veronica!",
  ui_story_5051_50510901_98_dialog_content = "Look, Mia's sword fighting has earned the people's recognition and cheers.",
  ui_story_5051_50510901_99_dialog_content = "The Mia I used to know could never fight.",
  ui_story_5051_50510901_100_dialog_content = "But she has become very formidable in combat now...",
  ui_story_5051_50510901_101_dialog_content = "Mia wanted to seize this opportunity to show her father she could accomplish more.",
  ui_story_5051_50510901_102_dialog_content = "However, now is not the right time.",
  ui_story_5051_50510901_103_dialog_content = "We must end this match for Mia quickly, PlayerName.",
  ui_story_5051_50510901_104_dialog_content = "Why? I don't get it. Mia is about to win.",
  ui_story_5051_50510901_105_dialog_content = "Do you still not believe in her?",
  ui_story_5051_50510901_106_dialog_content = "Do you know what happened in the ceremony that year, PlayerName?",
  ui_story_5051_50510901_107_dialog_content = "Huh?",
  ui_story_5051_50510901_108_dialog_content = "I'm about to give everything I got now, Princess Veronica!",
  ui_story_5051_50510901_109_dialog_content = "Got it. Please hold nothing back.",
  ui_story_5051_50510901_110_dialog_content = "Hi-yah!",
  ui_story_5051_50510901_111_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50510901_112_dialog_content = "What... You even blocked that?",
  ui_story_5051_50510901_113_dialog_content = "I got lucky.",
  ui_story_5051_50510901_114_dialog_content = "(He put so much behind the blow, I barely fought it off.)",
  ui_story_5051_50510901_115_dialog_content = "(Wonder if PlayerName saw that?)",
  ui_story_5051_50510901_116_dialog_content = "(Hey, where is PlayerName?)",
  ui_story_5051_50510901_117_dialog_content = "(Gotcha! But the person next to...)",
  ui_story_5051_50510901_118_dialog_content = "Watch out, Veronica!",
  ui_story_5051_50510901_119_dialog_content = "Hi-yah!",
  ui_story_5051_50510901_120_dialog_content = "(What now? I-I don't think I can take this one.)",
  ui_story_5051_50510901_121_dialog_content = "(Run away? N-No way, not when Father is watching...)",
  ui_story_5051_50510901_122_dialog_content = "(I still got time to charge up for a counterattack!)",
  ui_story_5051_50510901_123_dialog_content = "Is she going to release <color=#FFB400>that thing</color>?",
  ui_story_5051_50510901_124_dialog_content = "Veronica...",
  ui_story_5051_50510901_125_dialog_content = "(No, how can I forget the fact that Father doesn't want me summoning Hippoca...)",
  ui_story_5051_50510901_126_dialog_content = "(But what about the energy I already charged up? It's going to end up hurting the guard.)",
  ui_story_5051_50510901_127_dialog_content = "(What to do, what to do?)",
  ui_story_5051_50510901_128_dialog_content = "(What are those boxes over there? Maybe they can withstand the force!)",
  ui_story_5051_50510901_129_dialog_content = "What's going on, why is Mia running off to the side?",
  ui_story_5051_50510901_130_dialog_content = "Another second and she would have summoned with her Lumina!",
  ui_story_5051_50510901_131_dialog_content = "...",
  ui_story_5051_50510901_132_dialog_content = "Never summon that monster in public from now on, Veronica.",
  ui_story_5051_50510901_133_dialog_content = "Hippoca is not a monster.",
  ui_story_5051_50510901_134_dialog_content = "You named that spider with a horse head?",
  ui_story_5051_50510901_135_dialog_content = "Doesn't Carleen have a horse too?",
  ui_story_5051_50510901_136_dialog_content = "You have no talent for fighting, Veronica. Argue about it no further.",
  ui_story_5051_50510901_137_dialog_content = "Sigh...",
  ui_story_5051_50510901_138_dialog_content = "I seems she still remembers that.",
  ui_story_5051_50510901_139_dialog_content = "Mia is crashing into those boxes!",
  ui_story_5051_50510901_140_dialog_content = "What!?",
  ui_story_5051_50510901_141_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5051_50510901_142_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_5051_50510901_143_dialog_content = "Eclipsites? There are Eclipsites!",
  ui_story_5051_50510901_144_dialog_content = "Why are so many Eclipsites hiding in those background boxes?",
  ui_story_5051_50510901_145_dialog_content = "Run! Run!",
  ui_story_5051_50510901_146_dialog_content = "Ah, w-what's going on here?",
  ui_story_5051_50510901_147_dialog_content = "Is it because of me?",
  ui_story_5051_50510901_148_dialog_content = "<anim type=Shake>Gahhhh!</anim>",
  ui_story_5051_50510901_149_dialog_content = "I-I knew I shouldn't try to show off here...",
  ui_story_5051_50510901_150_dialog_content = "This is what would happen when I tried.",
  ui_story_5051_50510901_151_dialog_content = "It never ends well...",
  ui_story_5051_50510901_152_dialog_content = "Join Lumo Knights? I'm not expecting you to stand out, Veronica, only for you not to worry your mother!",
  ui_story_5051_50510901_153_dialog_content = "Please do not follow us into battle, Your Highness. Just stay where it is safe!",
  ui_story_5051_50510901_154_dialog_content = "What's wrong, Veronica?",
  ui_story_5051_50510901_155_dialog_content = "No!",
  ui_story_5051_50510901_156_dialog_content = "It's all because of me that...",
  ui_story_5051_50510901_157_dialog_content = "Watch out! Step back!",
  ui_story_5051_50510901_158_dialog_content = "Huh?",
  ui_story_5051_50510901_159_dialog_content = "<anim type=Shake>Grahhhhhh!</anim>",
  ui_story_5051_50510901_160_dialog_content = "The Sovereign's Blade!",
  ui_story_5051_50510901_161_dialog_content = "Father? T-The real father?",
  ui_story_5051_50510901_162_dialog_content = "Are you all right, Mia?",
  ui_story_5051_50510901_163_dialog_content = "I'm fine, PlayerName, just got somewhat distracted.",
  ui_story_5051_50510901_164_dialog_content = "Are you sure you are fine?",
  ui_story_5051_50510901_165_dialog_content = "I-I'm fine!",
  ui_story_5051_50510901_166_dialog_content = "Very well, let's charge.",
  ui_story_5051_50510901_167_dialog_content = "This is the first time you're fighting along my side, Father.",
  ui_story_5051_50510901_168_dialog_content = "And...",
  ui_story_5051_50510901_169_dialog_content = "If you would like to summon Hippoca, go ahead.",
  ui_story_5051_50510901_170_dialog_content = "Father?",
  ui_story_5051_50510901_171_dialog_content = "Ready?",
  ui_story_5051_50510901_172_dialog_content = "Right.",
  ui_story_5051_50510901_173_dialog_content = "<color=#e8d9bb>On the Other Side</color>",
  ui_story_5051_50510901_174_dialog_content = "Those black monsters... They're Eclipsites?!",
  ui_story_5051_50510901_175_dialog_content = "I can protect us too, Mother!",
  ui_story_5051_50510901_176_dialog_content = "I believe you have the ability, Carleen, but now is not the time, okay?",
  ui_story_5051_50510901_177_dialog_content = "... Okay.",
  ui_story_5051_50510901_178_dialog_content = "Ms. Rot will cover your and Carleen's retreat, Joshua. Go now!",
  ui_story_5051_50510901_179_dialog_content = "Daniel, I can...",
  ui_story_5051_50510901_180_dialog_content = "Do not worry, Joshua.",
  ui_story_5051_50510901_181_dialog_content = "I will bring Veronica back safe and sound.",
  ui_story_5051_50510901_182_dialog_content = "I want to see both of you home unscathed.",
  ui_story_5051_50510901_183_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_5051_50510901_184_dialog_content = "A sovereign's slash!",
  ui_story_5051_50510901_185_dialog_content = "I see these creatures have spread to here now.",
  ui_story_5051_50510901_186_dialog_content = "Well, you are just asking for it.",
  ui_story_5051_50511001_1_dialog_content = "Invenire eum! Invenire eum! Invenire eum!",
  ui_story_5051_50511001_2_dialog_content = "Please tell me where is the City Lord I'm thinking of right now?",
  ui_story_5051_50511001_3_dialog_content = "<size=42>Abracadabra!</size>",
  ui_story_5051_50511001_4_dialog_content = "<color=#e8d9bb>Buzz!</color>",
  ui_story_5051_50511001_5_dialog_content = "Whoa, this is the first time my crystal ball responded so intensely!",
  ui_story_5051_50511001_6_dialog_content = "I guess I never said the final incantation correctly before...",
  ui_story_5051_50511001_7_dialog_content = "But I'm very curious...",
  ui_story_5051_50511001_8_dialog_content = "Why does \"Abracadabra\" has to go on the end every time?",
  ui_story_5051_50511001_9_dialog_content = "Does \"Abracadabra\" carry any special meanings?",
  ui_story_5051_50511001_10_dialog_content = "Huh? Oh, what is it again...",
  ui_story_5051_50511001_11_dialog_content = "Yeah, I remember now!",
  ui_story_5051_50511001_12_dialog_content = "\"I'll destroy you if you don't obey!\"",
  ui_story_5051_50511001_13_dialog_content = "What?!",
  ui_story_5051_50511001_14_dialog_content = "Hahahaha, you looked so freaked out! This is fun!",
  ui_story_5051_50511001_15_dialog_content = "Are you mocking me?",
  ui_story_5051_50511001_16_dialog_content = "<size=30>Did I imagine my mom's kindness when I was a child all on my own?</size>",
  ui_story_5051_50511001_17_dialog_content = "Quit mumbling! You're going to lose the message if you don't talk to that crystal ball soon.",
  ui_story_5051_50511001_18_dialog_content = "Oh, almost forgot about it!",
  ui_story_5051_50511001_19_dialog_content = "The crystal ball says...",
  ui_story_5051_50511001_20_dialog_content = "Lord Schwartz is where PlayerName and Mia are?",
  ui_story_5051_50511001_21_dialog_content = "So they've already met up.",
  ui_story_5051_50511001_22_dialog_content = "That means I've wasted all this time with you!",
  ui_story_5051_50511001_23_dialog_content = "How could this be a waste of time?",
  ui_story_5051_50511001_24_dialog_content = "I taught you my secrets to you!",
  ui_story_5051_50511001_25_dialog_content = "Oh yeah, you're right!",
  ui_story_5051_50511001_26_dialog_content = "And this is my first time nailing someone's whereabouts with precision!",
  ui_story_5051_50511001_27_dialog_content = "But...",
  ui_story_5051_50511001_28_dialog_content = "Can you tell me what \"Abracadabra\" really means now?",
  ui_story_5051_50511001_29_dialog_content = "Ouch, that hurts, I have a headache!",
  ui_story_5051_50511001_30_dialog_content = "I need a couple more drinks to settle down and remind me.",
  ui_story_5051_50511001_31_dialog_content = "Pulling that again?",
  ui_story_5051_50511001_32_dialog_content = "It should be fine here, right?",
  ui_story_5051_50511001_33_dialog_content = "We should move a bit farther to be safe. Keep it up!",
  ui_story_5051_50511001_34_dialog_content = "Hey, why is everybody running from the square?",
  ui_story_5051_50511001_35_dialog_content = "Stay calm, do not trip and fall!",
  ui_story_5051_50511001_36_dialog_content = "Excuse me—",
  ui_story_5051_50511001_37_dialog_content = "What?",
  ui_story_5051_50511001_38_dialog_content = "Whoa, you look younger than I am!",
  ui_story_5051_50511001_39_dialog_content = "What can I do for you?",
  ui_story_5051_50511001_40_dialog_content = "Oh, I'm just wondering what happened at the square.",
  ui_story_5051_50511001_41_dialog_content = "Nothing specific yet, but I'm ordered to lead an evacuation.",
  ui_story_5051_50511001_42_dialog_content = "But the people I'm looking for are still there!",
  ui_story_5051_50511001_43_dialog_content = "Wait a minute, your appearance...",
  ui_story_5051_50511001_44_dialog_content = "Oh, everybody told me I looked like my mom... Uh, I mean, Boaz.",
  ui_story_5051_50511001_45_dialog_content = "Long red hair and green eyes... Are you Jakine?",
  ui_story_5051_50511001_46_dialog_content = "How do you know my name?",
  ui_story_5051_50511001_47_dialog_content = "Wait, wait, wait, don't tell me I brought you in here by mistake too!",
  ui_story_5051_50511001_48_dialog_content = "Pardon me, I don't understand what you're talking about.",
  ui_story_5051_50511001_49_dialog_content = "However, Princess Veronica's friend, PlayerName, asked us to look out for you and two other gentlemen.",
  ui_story_5051_50511001_50_dialog_content = "Yes, I'm trying to find PlayerName too!",
  ui_story_5051_50511001_51_dialog_content = "But the guy's probably still in the central square.",
  ui_story_5051_50511001_52_dialog_content = "Come with me now. When everything settles down, I'll take you to PlayerName.",
  ui_story_5051_50511001_53_dialog_content = "Appreciate the thoughts, but...",
  ui_story_5051_50511001_54_dialog_content = "I'm running out of time and gotta meet back up with everyone!",
  ui_story_5051_50511001_55_dialog_content = "So you're just going to cut right through the masses of Eclipsites, with a wasted lady in tow?",
  ui_story_5051_50511001_56_dialog_content = "Eclipsites?",
  ui_story_5051_50511001_57_dialog_content = "No, you're wasted!",
  ui_story_5051_50511001_58_dialog_content = "Well, that's rather problematic.",
  ui_story_5051_50511001_59_dialog_content = "Can you watch this lady, then?",
  ui_story_5051_50511001_60_dialog_content = "Are you going to try to find them by yourself?",
  ui_story_5051_50511001_61_dialog_content = "Don't judge me by my looks. Eclipsites are nothing to me.",
  ui_story_5051_50511001_62_dialog_content = "You think you can leave me behind after what you learned from me?",
  ui_story_5051_50511001_63_dialog_content = "Do you think that I, Boaz, am afraid of Eclipsites?",
  ui_story_5051_50511001_64_dialog_content = "Thank you for teaching me the right incantation.",
  ui_story_5051_50511001_65_dialog_content = "Although we're only briefly together, I really appreciate the time, and if possible...",
  ui_story_5051_50511001_66_dialog_content = "I wouldn't want to leave you now.",
  ui_story_5051_50511001_67_dialog_content = "But I just can't abandon my friends!",
  ui_story_5051_50511001_68_dialog_content = "They wouldn't be in this mess if it wasn't for me.",
  ui_story_5051_50511001_69_dialog_content = "I don't understand a single word. Just take me with you, you must!",
  ui_story_5051_50511001_70_dialog_content = "You don't want me to teach you anymore? And I still need more booze!",
  ui_story_5051_50511001_71_dialog_content = "...",
  ui_story_5051_50511001_72_dialog_content = "I respect you for thinking about your friends in this situation, Jakine.",
  ui_story_5051_50511001_73_dialog_content = "To be honest, I would like to help with the battle in the square.",
  ui_story_5051_50511001_74_dialog_content = "If you insist on going, I can take you.",
  ui_story_5051_50511001_75_dialog_content = "Really?",
  ui_story_5051_50511001_76_dialog_content = "Follow me, I'll clear the Eclipsites for you!",
  ui_story_5051_50511002_1_dialog_content = "How does it look?",
  ui_story_5051_50511002_2_dialog_content = "The vicinity should be clear of Eclipsites now.",
  ui_story_5051_50511002_3_dialog_content = "Excellent.",
  ui_story_5051_50511002_4_dialog_content = "There is a shortcut over there to exit the overran areas quickly.",
  ui_story_5051_50511002_5_dialog_content = "You two, follow me.",
  ui_story_5051_50511002_6_dialog_content = "We're leaving now?",
  ui_story_5051_50511002_7_dialog_content = "You've fought long enough and need a rest.",
  ui_story_5051_50511002_8_dialog_content = "But...",
  ui_story_5051_50511002_9_dialog_content = "No buts.",
  ui_story_5051_50511002_10_dialog_content = "We cannot squander too much time or energy here.",
  ui_story_5051_50511002_11_dialog_content = "I want to help clear out the Eclipsites...",
  ui_story_5051_50511002_12_dialog_content = "<size=45>Stop worrying about that, hurry and go!</size>",
  ui_story_5051_50511002_13_dialog_content = "Huh?",
  ui_story_5051_50511002_14_dialog_content = "You have no talent for fighting, Veronica. Argue about it no further.",
  ui_story_5051_50511002_15_dialog_content = "Hmm...",
  ui_story_5051_50511002_X15_dialog_content = "(Mia has the same demeanor as before the duel.)",
  ui_story_5051_50511002_X16_dialog_content = "(Is she reminded of something unpleasant in the past again?)",
  ui_story_5051_50511002_16_dialog_content = "What's on your mind, Mia?",
  ui_story_5051_50511002_17_dialog_content = "S-Sorry!",
  ui_story_5051_50511002_18_dialog_content = "It's all my fault...",
  ui_story_5051_50511002_19_dialog_content = "Did you just freak Mia out with what you said, City Lord?",
  ui_story_5051_50511002_20_dialog_content = "She just got better recently and that was probably too much for her.",
  ui_story_5051_50511002_21_dialog_content = "...",
  ui_story_5051_50511002_22_dialog_content = "I-I still cannot live up to Father's expectations.",
  ui_story_5051_50511002_23_dialog_content = "I don't deserve to be his child, I don't deserve it...",
  ui_story_5051_50511002_X21_dialog_content = "I admit I shouldn't dig into your family affairs.",
  ui_story_5051_50511002_X22_dialog_content = "But it's not normal for a child to be so fearful of her own father!",
  ui_story_5051_50511002_24_dialog_content = "Why is Mia so terrified of you?",
  ui_story_5051_50511002_25_dialog_content = "Is it because...",
  ui_story_5051_50511002_26_dialog_content = "You abandoned Mia in Umbraton and neglected her for all these years?",
  ui_story_5051_50511002_27_dialog_content = "I have never forsaken her for even one day!",
  ui_story_5051_50511002_28_dialog_content = "You do not need to know the details.",
  ui_story_5051_50511002_X28_dialog_content = "You have no right to judge my family.",
  ui_story_5051_50511002_X29_dialog_content = "Please don't be so mean to PlayerName, Father...",
  ui_story_5051_50511002_X30_dialog_content = "Quiet, I know what I am doing.",
  ui_story_5051_50511002_X31_dialog_content = "No, you can't be so mean to PlayerName...!",
  ui_story_5051_50511002_X32_dialog_content = "Mia...?",
  ui_story_5051_50511002_X33_dialog_content = "Lord of Lumopolis, Guardian of the House... You have a lot of impressive titles.",
  ui_story_5051_50511002_X34_dialog_content = "But all of them only suffocate me.",
  ui_story_5051_50511002_X35_dialog_content = "Maybe others see you as majestic and sublime.",
  ui_story_5051_50511002_X36_dialog_content = "But to me, you're always mean and always hurt those around you...",
  ui_story_5051_50511002_X37_dialog_content = "...",
  ui_story_5051_50511002_29_dialog_content = "I admit I shouldn't dig into your family affairs.",
  ui_story_5051_50511002_30_dialog_content = "But I think Mia needs an answer more than I do!",
  ui_story_5051_50511002_31_dialog_content = "...",
  ui_story_5051_50511002_32_dialog_content = "It's all my fault, I'm a burden to everyone...",
  ui_story_5051_50511002_33_dialog_content = "Listen to me, Mia, that's not true at all!",
  ui_story_5051_50511002_34_dialog_content = "You don't have to console me. I'm a jinx that endangers everyone.",
  ui_story_5051_50511002_35_dialog_content = "If I didn't break those boxes, the Eclipsites wouldn't have gotten out...",
  ui_story_5051_50511002_36_dialog_content = "No, conspirators hid them in there, it had nothing to do with you!",
  ui_story_5051_50511002_37_dialog_content = "Just the opposite, you've been helping out, Mia!",
  ui_story_5051_50511002_38_dialog_content = "I've been helping out?",
  ui_story_5051_50511002_39_dialog_content = "It was you who saved me from the Eclipsites outside the town.",
  ui_story_5051_50511002_40_dialog_content = "It was also you who fended off the Eclipsites trying to infiltrate the city at the gate.",
  ui_story_5051_50511002_41_dialog_content = "And just now, you saved a lot of innocent folks from those monsters.",
  ui_story_5051_50511002_42_dialog_content = "Doesn't all that prove how capable you are, Mia?",
  ui_story_5051_50511002_43_dialog_content = "They're just coincidences... I was just lucky.",
  ui_story_5051_50511002_44_dialog_content = "Mia... What can I say for you to believe me?",
  ui_story_5051_50511002_45_dialog_content = "You're much wiser than me, City Lord.",
  ui_story_5051_50511002_46_dialog_content = "So you must have more to say to Mia, right?",
  ui_story_5051_50511002_47_dialog_content = "...",
  ui_story_5051_50511002_X38_dialog_content = "T-That's what I truly think.",
  ui_story_5051_50511002_X39_dialog_content = "If that makes you angry, come at me, not my friend...!",
  ui_story_5051_50511002_48_dialog_content = "Hmm...",
  ui_story_5051_50511002_49_dialog_content = "Are you scared?",
  ui_story_5051_50511002_50_dialog_content = "I... I won't say I'm scared.",
  ui_story_5051_50511002_51_dialog_content = "As your eldest child, I must do my best as not to disappoint you.",
  ui_story_5051_50511002_52_dialog_content = "Whether it's the music and art I love, or the political and fighting expertise that I sorely lack...",
  ui_story_5051_50511002_53_dialog_content = "I must excel in everything.",
  ui_story_5051_50511002_54_dialog_content = "You've excelled enough, my child.",
  ui_story_5051_50511002_55_dialog_content = "But I still couldn't take any load off your shoulders.",
  ui_story_5051_50511002_56_dialog_content = "I remember now, I remember everything now.",
  ui_story_5051_50511002_57_dialog_content = "I once mustered the courage to join the knights, but was quickly injured by Eclipsites.",
  ui_story_5051_50511002_58_dialog_content = "It was Mother who saved me then, right?",
  ui_story_5051_50511002_59_dialog_content = "I didn't accomplish anything other than making more trouble.",
  ui_story_5051_50511002_60_dialog_content = "And isn't that what I just did?",
  ui_story_5051_50511002_61_dialog_content = "Otherwise you wouldn't be angry at me and want me to leave.",
  ui_story_5051_50511002_X61_dialog_content = "You're angry because I've been completely useless, is that so...?",
  ui_story_5051_50511002_62_dialog_content = "That was not my intent, Mia.",
  ui_story_5051_50511002_63_dialog_content = "Are you going to send me <color=#FFB400>somewhere far away</color> again?",
  ui_story_5051_50511002_64_dialog_content = "!!!",
  ui_story_5051_50511002_65_dialog_content = "Sending you anonymously to Umbraton for treatment was a choice I had to make.",
  ui_story_5051_50511002_66_dialog_content = "But I admit, I was too young then.",
  ui_story_5051_50511002_67_dialog_content = "If I could redo it, I would absolutely find a better way to handle everything.",
  ui_story_5051_50511002_68_dialog_content = "It is futile to say that now, but no matter what... that was one of the worst decisions I ever made.",
  ui_story_5051_50511002_69_dialog_content = "I am sorry for the hardships you had to endure for all these years...",
  ui_story_5051_50511002_70_dialog_content = "Father...",
  ui_story_5051_50511002_71_dialog_content = "I missed Mother and Carleen so much... And you too.",
  ui_story_5051_50511002_72_dialog_content = "I know, my child.",
  ui_story_5051_50511002_73_dialog_content = "While you are in Umbraton, Istvan briefed me about you constantly.",
  ui_story_5051_50511002_74_dialog_content = "I knew you were improving, and perhaps I will explain everything to you one day.",
  ui_story_5051_50511002_75_dialog_content = "I just never figured it would come to this...",
  ui_story_5051_50511002_76_dialog_content = "I promise I will spill the truth after we are out. But now our priority is to leave here.",
  ui_story_5051_50511002_77_dialog_content = "I... Uh...",
  ui_story_5051_50511002_79_dialog_content = "B-But if we leave, doesn't that mean I'll never see Mother again?",
  ui_story_5051_50511002_80_dialog_content = "...",
  ui_story_5051_50511002_81_dialog_content = "Was it because of me?",
  ui_story_5051_50511002_82_dialog_content = "Did she pass away because of me?",
  ui_story_5051_50511002_83_dialog_content = "We will talk about that later, child.",
  ui_story_5051_50511002_84_dialog_content = "We must leave here first.",
  ui_story_5051_50511002_85_dialog_content = "Leave... here?",
  ui_story_5051_50511002_86_dialog_content = "I do not wish to see anything else wrong happen to you, okay?",
  ui_story_5051_50511002_87_dialog_content = "OK...",
  ui_story_5051_50511002_88_dialog_content = "Can you stand up?",
  ui_story_5051_50511002_89_dialog_content = "Give me your hand and let us go together.",
  ui_story_5051_50511002_90_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5051_50511002_91_dialog_content = "What?",
  ui_story_5051_50511002_92_dialog_content = "What is going on here?",
  ui_story_5051_50511002_93_dialog_content = "Father!",
  ui_story_5051_50511002_94_dialog_content = "Stay away from him, Veronica.",
  ui_story_5051_50511002_95_dialog_content = "Do not get close to this bandit who is abducting you!",
  ui_story_5051_50511002_96_dialog_content = "...",
  ui_story_5051_50511002_97_dialog_content = "(The young Schwartz didn't recognize he is facing himself!)",
  ui_story_5051_50511002_98_dialog_content = "(Understandable, though...)",
  ui_story_5051_50511002_99_dialog_content = "(If I didn't know the truth, I wouldn't believe these two are the same person.)",
  ui_story_5051_50511002_100_dialog_content = "If you have the gall to abduct a daughter of Schwartz...",
  ui_story_5051_50511002_101_dialog_content = "Why do you not have the courage to fight me now!",
  ui_story_5051_50511002_102_dialog_content = "I do not want to cause any needless confrontation.",
  ui_story_5051_50511002_103_dialog_content = "Needless confrontation?",
  ui_story_5051_50511002_104_dialog_content = "I do not believe I have met you.",
  ui_story_5051_50511002_105_dialog_content = "Are you a Troy? No, you do not look like one.",
  ui_story_5051_50511002_106_dialog_content = "You must be a Kartima, then?",
  ui_story_5051_50511002_107_dialog_content = "Neither. I am Veronica's...",
  ui_story_5051_50511002_108_dialog_content = "Friend.",
  ui_story_5051_50511002_109_dialog_content = "Friend?",
  ui_story_5051_50511002_110_dialog_content = "Friend of a friend, but nevertheless a friend.",
  ui_story_5051_50511002_111_dialog_content = "Interesting, though I have only heard of \"The enemy of my enemy is my friend.\"",
  ui_story_5051_50511002_112_dialog_content = "Well, now you know.",
  ui_story_5051_50511002_113_dialog_content = "Your tone suggests that you are unwilling to be my friend.",
  ui_story_5051_50511002_114_dialog_content = "He indeed is... a friend of mine from Umbraton, Father.",
  ui_story_5051_50511002_115_dialog_content = "He also helped me just a moment ago.",
  ui_story_5051_50511002_116_dialog_content = "Peculiar timing for him to appear alongside the Eclipsites.",
  ui_story_5051_50511002_117_dialog_content = "Perhaps too much of a coincidence.",
  ui_story_5051_50511002_118_dialog_content = "Let your mother screen who you are friends with from now on, Veronica.",
  ui_story_5051_50511002_119_dialog_content = "...",
  ui_story_5051_50511002_120_dialog_content = "(Ahem, Schwartz must be livid at his younger self by now.)",
  ui_story_5051_50511002_121_dialog_content = "(But this simply can't go on...)",
  ui_story_5051_50511002_122_dialog_content = "(And we can't just tell the young Schwartz, \"This is you a dozen years in the future.\")",
  ui_story_5051_50511002_123_dialog_content = "(Only one card I can play now...)",
  ui_story_5051_50511002_124_dialog_content = "Actually...",
  ui_story_5051_50511002_125_dialog_content = "What?",
  ui_story_5051_50511002_126_dialog_content = "Please forgive me, City Lord.",
  ui_story_5051_50511002_127_dialog_content = "He's actually... my father, em, Soroz.",
  ui_story_5051_50511002_128_dialog_content = "I didn't inform him I was coming to Lumopolis with Princess Veronica.",
  ui_story_5051_50511002_129_dialog_content = "That's why he asked others to come find me here.",
  ui_story_5051_50511002_130_dialog_content = "I didn't expect to run into Eclipsites as soon as we met.",
  ui_story_5051_50511002_131_dialog_content = "Y-Yeah!",
  ui_story_5051_50511002_132_dialog_content = "Yes. See, a needless confrontation like I said.",
  ui_story_5051_50511002_133_dialog_content = "Although I must thank you and your family for looking after PlayerName.",
  ui_story_5051_50511002_134_dialog_content = "If that is the case, I indeed misunderstood.",
  ui_story_5051_50511002_135_dialog_content = "However...",
  ui_story_5051_50511002_136_dialog_content = "Do you still not believe me?",
  ui_story_5051_50511002_137_dialog_content = "PlayerName appears only slightly older than Veronica.",
  ui_story_5051_50511002_138_dialog_content = "I would have guessed you are PlayerName's grandfather.",
  ui_story_5051_50511002_139_dialog_content = "Ha ha ha, young man.",
  ui_story_5051_50511002_140_dialog_content = "Thank you for alerting me to how unlikeable I was in my younger days.",
  ui_story_5051_50511002_141_dialog_content = "I can imagine that.",
  ui_story_5051_50511002_142_dialog_content = "Fortunately, it no longer bothers me at my age.",
  ui_story_5051_50511002_143_dialog_content = "If I am correct, you must have more important business to tend to?",
  ui_story_5051_50511002_144_dialog_content = "What point are you trying to make?",
  ui_story_5051_50511002_145_dialog_content = "I may be old, but I know a thing or two about dealing with Eclipsites.",
  ui_story_5051_50511002_146_dialog_content = "I am willing to take Veronica and PlayerName to safety.",
  ui_story_5051_50511002_147_dialog_content = "I appreciate the thought.",
  ui_story_5051_50511002_148_dialog_content = "However, Veronica is my daughter.",
  ui_story_5051_50511002_149_dialog_content = "I am fully capable of protecting her myself.",
  ui_story_5051_50511002_150_dialog_content = "No one else needs to intervene.",
  ui_story_5051_50511002_151_dialog_content = "...",
  ui_story_5051_50511002_152_dialog_content = "<color=#FFB400>Father</color>...",
  ui_story_5051_50511002_153_dialog_content = "(Mia...)",
  ui_story_5051_50511002_154_dialog_content = "(Which <color=#FFB400>father</color> is she responding to now?)",
  ui_story_5051_50511101_1_dialog_content = "The crystal ball is really glowing...",
  ui_story_5051_50511101_2_dialog_content = "PlayerName and others must be nearby!",
  ui_story_5051_50511101_3_dialog_content = "It's so quiet.",
  ui_story_5051_50511101_4_dialog_content = "Yeah, this is nowhere as lively as it was on our way here.",
  ui_story_5051_50511101_5_dialog_content = "I think we should just go hang out where it's more crowded.",
  ui_story_5051_50511101_6_dialog_content = "It's just too dead around here.",
  ui_story_5051_50511101_7_dialog_content = "I can tell there's no one selling good booze.",
  ui_story_5051_50511101_8_dialog_content = "Ahem, we're not here to shop.",
  ui_story_5051_50511101_9_dialog_content = "You think you've learned enough to fool me now?",
  ui_story_5051_50511101_10_dialog_content = "Didn't those people in black formals just try to get our business?",
  ui_story_5051_50511101_11_dialog_content = "People in black formals? Are you talking about the Eclipsites?",
  ui_story_5051_50511101_12_dialog_content = "Are you so sloshed that you couldn't even tell they were Eclipsites?",
  ui_story_5051_50511101_13_dialog_content = "<size=30>No wonder you couldn't even tell it was me...</size>",
  ui_story_5051_50511101_14_dialog_content = "I checked the area and all the Eclipsites should be dead now.",
  ui_story_5051_50511101_15_dialog_content = "There should be ample security where the City Lord and Princess are.",
  ui_story_5051_50511101_16_dialog_content = "So your friends should be safe with them.",
  ui_story_5051_50511101_17_dialog_content = "Thank you so much.",
  ui_story_5051_50511101_18_dialog_content = "If you didn't kill those Eclipsites in a jiffy, I wouldn't know how I could make it this far.",
  ui_story_5051_50511101_19_dialog_content = "You're the most dependable knight I've ever met in Lumopolis!",
  ui_story_5051_50511101_20_dialog_content = "I can even tell without the crystal ball...",
  ui_story_5051_50511101_21_dialog_content = "You'll become a prominent figure eventually!",
  ui_story_5051_50511101_22_dialog_content = "Thanks for the comment.",
  ui_story_5051_50511101_23_dialog_content = "I'm just a trainee right now.",
  ui_story_5051_50511101_24_dialog_content = "You believing me is the greatest encouragement to me.",
  ui_story_5051_50511101_25_dialog_content = "It's all right, you're still young! You'll get a chance to...",
  ui_story_5051_50511101_26_dialog_content = "Hey, wait!",
  ui_story_5051_50511101_27_dialog_content = "(What happens here is what the Crystal recorded twelve years ago.)",
  ui_story_5051_50511101_28_dialog_content = "(So that means this knight is actually much older than me now!)",
  ui_story_5051_50511101_29_dialog_content = "Ahem. So, how old are you now?",
  ui_story_5051_50511101_30_dialog_content = "You were rather pushy when you wanted me to be your master.",
  ui_story_5051_50511101_31_dialog_content = "Why are you so awkward and wishy-washy now?",
  ui_story_5051_50511101_32_dialog_content = "Just say it if you're interested!",
  ui_story_5051_50511101_33_dialog_content = "What? N-No, that's not what I mean!",
  ui_story_5051_50511101_34_dialog_content = "Huh?",
  ui_story_5051_50511101_35_dialog_content = "Of course, that doesn't mean I don't like you!",
  ui_story_5051_50511101_36_dialog_content = "It's just... never mind, I don't know where to start too.",
  ui_story_5051_50511101_37_dialog_content = "But if you're still a knight in Lumopolis twelve years from now...",
  ui_story_5051_50511101_38_dialog_content = "We'll meet again for sure!",
  ui_story_5051_50511101_39_dialog_content = "You mean that \"I'll come back so-many-years later so wait for me\" cliche?",
  ui_story_5051_50511101_40_dialog_content = "I did that when I was eight. How about something fresher?",
  ui_story_5051_50511101_41_dialog_content = "Uh, haha...",
  ui_story_5051_50511101_42_dialog_content = "This drunk lady doesn't know what she's saying, so pay no attention to her!",
  ui_story_5051_50511101_43_dialog_content = "I'll hold you to it!",
  ui_story_5051_50511101_44_dialog_content = "Huh?",
  ui_story_5051_50511101_45_dialog_content = "My kins didn't see much in me because of different concerns.",
  ui_story_5051_50511101_46_dialog_content = "But I wouldn't be here today without them taking turns raising me.",
  ui_story_5051_50511101_47_dialog_content = "I hope I can prove my worth to them one day and rebuild the glory of House Kartima.",
  ui_story_5051_50511101_48_dialog_content = "Twelve years from now, you said...",
  ui_story_5051_50511101_49_dialog_content = "You'll see me as the mightiest knight leading an army when you return!",
  ui_story_5051_50511101_50_dialog_content = "Wow, that sounds very impressive!",
  ui_story_5051_50511101_51_dialog_content = "It's a promise then. I'll look for you in the Lumo Knights!",
  ui_story_5051_50511101_52_dialog_content = "But I don't know your name yet...",
  ui_story_5051_50511101_53_dialog_content = "Sharona Kartima.",
  ui_story_5051_50511101_54_dialog_content = "Sharona? What an adorable name.",
  ui_story_5051_50511101_55_dialog_content = "Hold it...",
  ui_story_5051_50511101_56_dialog_content = "So you're actually a girl?!",
  ui_story_5051_50511101_57_dialog_content = "<color=#e8d9bb>Other End of the Street</color>",
  ui_story_5051_50511101_58_dialog_content = "Do not be rash, young one.",
  ui_story_5051_50511101_59_dialog_content = "I understand your situation as well as your feelings.",
  ui_story_5051_50511101_60_dialog_content = "It took me a long time to finally figure out \"finesse over power.\"",
  ui_story_5051_50511101_61_dialog_content = "I hope you can consider keeping your family out of other affairs.",
  ui_story_5051_50511101_62_dialog_content = "If I get a chance, I must introduce you to the Elder Council.",
  ui_story_5051_50511101_63_dialog_content = "You would have a lot in common to discuss, and all of you love to mentor the young ones.",
  ui_story_5051_50511101_64_dialog_content = "What do you think?",
  ui_story_5051_50511101_65_dialog_content = "I see I have forgotten...",
  ui_story_5051_50511101_66_dialog_content = "That I found self-righteous preaching to be most annoying when I was young.",
  ui_story_5051_50511101_67_dialog_content = "<size=45>Whoa!</size>",
  ui_story_5051_50511101_68_dialog_content = "What?",
  ui_story_5051_50511101_69_dialog_content = "Finally found you all! Is everyone all right?",
  ui_story_5051_50511101_70_dialog_content = "Everything's attached, and looking lively... Guess nothing's wrong. Wonderful!",
  ui_story_5051_50511101_71_dialog_content = "Jakine...",
  ui_story_5051_50511101_72_dialog_content = "Don't worry about me, PlayerName. See, I'm still fine and in one piece!",
  ui_story_5051_50511101_73_dialog_content = "So then, let's not hang around here.",
  ui_story_5051_50511101_74_dialog_content = "Ahem, due to certain special reasons...",
  ui_story_5051_50511101_75_dialog_content = "We must leave here TODAY!",
  ui_story_5051_50511101_76_dialog_content = "Shhh...",
  ui_story_5051_50511101_77_dialog_content = "Problems, PlayerName?",
  ui_story_5051_50511101_78_dialog_content = "Oh, you wanna know who's the drunk lady with me, right?",
  ui_story_5051_50511101_79_dialog_content = "It's rather complicated, but I can certainly introduce the knight who helped us!",
  ui_story_5051_50511101_80_dialog_content = "Hey, where's she?",
  ui_story_5051_50511101_81_dialog_content = "Did she just leave after seeing I've found my friends?",
  ui_story_5051_50511101_82_dialog_content = "Come on, can't anyone in Lumopolis say goodbye like normal people?",
  ui_story_5051_50511101_83_dialog_content = "Hey, is he who you're looking for, girl?",
  ui_story_5051_50511101_84_dialog_content = "How come he looks familiar to me?",
  ui_story_5051_50511101_85_dialog_content = "Boaz? Did you not depart for Northland last night as scheduled?",
  ui_story_5051_50511101_86_dialog_content = "I don't come to Lumopolis often *hiccup*, so I thought I'd relax a little.",
  ui_story_5051_50511101_87_dialog_content = "Oh, I remember now. From yesterday...",
  ui_story_5051_50511101_88_dialog_content = "You're that City Lord guy!",
  ui_story_5051_50511101_89_dialog_content = "(What? This is the City Lord?)",
  ui_story_5051_50511101_90_dialog_content = "(No wonder PlayerName was winking at me...)",
  ui_story_5051_50511101_91_dialog_content = "<size=30>PlayerName, come here!</size>",
  ui_story_5051_50511101_92_dialog_content = "Whoa, take it easy...",
  ui_story_5051_50511101_93_dialog_content = "Say, what's going on with all this?",
  ui_story_5051_50511101_94_dialog_content = "That's what I've been trying to sort out, but it just got more complicated now that you've shown up too...",
  ui_story_5051_50511101_95_dialog_content = "How can anything be complicated? It's probably all in your head.",
  ui_story_5051_50511101_96_dialog_content = "Anyway, the City Lord just noticed the City Lord and mistook him for a kidnapper...",
  ui_story_5051_50511101_97_dialog_content = "Why do I feel even more lost from that?",
  ui_story_5051_50511101_98_dialog_content = "That's why I said it's very complicated...",
  ui_story_5051_50511101_99_dialog_content = "The problem is how are we gonna tell one City Lord from the other?",
  ui_story_5051_50511101_100_dialog_content = "I just told them that the City Lord who came here with us is my father, Soroz...",
  ui_story_5051_50511101_101_dialog_content = "Soroz? Isn't that the name of your Colossus, PlayerName?",
  ui_story_5051_50511101_102_dialog_content = "I was pressing for a name at the time...",
  ui_story_5051_50511101_103_dialog_content = "One is old Schwartz, the other is young Schwartz. Wouldn't that be easier?",
  ui_story_5051_50511101_104_dialog_content = "Well, that's probably impolite to the City Lord, but for the sake of convenience...",
  ui_story_5051_50511101_105_dialog_content = "So, the old Schwartz tried to take Mia away, only for the young Schwartz to mistake him for a kidnapper.",
  ui_story_5051_50511101_106_dialog_content = "Now we're trying to get out of the bind!",
  ui_story_5051_50511101_107_dialog_content = "Ah, I get it now since you put it that way!",
  ui_story_5051_50511101_108_dialog_content = "I got this!",
  ui_story_5051_50511101_109_dialog_content = "I'm okay, I ain't... wasted at all!",
  ui_story_5051_50511101_110_dialog_content = "All right, mind telling me who the young lady is then?",
  ui_story_5051_50511101_111_dialog_content = "I can do that myself just fine! Me, Boaz's pupil!",
  ui_story_5051_50511101_112_dialog_content = "I did not know Her Majesty sent two envoys this time.",
  ui_story_5051_50511101_113_dialog_content = "Of course the City Lord wouldn't know, since there's only one envoy.",
  ui_story_5051_50511101_114_dialog_content = "I'm just a follower! Though followers got jobs to do too!",
  ui_story_5051_50511101_115_dialog_content = "My job is different from Boaz's, so I didn't get to meet you and your lady.",
  ui_story_5051_50511101_116_dialog_content = "Oh? What's your mission?",
  ui_story_5051_50511101_117_dialog_content = "Invite PlayerName to Northland for Her Majesty's party.",
  ui_story_5051_50511101_118_dialog_content = "What?!",
  ui_story_5051_50511101_119_dialog_content = "It seems PlayerName is not aware of this.",
  ui_story_5051_50511101_120_dialog_content = "Of course not. I did just track the fellow down!",
  ui_story_5051_50511101_121_dialog_content = "So, PlayerName, would you like to go?",
  ui_story_5051_50511101_122_dialog_content = "<size=30>*cough* Say yes! *cough*</size>",
  ui_story_5051_50511101_123_dialog_content = "Huh? Oh...",
  ui_story_5051_50511101_124_dialog_content = "I certainly am not going to turn down an invitation from the Queen!",
  ui_story_5051_50511101_125_dialog_content = "Is that right? That's great!",
  ui_story_5051_50511101_126_dialog_content = "My master did her job, and I did mine.",
  ui_story_5051_50511101_127_dialog_content = "We can all go back to Northland with joy now!",
  ui_story_5051_50511101_128_dialog_content = "(Jakine is a genius!)",
  ui_story_5051_50511101_129_dialog_content = "(Young Schwartz has to let us go now.)",
  ui_story_5051_50511101_130_dialog_content = "...",
  ui_story_5051_50511101_131_dialog_content = "(But why is the old Schwartz still uptight?)",
  ui_story_5051_50511101_132_dialog_content = "(Did Jakine and I grossly underestimate the situation?)",
  ui_story_5051_50511101_133_dialog_content = "I see.",
  ui_story_5051_50511101_134_dialog_content = "(Was I seeing things or did the young Schwartz just chuckle?)",
  ui_story_5051_50511101_135_dialog_content = "I have the utmost respect for the Queen of the North. Any guest of hers is a guest of mine.",
  ui_story_5051_50511101_136_dialog_content = "I'm very sorry for you to see Lumopolis in such chaos.",
  ui_story_5051_50511101_137_dialog_content = "But I promise it will not last long.",
  ui_story_5051_50511101_138_dialog_content = "Until then, I request that you follow me.",
  ui_story_5051_50511101_139_dialog_content = "I shall ensure the safety of your entire party!",
  ui_story_5051_50511101_140_dialog_content = "<size=30>His attitude is totally different...</size>",
  ui_story_5051_50511101_141_dialog_content = "<size=30>Would you not exploit any free pawns gift-wrapped to you, PlayerName?</size>",
  ui_story_5051_50511101_142_dialog_content = "<size=30>Pawns?</size>",
  ui_story_5051_50511101_143_dialog_content = "(What does that mean? Are we all pawns for young Schwartz now?)",
  ui_story_5051_50511101_144_dialog_content = "(But what benefits can the few of us bring to him?)",
  ui_story_5051_50511101_145_dialog_content = "(Also, old Schwartz is saying that...)",
  ui_story_5051_50511101_146_dialog_content = "(Because he had treated others like chess pieces in this way?)",
  ui_story_5051_50511101_147_dialog_content = "<size=30>PlayerName, you should know that chess is more than just a game right now.</size>",
  ui_story_5051_50511101_148_dialog_content = "Father!",
  ui_story_5051_50511101_149_dialog_content = "That voice...",
  ui_story_5051_50511101_150_dialog_content = "Father!",
  ui_story_5051_50511101_151_dialog_content = "Car...",
  ui_story_5051_50511101_152_dialog_content = "Carleen! What are you doing here?",
  ui_story_5051_50511101_153_dialog_content = "I brought her here.",
  ui_story_5051_50511101_154_dialog_content = "...",
  ui_story_5051_50511101_155_dialog_content = "Why are you back? Has the second wave of Eclipsites been eliminated?",
  ui_story_5051_50511101_156_dialog_content = "Second wave of Eclipsites?",
  ui_story_5051_50511101_157_dialog_content = "Uh, I am merely concerned that perhaps more Eclipsites will emerge elsewhere.",
  ui_story_5051_50511101_158_dialog_content = "I can't substantiate the suspicion, but we can't be careless either.",
  ui_story_5051_50511101_159_dialog_content = "Where is Ms. Rot? She was supposed to leave with you. Why did she neglect her post?",
  ui_story_5051_50511101_160_dialog_content = "Ms. Rot didn't neglect her post. Compared to me, the civilians needed her assistance more.",
  ui_story_5051_50511101_161_dialog_content = "You're making it difficult for me, Joshua.",
  ui_story_5051_50511101_162_dialog_content = "And you know this is not the first time, Daniel.",
  ui_story_5051_50511101_163_dialog_content = "When will you remember that my sword-fighting skills rival yours?",
  ui_story_5051_50511101_164_dialog_content = "You seem to have many friends in need of help here...",
  ui_story_5051_50511101_165_dialog_content = "Let me share some of that burden, Daniel.",
  ui_story_5051_50511101_166_dialog_content = "Joshua!",
  ui_story_5051_50511101_167_dialog_content = "Cough, cough!",
  ui_story_5051_50511101_168_dialog_content = "Are you okay, sir?",
  ui_story_5051_50511101_169_dialog_content = "You look somewhat familiar to me...",
  ui_story_5051_50511101_170_dialog_content = "That was what you said when we met for the first time.",
  ui_story_5051_50511101_171_dialog_content = "Have we met before...?",
  ui_story_5051_50511101_172_dialog_content = "(Now who was it that warned me not to get involved in this world?)",
  ui_story_5051_50511101_173_dialog_content = "Ahem. I see my father knew Lady Joshua?",
  ui_story_5051_50511101_174_dialog_content = "My apologies, I believe I had the wrong person.",
  ui_story_5051_50511101_175_dialog_content = "Oh, it's PlayerName's father, no wonder you looked familiar!",
  ui_story_5051_50511101_176_dialog_content = "Ouch!",
  ui_story_5051_50511101_177_dialog_content = "Eclipsites! More Eclipsites!",
  ui_story_5051_50511101_178_dialog_content = "The City Lord guessed it right on the dot. Here comes the second wave!",
  ui_story_5051_50511101_179_dialog_content = "Can he predict the future too? Maybe even better than me?!",
  ui_story_5051_50511101_180_dialog_content = "...",
  ui_story_5051_50511101_181_dialog_content = "Daniel!",
  ui_story_5051_50511101_182_dialog_content = "Watch out for Eclipsites, everyone!",
  ui_story_5051_50511101_183_dialog_content = "<color=#e8d9bb>Thump, thump!</color>",
  ui_story_5051_50511101_184_dialog_content = "I hear neat, orderly footsteps...",
  ui_story_5051_50511101_185_dialog_content = "It's probably not the Eclipsites!",
  ui_story_5051_50511101_186_dialog_content = "That's great!",
  ui_story_5051_50511101_187_dialog_content = "The reinforcement is here!",
  ui_story_5051_50511101_188_dialog_content = "Hold it.",
  ui_story_5051_50511101_189_dialog_content = "These soldiers are not here to aid us.",
  ui_story_5051_50511101_190_dialog_content = "Huh?",
  ui_story_5051_50511101_191_dialog_content = "Charge!",
  ui_story_5051_50511101_192_dialog_content = "Whoa—!",
  ui_story_5051_50511101_193_dialog_content = "Why are they pointing their weapons at us?",
  ui_story_5051_50511102_1_dialog_content = "Behind you on the left, Jakine!",
  ui_story_5051_50511102_2_dialog_content = "Hey, stay away!",
  ui_story_5051_50511102_3_dialog_content = "Ugh...",
  ui_story_5051_50511102_4_dialog_content = "Huh? Did you save me, PlayerName?",
  ui_story_5051_50511102_5_dialog_content = "N-No...",
  ui_story_5051_50511102_6_dialog_content = "Watch where you're stumbling, you walking rocks.",
  ui_story_5051_50511102_7_dialog_content = "Who's gonna get me booze if my pupil's hurt?",
  ui_story_5051_50511102_8_dialog_content = "Yes, the awesomely intrepid Boaz whom I remember has returned!",
  ui_story_5051_50511102_9_dialog_content = "I'm dizzy, must've put too much into that...",
  ui_story_5051_50511102_10_dialog_content = "You take over, girl, I'm done...",
  ui_story_5051_50511102_11_dialog_content = "No—! We still haven't had the chance to catch up!",
  ui_story_5051_50511102_12_dialog_content = "Really? Falling asleep in a time like this. I take back what I said before!",
  ui_story_5051_50511102_13_dialog_content = "PlayerName, take Jakine and Mia and slip out of the right gap. I will cover you!",
  ui_story_5051_50511102_14_dialog_content = "Are we leaving others behind?",
  ui_story_5051_50511102_15_dialog_content = "We are out of time. The <color=#FFB400>insurrection</color> is happening. Every second here only increases the danger!",
  ui_story_5051_50511102_16_dialog_content = "Insurrection?",
  ui_story_5051_50511102_17_dialog_content = "How come I don't remember any of this? Did I know about this back then?",
  ui_story_5051_50511102_18_dialog_content = "Don't strain yourself, Mia!",
  ui_story_5051_50511102_19_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5051_50511102_20_dialog_content = "Who was that?",
  ui_story_5051_50511102_21_dialog_content = "Looked to be flying down from the sky and going after a specific target?",
  ui_story_5051_50511102_22_dialog_content = "Can the target be <color=#FFB400>young Schwartz</color>?",
  ui_story_5051_50511102_23_dialog_content = "Young Schwartz is paying too much attention to the enemy to notice the danger from above!",
  ui_story_5051_50511102_24_dialog_content = "No way, even our old City Lord would have seen it!",
  ui_story_5051_50511102_25_dialog_content = "...",
  ui_story_5051_50511102_26_dialog_content = "Look out, Daniel!",
  ui_story_5051_50511102_27_dialog_content = "Hiyah!",
  ui_story_5051_50511102_28_dialog_content = "Err...",
  ui_story_5051_50511102_29_dialog_content = "Oh, that looks painful!",
  ui_story_5051_50511102_30_dialog_content = "Was he stabbed in the shoulder?",
  ui_story_5051_50511102_31_dialog_content = "We have to hurry while everyone is distracted!",
  ui_story_5051_50511102_32_dialog_content = "But...",
  ui_story_5051_50511102_33_dialog_content = "Father!",
  ui_story_5051_50511102_34_dialog_content = "I'm going to help Father!",
  ui_story_5051_50511102_35_dialog_content = "Is that so?",
  ui_story_5051_50511102_36_dialog_content = "Carleen...",
  ui_story_5051_50511102_37_dialog_content = "Oh no, the rebels spotted young Carleen!",
  ui_story_5051_50511102_38_dialog_content = "... What?",
  ui_story_5051_50511102_39_dialog_content = "A-Are you a bad guy too?",
  ui_story_5051_50511102_40_dialog_content = "Hello, little princess!",
  ui_story_5051_50511102_41_dialog_content = "D-Don't think I'm afraid of you!",
  ui_story_5051_50511102_42_dialog_content = "I'm very skilled with swords! I beat a lot of soldiers!",
  ui_story_5051_50511102_43_dialog_content = "A pity I won't have mercy on you like those soldiers!",
  ui_story_5051_50511102_44_dialog_content = "Agh!",
  ui_story_5051_50511102_45_dialog_content = "Heh, I didn't even break a sweat and you're on the ground already!",
  ui_story_5051_50511102_46_dialog_content = "Don't bother getting up. You'll just fall back down anyway.",
  ui_story_5051_50511102_47_dialog_content = "Agh!",
  ui_story_5051_50511102_48_dialog_content = "The Sovereign's Blade!",
  ui_story_5051_50511102_49_dialog_content = "What the...",
  ui_story_5051_50511102_50_dialog_content = "(Old Schwartz urged us to run only to save Carleen himself.)",
  ui_story_5051_50511102_51_dialog_content = "I'm saved? Father, is that you...?",
  ui_story_5051_50511102_52_dialog_content = "...",
  ui_story_5051_50511102_53_dialog_content = "Carleen!!!",
  ui_story_5051_50511102_54_dialog_content = "Are you hurt?",
  ui_story_5051_50511102_55_dialog_content = "Don't worry, Mother, I'm not hurt.",
  ui_story_5051_50511102_56_dialog_content = "Why are you still talking tough, child...",
  ui_story_5051_50511102_57_dialog_content = "She probably just got scared, that is all.",
  ui_story_5051_50511102_58_dialog_content = "Thank you for saving Carleen, father of PlayerName!",
  ui_story_5051_50511102_59_dialog_content = "No need to thank me. It's something I should do.",
  ui_story_5051_50511102_60_dialog_content = "My poor little Carleen...",
  ui_story_5051_50511102_61_dialog_content = "Mother, how is *cough cough* Father?",
  ui_story_5051_50511102_62_dialog_content = "He, uh...",
  ui_story_5051_50511102_63_dialog_content = "Don't worry, he'll defeat the bad guys soon.",
  ui_story_5051_50511102_64_dialog_content = "Mother, you should go and help Father. I'm all right... totally fine!",
  ui_story_5051_50511102_65_dialog_content = "Oh, my fool girl.",
  ui_story_5051_50511102_66_dialog_content = "Hiyah!",
  ui_story_5051_50511102_67_dialog_content = "Cough...",
  ui_story_5051_50511102_68_dialog_content = "Daniel!",
  ui_story_5051_50511102_69_dialog_content = "Worry not, he's more than enough to take on the assassin alone.",
  ui_story_5051_50511102_70_dialog_content = "But he is wounded...",
  ui_story_5051_50511102_71_dialog_content = "Then stay here and allow me to help your husband.",
  ui_story_5051_50511102_72_dialog_content = "What? You shouldn't risk your life for that.",
  ui_story_5051_50511102_73_dialog_content = "As you can tell, the traitors are not targeting you but me and my family.",
  ui_story_5051_50511102_74_dialog_content = "There is no time for such distinctions under this circumstance.",
  ui_story_5051_50511102_75_dialog_content = "Wait here.",
  ui_story_5051_50511102_76_dialog_content = "PlayerName, wait here with Jakine and Mia as well.",
  ui_story_5051_50511102_77_dialog_content = "I will be right back.",
  ui_story_5051_50511102_78_dialog_content = "Wait!",
  ui_story_5051_50511102_79_dialog_content = "I-I would like to come with you.",
  ui_story_5051_50511102_80_dialog_content = "...",
  ui_story_5051_50511102_81_dialog_content = "You take the left flank and I take the right. Let us move out!",
  ui_story_5051_50511102_82_dialog_content = "... S-Sure!",
  ui_story_5051_50511102_83_dialog_content = "Am I hallucinating?",
  ui_story_5051_50511102_84_dialog_content = "Or is that Daniel I saw in PlayerName's father...?",
  ui_story_5051_50511102_85_dialog_content = "Err...",
  ui_story_5051_50511102_86_dialog_content = "I have been expecting you for a long time.",
  ui_story_5051_50511102_87_dialog_content = "What?",
  ui_story_5051_50511102_88_dialog_content = "Heh, this wound is not even nearly as bad as I imagined it would be.",
  ui_story_5051_50511102_89_dialog_content = "So you figured it out already.",
  ui_story_5051_50511102_90_dialog_content = "Stop talking and let us finish this.",
  ui_story_5051_50511102_91_dialog_content = "I-I'll help!",
  ui_story_5051_50511102_92_dialog_content = "Retreat!",
  ui_story_5051_50511102_93_dialog_content = "Everyone, retreat!",
  ui_story_5051_50511102_94_dialog_content = "Thank you all for giving me this opportunity...",
  ui_story_5051_50511102_95_dialog_content = "Aurora Aeterna beneath the Light!",
  ui_story_5051_50511102_96_dialog_content = "Urgh!",
  ui_story_5051_50511102_97_dialog_content = "As I mentioned...",
  ui_story_5051_50511102_98_dialog_content = "As the lord of the city, I am more than just a bureaucrat.",
  ui_story_5051_50511201_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5051_50511201_2_dialog_content = "Are you okay, Uncle?",
  ui_story_5051_50511201_3_dialog_content = "Sharona?!",
  ui_story_5051_50511201_4_dialog_content = "Did I not tell you to take half-day off? What are you doing here?",
  ui_story_5051_50511201_5_dialog_content = "We promised Princess Veronica's friend to find some people this morning, so I thought maybe I could help...",
  ui_story_5051_50511201_6_dialog_content = "It is my fault for not following your orders, Uncle.",
  ui_story_5051_50511201_7_dialog_content = "But when Eclipsites overran the city, it's my duty as a knight-in-training to protect the people!",
  ui_story_5051_50511201_8_dialog_content = "Also, I was concerned for the Kartimas patrolling the city... as well as you.",
  ui_story_5051_50511201_9_dialog_content = "Fine.",
  ui_story_5051_50511201_10_dialog_content = "You'll go home now and leave Lumopolis with your aunt and cousins!",
  ui_story_5051_50511201_11_dialog_content = "Take the airship parked in the rear garden.",
  ui_story_5051_50511201_12_dialog_content = "Why, Uncle?",
  ui_story_5051_50511201_13_dialog_content = "Don't ask why, just do it!",
  ui_story_5051_50511201_14_dialog_content = "Look at the Eclipsites on the street, Uncle. They seem hesitant to attack you or me.",
  ui_story_5051_50511201_15_dialog_content = "The Kartima blood running through us just might be their bane.",
  ui_story_5051_50511201_16_dialog_content = "If we can get the whole clan to repel the Eclipsites from Lumopolis this time...",
  ui_story_5051_50511201_17_dialog_content = "We'll definitely gain the City Lord's favor and reclaim family glory!",
  ui_story_5051_50511201_18_dialog_content = "So why are you instructing me to flee with the family at this moment?",
  ui_story_5051_50511201_19_dialog_content = "You just reminded me, you might run across other Eclipsites after leaving Lumopolis...",
  ui_story_5051_50511201_20_dialog_content = "In my study is a Kartima heirloom katana called Azure Flame.",
  ui_story_5051_50511201_21_dialog_content = "Remember to bring it with you!",
  ui_story_5051_50511201_22_dialog_content = "I don't understand, Uncle...",
  ui_story_5051_50511201_23_dialog_content = "Perhaps that prophecy is true, but I never believed it.",
  ui_story_5051_50511201_24_dialog_content = "The person who will save the Kartimas is you...",
  ui_story_5051_50511201_25_dialog_content = "Not me.",
  ui_story_5051_50511201_26_dialog_content = "...",
  ui_story_5051_50511201_27_dialog_content = "All this happened exactly like the time before?",
  ui_story_5051_50511201_28_dialog_content = "Practically identical.",
  ui_story_5051_50511201_29_dialog_content = "Except Carleen's injury was worse and I wasn't there to protect her.",
  ui_story_5051_50511201_30_dialog_content = "That's why you couldn't help but go when you heard her voice.",
  ui_story_5051_50511201_31_dialog_content = "Were you trying to make up for that?",
  ui_story_5051_50511201_32_dialog_content = "I would be lying if I said I wasn't.",
  ui_story_5051_50511201_33_dialog_content = "How is Carleen?",
  ui_story_5051_50511201_34_dialog_content = "Generally fine, only a few scratches on her hands and feet.",
  ui_story_5051_50511201_35_dialog_content = "But you, however, are bleeding from the shoulder!",
  ui_story_5051_50511201_36_dialog_content = "It is no more serious than a mosquito bite.",
  ui_story_5051_50511201_37_dialog_content = "We haven't practiced sword fighting together for a long time now.",
  ui_story_5051_50511201_38_dialog_content = "This level of ambush wouldn't have touched you before...",
  ui_story_5051_50511201_39_dialog_content = "It was abrupt, and I probably was thrown a little off-balance too.",
  ui_story_5051_50511201_40_dialog_content = "First an Eclipsites invasion, then sending assassins on the very day of Schwartz Family Day...",
  ui_story_5051_50511201_41_dialog_content = "Who would hold such a grudge against us?",
  ui_story_5051_50511201_42_dialog_content = "Lord Schwartz, Lady Joshua.",
  ui_story_5051_50511201_43_dialog_content = "Please pardon me and my squad for our late arrival.",
  ui_story_5051_50511201_44_dialog_content = "It is our negligence that caused the princess and the lord to get hurt.",
  ui_story_5051_50511201_45_dialog_content = "The fault is not on you, Ms. Rot.",
  ui_story_5051_50511201_46_dialog_content = "For ensuring civilians' safety is your priority.",
  ui_story_5051_50511201_47_dialog_content = "Thank you, My Lady.",
  ui_story_5051_50511201_48_dialog_content = "Anything else to report?",
  ui_story_5051_50511201_49_dialog_content = "Yes, my lord.",
  ui_story_5051_50511201_50_dialog_content = "We combed the vicinity and captured several rebels alive.",
  ui_story_5051_50511201_51_dialog_content = "Tell me what you have discovered.",
  ui_story_5051_50511201_52_dialog_content = "We found weapons with unique images on their persons.",
  ui_story_5051_50511201_53_dialog_content = "After comparisons, we verified the images to be House Kartima markings.",
  ui_story_5051_50511201_54_dialog_content = "House Kartima?",
  ui_story_5051_50511201_55_dialog_content = "I was having a nice chat with Mime's wife at a party not too long ago.",
  ui_story_5051_50511201_56_dialog_content = "Her two children were roughly the same age as Carleen.",
  ui_story_5051_50511201_57_dialog_content = "No, something is wrong here.",
  ui_story_5051_50511201_58_dialog_content = "Why would they be carrying weapons that could easily incriminate themselves?",
  ui_story_5051_50511201_59_dialog_content = "Arrogant people are often very naive as well.",
  ui_story_5051_50511201_60_dialog_content = "They were sure they could end me today and terminate Schwartz's reign.",
  ui_story_5051_50511201_61_dialog_content = "Ms. Rot.",
  ui_story_5051_50511201_62_dialog_content = "At your service, my lord.",
  ui_story_5051_50511201_63_dialog_content = "Notify the Hall of Justice regarding concrete evidence of House Kartima's insurrection.",
  ui_story_5051_50511201_64_dialog_content = "Put a city-wide all-points bulletin out on <color=#FFB400>all members</color> of the Kartima family immediately",
  ui_story_5051_50511201_65_dialog_content = "Request that Hall of Justice issues the same and assist us in apprehending them.",
  ui_story_5051_50511201_66_dialog_content = "Execute suspect on the spot when met with resistance.",
  ui_story_5051_50511201_67_dialog_content = "Yes, my lord.",
  ui_story_5051_50511201_68_dialog_content = "All members of House Kartima? What are you doing, Daniel...?",
  ui_story_5051_50511201_69_dialog_content = "I've seen too many things like this happen this year.",
  ui_story_5051_50511201_70_dialog_content = "Aren't the spirits of House Pyrrhus and House Gautier enough?",
  ui_story_5051_50511201_71_dialog_content = "Joshua...",
  ui_story_5051_50511201_72_dialog_content = "Carleen needs rest. Take her home.",
  ui_story_5051_50511201_73_dialog_content = "...",
  ui_story_5051_50511201_74_dialog_content = "Joshua... Lady Joshua, I am about to leave with my child as well.",
  ui_story_5051_50511201_75_dialog_content = "Allow me to walk you back.",
  ui_story_5051_50511201_76_dialog_content = "I appreciate the offer.",
  ui_story_5051_50511201_77_dialog_content = "But since the Eclipsites are removed in the city, I believe I can manage it on my own.",
  ui_story_5051_50511201_78_dialog_content = "Mr. Soroz... If I remember correctly, that is your name, right?",
  ui_story_5051_50511201_79_dialog_content = "Yes.",
  ui_story_5051_50511201_80_dialog_content = "I am sorry I doubted you.",
  ui_story_5051_50511201_81_dialog_content = "As you mentioned, you are quite capable of dealing with the Eclipsites.",
  ui_story_5051_50511201_82_dialog_content = "An outstanding warrior like you should not remain anonymous.",
  ui_story_5051_50511201_83_dialog_content = "I have not been a perfect host today, thus perhaps we can hold a lengthy exchange after all this is over.",
  ui_story_5051_50511201_84_dialog_content = "I am merely an ordinary old man.",
  ui_story_5051_50511201_85_dialog_content = "Who wished for a safe passage home for his child.",
  ui_story_5051_50511201_86_dialog_content = "What a pity, I thought we would have much in common to talk about.",
  ui_story_5051_50511201_87_dialog_content = "Maybe those who are too similar should not be friends.",
  ui_story_5051_50511201_88_dialog_content = "Heh, is that so?",
  ui_story_5051_50511201_89_dialog_content = "All right. Come, Veronica.",
  ui_story_5051_50511201_90_dialog_content = "M-me?",
  ui_story_5051_50511201_91_dialog_content = "Is there anyone else here named Veronica?",
  ui_story_5051_50511201_92_dialog_content = "Where are we going?",
  ui_story_5051_50511201_93_dialog_content = "To chase down the surviving Kartima rebels.",
  ui_story_5051_50511201_94_dialog_content = "I hope you can learn how to fight with me, starting today.",
  ui_story_5051_50511201_95_dialog_content = "Do you feel I'm qualified, Father...",
  ui_story_5051_50511201_96_dialog_content = "Princess Veronica's abilities were on full display.",
  ui_story_5051_50511201_97_dialog_content = "But she is still young and spent a lot of energy today.",
  ui_story_5051_50511201_98_dialog_content = "It is better for her to return home for rest.",
  ui_story_5051_50511201_99_dialog_content = "Mr. Soroz, perhaps PlayerName needs a rest, but Veronica is my daughter.",
  ui_story_5051_50511201_100_dialog_content = "Let us look after our children, respectively.",
  ui_story_5051_50511201_101_dialog_content = "<size=30>Well, uh...</size>",
  ui_story_5051_50511201_102_dialog_content = "She needs to rest.",
  ui_story_5051_50511201_103_dialog_content = "She needs to learn.",
  ui_story_5051_50511201_104_dialog_content = "<size=45>Well!</size>",
  ui_story_5051_50511201_105_dialog_content = "What?",
  ui_story_5051_50511201_106_dialog_content = "I, I...",
  ui_story_5051_50511201_107_dialog_content = "I want to go!",
  ui_story_5051_50511201_108_dialog_content = "?!",
  ui_story_5051_50511201_109_dialog_content = "Father has never been more approved of me...",
  ui_story_5051_50511201_110_dialog_content = "I will never let him down again!",
  ui_story_5051_50511201_111_dialog_content = "Plus, I'd like to see how this history I was never a part of will turn out.",
  ui_story_5051_50511201_112_dialog_content = "...",
  ui_story_5051_50511201_113_dialog_content = "Time to go, Veronica!",
  ui_story_5051_50511201_114_dialog_content = "C-Coming!",
  ui_story_5051_50511201_115_dialog_content = "Then I'm going too!",
  ui_story_5051_50511201_116_dialog_content = "You are all much too stubborn.",
  ui_story_5051_50511201_117_dialog_content = "Hey, old Schwartz, Boaz is completely out and it doesn't feel right...",
  ui_story_5051_50511201_118_dialog_content = "The lady said she'd bring her in for treatment, but I just can't leave her to fate.",
  ui_story_5051_50511201_119_dialog_content = "You must be careful if you go somewhere else.",
  ui_story_5051_50511201_120_dialog_content = "Also, make sure you get back before the day's over, or we might be trapped here forever...",
  ui_story_5051_50511201_121_dialog_content = "... I see.",
  ui_story_5051_50511201_122_dialog_content = "But what did you just call me?",
  ui_story_5051_50511201_123_dialog_content = "Oops, it was a slip.",
  ui_story_5051_50511201_124_dialog_content = "Anyway, come back as soon as you can!",
  ui_story_5051_50511201_125_dialog_content = "<color=#e8d9bb>Otto Residence</color>",
  ui_story_5051_50511201_126_dialog_content = "Did you know about this, Duke Troy?",
  ui_story_5051_50511201_127_dialog_content = "What? What are you referring to, Duke Hermes?",
  ui_story_5051_50511201_128_dialog_content = "It's a big mess out there, so stop fooling me around.",
  ui_story_5051_50511201_129_dialog_content = "Oh, you mean someone tried to take advantage of an Eclipsite incursion to assassinate the City Lord?",
  ui_story_5051_50511201_130_dialog_content = "Yes!",
  ui_story_5051_50511201_131_dialog_content = "Regardless of how much I disapprove of Schwartz, I would never stoop so low and risk ruining my family name.",
  ui_story_5051_50511201_132_dialog_content = "So, you indeed knew nothing of it?",
  ui_story_5051_50511201_133_dialog_content = "Duke Hermes, why must you be so paranoid and suspect everyone?",
  ui_story_5051_50511201_134_dialog_content = "I don't mean to question you, Duke Troy.",
  ui_story_5051_50511201_135_dialog_content = "But... you know, the descendants of the Hermes family have all joined the Lumo Knights.",
  ui_story_5051_50511201_136_dialog_content = "Schwartz is now calling for the entire order to aid Umbraton, which I've opposed all along!",
  ui_story_5051_50511201_137_dialog_content = "Those ground-crawling Eclipsites can't affect Lumopolis.",
  ui_story_5051_50511201_138_dialog_content = "So why should we be sent to our death?",
  ui_story_5051_50511201_139_dialog_content = "I'm not the only one with that thought, am I?",
  ui_story_5051_50511201_140_dialog_content = "The City Lord has his concerns too, Duke Hermes.",
  ui_story_5051_50511201_141_dialog_content = "Lumopolis would be able to exert tighter control over Umbraton if we defend it, isn't that better?",
  ui_story_5051_50511201_142_dialog_content = "It's not like you don't get that, Duke Hermes.",
  ui_story_5051_50511201_143_dialog_content = "Even a small edge like that would probably end up seized by Schwartz, anyway.",
  ui_story_5051_50511201_144_dialog_content = "And he got the gall to celebrate the so-called Schwartz Family Day.",
  ui_story_5051_50511201_145_dialog_content = "The Hermes and Troy families both made significant contributions to make Lumopolis what it is today!",
  ui_story_5051_50511201_146_dialog_content = "Why should House Schwartz get everything?!",
  ui_story_5051_50511201_147_dialog_content = "If the Kartimas had let us in on the plan and combined our forces together...",
  ui_story_5051_50511201_148_dialog_content = "We would be standing up to Schwartz!",
  ui_story_5051_50511201_149_dialog_content = "Be careful of your words, Duke Hermes.",
  ui_story_5051_50511201_150_dialog_content = "I just got the news that the City Lord ordered the arrest of all Kartimas.",
  ui_story_5051_50511201_151_dialog_content = "Even a toddler can figure out how it's going to end for them.",
  ui_story_5051_50511201_152_dialog_content = "It can't be as bad as for House Pyrrhus and House Gautier!",
  ui_story_5051_50511201_153_dialog_content = "Sigh. You still don't get it? That's where the problem lies.",
  ui_story_5051_50511201_154_dialog_content = "What? You mean...",
  ui_story_5051_50511201_155_dialog_content = "Wait, I get it, I connect all the dots now!",
  ui_story_5051_50511201_156_dialog_content = "The Kartimas are such fools!",
  ui_story_5051_50511201_157_dialog_content = "They just gave Schwartz more clout with what they just did!",
  ui_story_5051_50511201_158_dialog_content = "Schwartz can use it to summon the Lumo Knights and even private house armies to their deaths in Umbraton.",
  ui_story_5051_50511201_159_dialog_content = "Mime Kartima, you brainless fool!",
  ui_story_5051_50511201_160_dialog_content = "Under the circumstances, the less spoken the better, Duke Hermes.",
  ui_story_5051_50511201_161_dialog_content = "And I dozed off and missed everything you said.",
  ui_story_5051_50511201_162_dialog_content = "Thank you, Duke Troy. Please do not let me keep you. Farewell.",
  ui_story_5051_50511201_163_dialog_content = "Servant.",
  ui_story_5051_50511201_164_dialog_content = "Yes.",
  ui_story_5051_50511201_165_dialog_content = "And destroy all hints of correspondence with House Kartima.",
  ui_story_5051_50511201_166_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50511201_167_dialog_content = "What was that?",
  ui_story_5051_50511201_168_dialog_content = "I shall check.",
  ui_story_5051_50511201_169_dialog_content = "Did you see who it was?",
  ui_story_5051_50511201_170_dialog_content = "It was Miss Rohsee. You are supposed to see her before dinner.",
  ui_story_5051_50511201_171_dialog_content = "She had been waiting outside for a while.",
  ui_story_5051_50511201_172_dialog_content = "But just left in a panic.",
  ui_story_5051_50511201_173_dialog_content = "Ah, kids these days...",
  ui_story_5051_50511301_1_dialog_content = "We found nothing on this Kartima property either, City Lord.",
  ui_story_5051_50511301_2_dialog_content = "All Kartima assets in Lumopolis Gardens have been confiscated. Other than servants, no armed personnel was discovered.",
  ui_story_5051_50511301_3_dialog_content = "Except for an airship that ignored warnings and left Lumopolis...",
  ui_story_5051_50511301_4_dialog_content = "All other members of House Kartima should still be hiding within the city.",
  ui_story_5051_50511301_5_dialog_content = "What about Lumopolis Courtyard and Lower Lumopolis?",
  ui_story_5051_50511301_6_dialog_content = "Personnel has been dispatched, but time is required to gather specific details.",
  ui_story_5051_50511301_7_dialog_content = "They did not flee but hid in the city?",
  ui_story_5051_50511301_8_dialog_content = "It seems they are waiting for an opportunity to strike again.",
  ui_story_5051_50511301_9_dialog_content = "House Kartima boasts many members and has gained ample affiliates in recent years.",
  ui_story_5051_50511301_10_dialog_content = "Given that, the situation is more precarious than imagined...",
  ui_story_5051_50511301_11_dialog_content = "We cannot be passive.",
  ui_story_5051_50511301_12_dialog_content = "We must continue the search in Lumopolis Courtyard.",
  ui_story_5051_50511301_13_dialog_content = "Just a moment, please.",
  ui_story_5051_50511301_14_dialog_content = "Y-You've come after all!",
  ui_story_5051_50511301_15_dialog_content = "...",
  ui_story_5051_50511301_16_dialog_content = "<size=30>Don't be afraid, Mia, I'm not here to take you back.</size>",
  ui_story_5051_50511301_17_dialog_content = "<size=30>I pondered it and you have the right to know this part of history.</size>",
  ui_story_5051_50511301_18_dialog_content = "Mr. Soroz? I knew we would meet again very soon.",
  ui_story_5051_50511301_19_dialog_content = "Though I did not expect it to be this quickly.",
  ui_story_5051_50511301_20_dialog_content = "I suddenly recalled that I may have the leads you are looking for.",
  ui_story_5051_50511301_21_dialog_content = "I hope you are not delaying me on purpose.",
  ui_story_5051_50511301_22_dialog_content = "Of course not. I also hope my rebellious child will go home with me willingly in time.",
  ui_story_5051_50511301_23_dialog_content = "However, I would like you to promise me that you will not pursue my source of information.",
  ui_story_5051_50511301_24_dialog_content = "Sure, I promise I will not pursue your source. Tell me, what leads have you?",
  ui_story_5051_50511301_25_dialog_content = "There are signs of private armies making camp on an undeveloped field in Lower Lumopolis.",
  ui_story_5051_50511301_26_dialog_content = "Have you heard this, Ms. Rot?",
  ui_story_5051_50511301_27_dialog_content = "Wilderness near the outskirts...",
  ui_story_5051_50511301_28_dialog_content = "Can it be that rocky hill?",
  ui_story_5051_50511301_29_dialog_content = "I have heard accounts of occasional, strange cries of animals, but it is desolate.",
  ui_story_5051_50511301_30_dialog_content = "Are you saying, Mr. Soroz, that is where the Kartimas may be hiding?",
  ui_story_5051_50511301_31_dialog_content = "I am a hundred percent certain.",
  ui_story_5051_50511301_32_dialog_content = "Why are you so sure? From where did you get that information?",
  ui_story_5051_50511301_33_dialog_content = "You promised me not to ask.",
  ui_story_5051_50511301_34_dialog_content = "But you may punish me however you want should the information be false.",
  ui_story_5051_50511301_35_dialog_content = "All right. Ms. Rot, let us head for the area.",
  ui_story_5051_50511301_36_dialog_content = "Is the lead trustworthy, City Lord?",
  ui_story_5051_50511301_37_dialog_content = "The surrender and downfall of the Kartimas are inevitable.",
  ui_story_5051_50511301_38_dialog_content = "It matters not to trust him this once.",
  ui_story_5051_50511301_39_dialog_content = "Of course, do not stop combing other areas either.",
  ui_story_5051_50511301_40_dialog_content = "Yes, my lord.",
  ui_story_5051_50511301_41_dialog_content = "Hmm...",
  ui_story_5051_50511301_42_dialog_content = "Do you have a question for me?",
  ui_story_5051_50511301_43_dialog_content = "About that lead, did you get it from somebody back then?",
  ui_story_5051_50511301_44_dialog_content = "No, we did not find any useful information in the city.",
  ui_story_5051_50511301_45_dialog_content = "Only in the evening did we notice movements in the wilderness and suffer a brutal offensive from them.",
  ui_story_5051_50511301_46_dialog_content = "However, ultimately they still could not avoid defeat.",
  ui_story_5051_50511301_47_dialog_content = "Did you speed up the timeline so we can return as soon as possible?",
  ui_story_5051_50511301_48_dialog_content = "Sometimes, I would think if I had located the rebel forces sooner...",
  ui_story_5051_50511301_49_dialog_content = "Maybe the soldiers who have followed me for years would have a few children they found troublesome now.",
  ui_story_5051_50511301_50_dialog_content = "Haven't you been apprehensive about messing up this world?",
  ui_story_5051_50511301_51_dialog_content = "We have already done enough. This one will not make a big difference.",
  ui_story_5051_50511301_52_dialog_content = "You're not quite the Lord Schwartz I knew now.",
  ui_story_5051_50511301_53_dialog_content = "You think so? I feel different too, once I let go of my City Lord status.",
  ui_story_5051_50511301_54_dialog_content = "Especially after meeting my younger self.",
  ui_story_5051_50511301_55_dialog_content = "This is the place?",
  ui_story_5051_50511301_56_dialog_content = "According to scouts, the Kartimas have indeed convened on the hill ahead.",
  ui_story_5051_50511301_57_dialog_content = "They seem to be planning to fight until the last breath!",
  ui_story_5051_50511301_58_dialog_content = "Come, Veronica.",
  ui_story_5051_50511301_59_dialog_content = "Tell me, what would you do in this situation if you were in command?",
  ui_story_5051_50511301_60_dialog_content = "If I was in command...",
  ui_story_5051_50511301_61_dialog_content = "I would send an envoy over to reason with or persuade them.",
  ui_story_5051_50511301_62_dialog_content = "Encourage them to admit the error of their ways and make up for it.",
  ui_story_5051_50511301_63_dialog_content = "Wrong, Veronica.",
  ui_story_5051_50511301_64_dialog_content = "If you want to bear greater responsibilities, you must force yourself to win <color=#FFB400>at whatever the cost</color>.",
  ui_story_5051_50511301_65_dialog_content = "Win at whatever the cost?",
  ui_story_5051_50511301_66_dialog_content = "From Lumopolis Gardens down to Umbraton, all eyes are on this battle.",
  ui_story_5051_50511301_67_dialog_content = "They are waiting to see who will emerge victorious and will only praise the winner, regardless of who that may be.",
  ui_story_5051_50511301_68_dialog_content = "History is written by the victors.",
  ui_story_5051_50511301_69_dialog_content = "The history of Lumopolis is likely to change in the not-too-distant future.",
  ui_story_5051_50511301_70_dialog_content = "You still have a lot to learn, Veronica.",
  ui_story_5051_50511301_71_dialog_content = "Whatever the cost? I find that perspective... hard to swallow.",
  ui_story_5051_50511301_72_dialog_content = "Is that so?",
  ui_story_5051_50511301_73_dialog_content = "(Oops, I forgot that snarking the young Schwartz is the same as snarking him!)",
  ui_story_5051_50511301_74_dialog_content = "Uh, that wasn't intentional...",
  ui_story_5051_50511301_75_dialog_content = "You just have to make some decisions when you are on top, even though that sounds like an excuse to shirk blame.",
  ui_story_5051_50511301_76_dialog_content = "But the present me will not boast emphatically that I am an impeccable great leader.",
  ui_story_5051_50511301_77_dialog_content = "I only hope...",
  ui_story_5051_50511301_78_dialog_content = "That you will blaze your own trail in the future and find a path belonging solely to you.",
  ui_story_5051_50511301_79_dialog_content = "I will!",
  ui_story_5051_50511301_80_dialog_content = "I hope when I grow old, I don't regret my younger self.",
  ui_story_5051_50511301_81_dialog_content = "Uh, that wasn't meant to be sarcasm toward you!",
  ui_story_5051_50511301_82_dialog_content = "Ha ha ha!",
  ui_story_5051_50511301_83_dialog_content = "(This is the first time I remember seeing Schwartz laughing out loud.)",
  ui_story_5051_50511301_84_dialog_content = "(I just realized, outside of this old and young Schwartz...)",
  ui_story_5051_50511301_85_dialog_content = "(In an even more distant past, there was an innocent, laugh-out-loud Daniel...)",
  ui_story_5051_50511301_86_dialog_content = "I sense something up ahead.",
  ui_story_5051_50511301_87_dialog_content = "... Rebels lying in ambush!",
  ui_story_5051_50511302_1_dialog_content = "I've searched all of the main rooms.",
  ui_story_5051_50511302_2_dialog_content = "Yet I still cannot find it!",
  ui_story_5051_50511302_3_dialog_content = "Did Schwartz build a secret chamber?",
  ui_story_5051_50511302_4_dialog_content = "That must be the case.",
  ui_story_5051_50511302_5_dialog_content = "Judging from Schwartz's personality, he must be hiding a lot of secrets from Joshua.",
  ui_story_5051_50511302_6_dialog_content = "Could the secret entrance be in his study?",
  ui_story_5051_50511302_7_dialog_content = "Hmm, what's that on the bookshelf?",
  ui_story_5051_50511302_8_dialog_content = "The Crystal of Eternal Memory?!",
  ui_story_5051_50511302_9_dialog_content = "Yes, it is indeed the Crystal of Eternal Memory!",
  ui_story_5051_50511302_10_dialog_content = "The most dangerous place is the safest, heh?",
  ui_story_5051_50511302_11_dialog_content = "Hahaha.",
  ui_story_5051_50511302_12_dialog_content = "I can't believe Schwartz would leave something this precious out in the open.",
  ui_story_5051_50511302_13_dialog_content = "Just like what he did to my dear sister...",
  ui_story_5051_50511302_14_dialog_content = "You're back, My Lady!",
  ui_story_5051_50511302_15_dialog_content = "It's her...",
  ui_story_5051_50511302_16_dialog_content = "You seem nervous. What happened?",
  ui_story_5051_50511302_17_dialog_content = "Please forgive my ineptitude!",
  ui_story_5051_50511302_18_dialog_content = "A gate guard was knocked out this afternoon and is still in the infirmary.",
  ui_story_5051_50511302_19_dialog_content = "We checked everywhere but still couldn't find the culprit...",
  ui_story_5051_50511302_20_dialog_content = "Someone from House Kartima again?",
  ui_story_5051_50511302_21_dialog_content = "I see.",
  ui_story_5051_50511302_22_dialog_content = "We have guests for the night. Please be more vigilant.",
  ui_story_5051_50511302_23_dialog_content = "Yes, My Lady!",
  ui_story_5051_50511302_24_dialog_content = "Also, make sure the injured guard recuperates in peace.",
  ui_story_5051_50511302_25_dialog_content = "I'll pay for the medical bill.",
  ui_story_5051_50511302_26_dialog_content = "Thank you, My Lady!",
  ui_story_5051_50511302_27_dialog_content = "The Kartimas...",
  ui_story_5051_50511302_28_dialog_content = "Don't you know someone in that family?",
  ui_story_5051_50511302_29_dialog_content = "Yeah, but I don't think she's one of the traitors.",
  ui_story_5051_50511302_30_dialog_content = "She was obviously very kind and upright.",
  ui_story_5051_50511302_31_dialog_content = "She also told me she wants to become an awesome knight captain!",
  ui_story_5051_50511302_32_dialog_content = "Your friend is likely innocent and knew nothing of the plot.",
  ui_story_5051_50511302_33_dialog_content = "What's gonna happen if she's caught?",
  ui_story_5051_50511302_34_dialog_content = "I don't know yet.",
  ui_story_5051_50511302_35_dialog_content = "But relax, I'll do my best to defend the innocents.",
  ui_story_5051_50511302_36_dialog_content = "Even though her people tried to assassinate you and your family?",
  ui_story_5051_50511302_37_dialog_content = "Sinners deserve to be punished.",
  ui_story_5051_50511302_38_dialog_content = "But I don't think the innocents should be just because of their bloodline.",
  ui_story_5051_50511302_39_dialog_content = "Let's not talk about this right now.",
  ui_story_5051_50511302_40_dialog_content = "Let me go get supper as well as a hangover cure for Boaz ready.",
  ui_story_5051_50511302_41_dialog_content = "Aren't you concerned about the City Lord?",
  ui_story_5051_50511302_42_dialog_content = "Of course I am!",
  ui_story_5051_50511302_43_dialog_content = "But I'm much more confident in Daniel returning safely.",
  ui_story_5051_50511302_44_dialog_content = "That's why I have to have supper ready when he comes back!",
  ui_story_5051_50511302_45_dialog_content = "I'm starting to miss you already, Lady Joshua!",
  ui_story_5051_50511302_46_dialog_content = "Then you should drop by Lumopolis more often, Jakine!",
  ui_story_5051_50511302_47_dialog_content = "Veronica and Carleen would love to have a new friend like you.",
  ui_story_5051_50511302_48_dialog_content = "*Sniffle*",
  ui_story_5051_50511302_49_dialog_content = "Shush—",
  ui_story_5051_50511302_50_dialog_content = "Boaz and Carleen are still asleep. Try not to wake them up!",
  ui_story_5051_50511401_1_dialog_content = "I figured with the Eclipsites running interference, I had Schwartz in the bag.",
  ui_story_5051_50511401_2_dialog_content = "Yet I still underestimated him.",
  ui_story_5051_50511401_3_dialog_content = "Announcing to the world he is ill was a deliberate ruse.",
  ui_story_5051_50511401_4_dialog_content = "Guess he already saw through my plot.",
  ui_story_5051_50511401_5_dialog_content = "When it comes to cunning, very few in Lumopolis can best Schwartz.",
  ui_story_5051_50511401_6_dialog_content = "And I thought I've gotten devious enough over the years...",
  ui_story_5051_50511401_7_dialog_content = "...",
  ui_story_5051_50511401_8_dialog_content = "How could this happen? Mime, why did you awaken the <color=#FFB400>Dragonkin</color>?",
  ui_story_5051_50511401_9_dialog_content = "That's inexcusable in House Kartima!",
  ui_story_5051_50511401_10_dialog_content = "I didn't do it on purpose... Save me, Mother!",
  ui_story_5051_50511401_11_dialog_content = "Never let anyone know about this, my child.",
  ui_story_5051_50511401_12_dialog_content = "But my head is about to split open...",
  ui_story_5051_50511401_13_dialog_content = "Hold on, Mime! Tell me... Tell me you can suppress this power!",
  ui_story_5051_50511401_14_dialog_content = "The person to lead House Kartima has to be and must be you!",
  ui_story_5051_50511401_15_dialog_content = "It hurts... I can't do this!",
  ui_story_5051_50511401_16_dialog_content = "You must!",
  ui_story_5051_50511401_17_dialog_content = "I dare you to say that again!",
  ui_story_5051_50511401_18_dialog_content = "Even though you locked me away on this teetering tower *cough*",
  ui_story_5051_50511401_19_dialog_content = "I'll still repeat the same words!",
  ui_story_5051_50511401_20_dialog_content = "Mime, you cannot save the Kartima family.",
  ui_story_5051_50511401_21_dialog_content = "You are not the leader of the family!",
  ui_story_5051_50511401_22_dialog_content = "Yes, I did awaken the Dragonkin, so what?",
  ui_story_5051_50511401_23_dialog_content = "For I am the leader of House Kartima. That's a simple fact.",
  ui_story_5051_50511401_X23_dialog_content = "You have awakened the Dragonkin?!",
  ui_story_5051_50511401_X24_dialog_content = "I'm surprised that you managed to keep the truth from those clansmen who consider the Dragonkin a sin... You really have some tricks up your sleeve.",
  ui_story_5051_50511401_X25_dialog_content = "Still, I must say that you are not the one to save House Kartima.",
  ui_story_5051_50511401_X26_dialog_content = "It doesn't matter if you've awakened the Dragonkin or not.",
  ui_story_5051_50511401_X27_dialog_content = "Too bad no one will believe your prophecy.",
  ui_story_5051_50511401_24_dialog_content = "Hahahahah! Cough...",
  ui_story_5051_50511401_25_dialog_content = "Be afraid, the girl who will save the Kartimas shall soon appear to you.",
  ui_story_5051_50511401_26_dialog_content = "You are utterly mad.",
  ui_story_5051_50511401_27_dialog_content = "No one else likes this child or is willing to foster her.",
  ui_story_5051_50511401_28_dialog_content = "Good evening, Lord Mime.",
  ui_story_5051_50511401_29_dialog_content = "I'm Sharona.",
  ui_story_5051_50511401_30_dialog_content = "!!!",
  ui_story_5051_50511401_31_dialog_content = "Can you be the one whom the elder spoke of?",
  ui_story_5051_50511401_32_dialog_content = "I promise I won't cause any trouble for you.",
  ui_story_5051_50511401_33_dialog_content = "I'm taking this kid in.",
  ui_story_5051_50511401_34_dialog_content = "Th-Thank you, Lord Mime!",
  ui_story_5051_50511401_35_dialog_content = "Be prepared, you will never amount to anything here.",
  ui_story_5051_50511401_36_dialog_content = "Sigh...",
  ui_story_5051_50511401_37_dialog_content = "Lord Mime, Lord Mime...",
  ui_story_5051_50511401_38_dialog_content = "What is it?",
  ui_story_5051_50511401_39_dialog_content = "All House Kartima members and soldiers have assembled.",
  ui_story_5051_50511401_40_dialog_content = "I made you accomplices in the end...",
  ui_story_5051_50511401_41_dialog_content = "We have no problem with that, my lord!",
  ui_story_5051_50511401_42_dialog_content = "Schwartz has been diminishing the power of House Kartima.",
  ui_story_5051_50511401_43_dialog_content = "If it wasn't for you, Schwartz would have long ruined us by now.",
  ui_story_5051_50511401_44_dialog_content = "All right, enough of that.",
  ui_story_5051_50511401_45_dialog_content = "No, I must speak up! We must speak up!",
  ui_story_5051_50511401_46_dialog_content = "We all saw the contributions you made to House Kartima.",
  ui_story_5051_50511401_47_dialog_content = "We're willing to follow you to the end without regret!",
  ui_story_5051_50511401_48_dialog_content = "Schwartz knew everyone opposed sending reinforcement to Umbraton...",
  ui_story_5051_50511401_49_dialog_content = "Yet he tried to force you to take an oath in support of that very idea in today's ceremony.",
  ui_story_5051_50511401_50_dialog_content = "That clearly made us the target of other houses as to advance his own ambition.",
  ui_story_5051_50511401_51_dialog_content = "Compared to dying in Eclipsites' hands for Schwartz's interest...",
  ui_story_5051_50511401_52_dialog_content = "We're considerably more willing to die for House Kartima!",
  ui_story_5051_50511401_53_dialog_content = "<size=45>Die for House Kartima! Die for House Kartima! Die for House Kartima!</size>",
  ui_story_5051_50511401_54_dialog_content = "Wonderful! But I disagree with one of the points.",
  ui_story_5051_50511401_55_dialog_content = "The outcome of this battle has yet to be determined!",
  ui_story_5051_50511401_56_dialog_content = "You're correct, my lord!",
  ui_story_5051_50511401_57_dialog_content = "We're ready to follow you and recapture Kartimas' lost glory!",
  ui_story_5051_50511401_58_dialog_content = "We're fully prepared and awaiting your order.",
  ui_story_5051_50511401_59_dialog_content = "We vow to defend House Kartima's honor to our death!",
  ui_story_5051_50511401_60_dialog_content = "<size=45>Defend Kartima's honor! Defend Kartima's honor! Defend Kartima's honor!</size>",
  ui_story_5051_50511401_61_dialog_content = "Alright!",
  ui_story_5051_50511401_62_dialog_content = "Now, let me unveil our final reinforcement.",
  ui_story_5051_50511401_63_dialog_content = "Reinforcement?",
  ui_story_5051_50511401_64_dialog_content = "\"The dragon soaring through the sky, the eternal partner of Kartima.\"",
  ui_story_5051_50511401_65_dialog_content = "\"Unfurl your wings and pierce the endless night.\"",
  ui_story_5051_50511401_66_dialog_content = "\"Come to me.\"",
  ui_story_5051_50511401_67_dialog_content = "\"Come to us.\"",
  ui_story_5051_50511401_68_dialog_content = "\"House Kartima never forgets our pact.\"",
  ui_story_5051_50511401_69_dialog_content = "<anim type=Shake><size=45>Roar—!</size></anim>",
  ui_story_5051_50511401_70_dialog_content = "That voice...",
  ui_story_5051_50511401_71_dialog_content = "Did you just summon the <color=#FFB400>dragon</color>, my lord?!",
  ui_story_5051_50511401_72_dialog_content = "The dragon has always been the most loyal ally to House Kartima.",
  ui_story_5051_50511401_73_dialog_content = "Some people envied our power and convinced our forefathers that dragons are portents of evil.",
  ui_story_5051_50511401_74_dialog_content = "Some people? Could that be House Schwartz...?",
  ui_story_5051_50511401_75_dialog_content = "<size=45>Come, Ganon! Come to your friends and family!</size>",
  ui_story_5051_50511401_76_dialog_content = "<anim type=Shake><size=45>Growl!</size></anim>",
  ui_story_5051_50511401_77_dialog_content = "Now, we need to worry about heretics no more.",
  ui_story_5051_50511401_78_dialog_content = "<anim type=Shake><size=45>Roar!</size></anim>",
  ui_story_5051_50511401_79_dialog_content = "Listen up, members of House Kartima!",
  ui_story_5051_50511401_80_dialog_content = "The dragon has returned!",
  ui_story_5051_50511401_81_dialog_content = "It will assist us in lording over Lumopolis!",
  ui_story_5051_50511401_82_dialog_content = "Long live the dragon!",
  ui_story_5051_50511401_83_dialog_content = "<anim type=Shake><size=45>Roar—!!!</size></anim>",
  ui_story_5051_50511401_84_dialog_content = "<color=#e8d9bb>Meanwhile in Umbraton</color>",
  ui_story_5051_50511401_85_dialog_content = "Did you hear that?",
  ui_story_5051_50511401_86_dialog_content = "I thought something was wrong with my ear!",
  ui_story_5051_50511401_87_dialog_content = "It can't be Eclipsites attacking again, can it?",
  ui_story_5051_50511401_88_dialog_content = "Stop talking nonsense and go home!",
  ui_story_5051_50511401_89_dialog_content = "Yeah, let's go await our fate back home.",
  ui_story_5051_50511401_90_dialog_content = "Umbraton is more humid than I remembered.",
  ui_story_5051_50511401_91_dialog_content = "Looking at Lumopolis from this vantage point...",
  ui_story_5051_50511401_92_dialog_content = "It does look very different.",
  ui_story_5051_50511401_93_dialog_content = "The nights up there feel colder than down here.",
  ui_story_5051_50511401_94_dialog_content = "Did that roar come from an Eclipsite?",
  ui_story_5051_50511401_95_dialog_content = "No, not Eclipsite.",
  ui_story_5051_50511401_96_dialog_content = "What else could it be, then?",
  ui_story_5051_50511401_97_dialog_content = "Look, it's coming.",
  ui_story_5051_50511401_98_dialog_content = "<anim type=Shake><size=45>Roar—!</size></anim>",
  ui_story_5051_50511401_99_dialog_content = "A flying dragon?",
  ui_story_5051_50511401_100_dialog_content = "Yes, they are indeed blinded by the evil dragon's hatred.",
  ui_story_5051_50511401_101_dialog_content = "Is the Kartima bloodline destined to be bound forever to that ancient bargain?",
  ui_story_5051_50511401_102_dialog_content = "The dragon is going to be here soon!",
  ui_story_5051_50511401_103_dialog_content = "Stay back, Veronica!",
  ui_story_5051_50511401_104_dialog_content = "Let me check out what this dragon is capable of.",
  ui_story_5051_50511401_105_dialog_content = "It is enormous in size, able to breathe fire.",
  ui_story_5051_50511401_106_dialog_content = "In order to avoid severe injury, the best option is first to strike its vulnerable spot.",
  ui_story_5051_50511401_107_dialog_content = "And this dragon's vulnerable spot is...",
  ui_story_5051_50511401_108_dialog_content = "I know what it is, naturally.",
  ui_story_5051_50511401_109_dialog_content = "He walked off before you could finish.",
  ui_story_5051_50511401_110_dialog_content = "I see this battle is going to take some time.",
  ui_story_5051_50511401_111_dialog_content = "Did you not know the dragon's weak spot?",
  ui_story_5051_50511401_112_dialog_content = "Or were you not able to hit it on the first try?",
  ui_story_5051_50511401_113_dialog_content = "...",
  ui_story_5051_50511401_114_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5051_50511401_115_dialog_content = "The wind is rising. This is different from what I remembered.",
  ui_story_5051_50511401_116_dialog_content = "(Did he just selectively ignore that question?)",
  ui_story_5051_50511401_117_dialog_content = "If we can take advantage of the wind's direction, perhaps...",
  ui_story_5051_50511401_118_dialog_content = "The battle may end early.",
  ui_story_5051_50511401_119_dialog_content = "Ha—!",
  ui_story_5051_50511401_120_dialog_content = "Light of White Night!",
  ui_story_5051_50511401_121_dialog_content = "<anim type=Shake>Graw!</anim>",
  ui_story_5051_50511401_122_dialog_content = "(Young Schwartz struck the dragon precisely in the throat to prevent it from breathing fire temporarily...)",
  ui_story_5051_50511401_123_dialog_content = "(Is that its weakness, though?)",
  ui_story_5051_50511401_124_dialog_content = "(I can't really tell, but there seems to be a figure on the dragon's back.)",
  ui_story_5051_50511401_125_dialog_content = "It's Mime Kartima!",
  ui_story_5051_50511401_126_dialog_content = "The captain of the knights we met when we were coming into the city?",
  ui_story_5051_50511401_127_dialog_content = "Heh, is this all the dragon can do?",
  ui_story_5051_50511401_128_dialog_content = "I see I do not need to fight with full strength.",
  ui_story_5051_50511401_129_dialog_content = "Count yourself lucky to withstand the first attack.",
  ui_story_5051_50511401_130_dialog_content = "Do not confuse luck with prowess, esteemed City Lord.",
  ui_story_5051_50511401_131_dialog_content = "You fortuitously evaded Ganon's flame, like you fortuitously became the City Lord.",
  ui_story_5051_50511401_132_dialog_content = "Ganon? You named your dragon, I see.",
  ui_story_5051_50511401_133_dialog_content = "This is a dangerous move, Mime.",
  ui_story_5051_50511401_134_dialog_content = "You will be incredibly sad when it is killed.",
  ui_story_5051_50511401_135_dialog_content = "You talk too much!",
  ui_story_5051_50511401_136_dialog_content = "Charge, Ganon!",
  ui_story_5051_50511401_137_dialog_content = "Deliver your fiercest flame to this man before you!",
  ui_story_5051_50511401_138_dialog_content = "One gift from you to my shoulder is quite enough. I should not accept another.",
  ui_story_5051_50511401_139_dialog_content = "However, allow me to reciprocate!",
  ui_story_5051_50511401_140_dialog_content = "Ephemeral nights and days without end!",
  ui_story_5051_50511401_141_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5051_50511401_142_dialog_content = "Charge!",
  ui_story_5051_50511401_143_dialog_content = "The rebels are charging...",
  ui_story_5051_50511401_144_dialog_content = "All hands, listen up!",
  ui_story_5051_50511401_145_dialog_content = "Prepare for battle!",
  ui_story_5051_50511401_146_dialog_content = "...",
  ui_story_5051_50511401_147_dialog_content = "Are you fighting too, Mia?",
  ui_story_5051_50511401_148_dialog_content = "If possible, I don't want to stain my weapon with my people's blood...",
  ui_story_5051_50511401_149_dialog_content = "Why did we make the choice back then, Father?",
  ui_story_5051_50511401_150_dialog_content = "Because they wanted to stain their weapons with our blood.",
  ui_story_5051_50511402_1_dialog_content = "<anim type=Shake>Roar...</anim>",
  ui_story_5051_50511402_2_dialog_content = "No, Ganon!",
  ui_story_5051_50511402_3_dialog_content = "This is not real...",
  ui_story_5051_50511402_4_dialog_content = "It isn't supposed to happen like this!",
  ui_story_5051_50511402_5_dialog_content = "(Young Schwartz indeed defeated the dragon by capitalizing on the wind.)",
  ui_story_5051_50511402_6_dialog_content = "(This battle ended quicker than I imagined.)",
  ui_story_5051_50511402_7_dialog_content = "Mime Kartima!",
  ui_story_5051_50511402_8_dialog_content = "As the captain of Lumopolis Knights, you should be resolute in defending the city.",
  ui_story_5051_50511402_9_dialog_content = "But you chose to betray Lumopolis and faith as a knight.",
  ui_story_5051_50511402_10_dialog_content = "You have caused irreparable damage and suffering to the people of Lumopolis.",
  ui_story_5051_50511402_11_dialog_content = "White Night up high!",
  ui_story_5051_50511402_12_dialog_content = "Your actions constituted treason.",
  ui_story_5051_50511402_13_dialog_content = "Henceforth, you are forever stripped of all titles and posts.",
  ui_story_5051_50511402_14_dialog_content = "You are condemned to await the Hall of Justice's final judgment in incarceration.",
  ui_story_5051_50511402_15_dialog_content = "Heh, why wait...",
  ui_story_5051_50511402_16_dialog_content = "Just kill me now, Schwartz!",
  ui_story_5051_50511402_17_dialog_content = "You do not wish to see your kins again?",
  ui_story_5051_50511402_18_dialog_content = "You...!",
  ui_story_5051_50511402_19_dialog_content = "All of this is my fault. No one else has anything to do with this!",
  ui_story_5051_50511402_20_dialog_content = "I coerced them into attacking...",
  ui_story_5051_50511402_21_dialog_content = "If you still have a thread of decency left, spare the children and elderly!",
  ui_story_5051_50511402_22_dialog_content = "At this point, the decision is not up to me.",
  ui_story_5051_50511402_23_dialog_content = "Save your begging for the court.",
  ui_story_5051_50511402_24_dialog_content = "The Hall of Justice will render a fair judgment.",
  ui_story_5051_50511402_25_dialog_content = "Heheh...",
  ui_story_5051_50511402_26_dialog_content = "<anim type=Shake><size=45>Hahaha!</size></anim>",
  ui_story_5051_50511402_27_dialog_content = "I'm indeed not the one to save House Kartima...",
  ui_story_5051_50511402_28_dialog_content = "If the elder was correct, she would complete the mission for me!",
  ui_story_5051_50511402_29_dialog_content = "It is you who just destroyed House Kartima.",
  ui_story_5051_50511402_30_dialog_content = "If you would publicly swear the oath to reinforce Umbraton with me as we previously agreed...",
  ui_story_5051_50511402_31_dialog_content = "Perhaps the ending would be different.",
  ui_story_5051_50511402_32_dialog_content = "Why you...!",
  ui_story_5051_50511402_33_dialog_content = "Not a chance!",
  ui_story_5051_50511402_34_dialog_content = "Watch out!!",
  ui_story_5051_50511402_35_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5051_50511402_36_dialog_content = "Err...",
  ui_story_5051_50511402_37_dialog_content = "(Mime still tried to attack even though he knew it was hopeless...)",
  ui_story_5051_50511402_38_dialog_content = "I admire your courage, Mime Kartima.",
  ui_story_5051_50511402_39_dialog_content = "Take over for me, Ms. Rot.",
  ui_story_5051_50511402_40_dialog_content = "I need to check on Carleen. Wait for me in the conference hall.",
  ui_story_5051_50511402_41_dialog_content = "Yes!",
  ui_story_5051_50511501_1_dialog_content = "I'm back, Joshua.",
  ui_story_5051_50511501_2_dialog_content = "Daniel...",
  ui_story_5051_50511501_3_dialog_content = "Let me see... Did the wound open up? Any new injuries?",
  ui_story_5051_50511501_4_dialog_content = "Relax, Joshua. I told you I would be fine.",
  ui_story_5051_50511501_5_dialog_content = "By the way, how is Carleen?",
  ui_story_5051_50511501_6_dialog_content = "The physician was here and said she'd be fine after a few days' rest.",
  ui_story_5051_50511501_7_dialog_content = "That's good to hear.",
  ui_story_5051_50511501_8_dialog_content = "Supper is ready for you to partake.",
  ui_story_5051_50511501_9_dialog_content = "No, I still have business to tend to.",
  ui_story_5051_50511501_10_dialog_content = "You should turn in early.",
  ui_story_5051_50511501_11_dialog_content = "You've been busy the whole day, Daniel. You're the one who should turn in.",
  ui_story_5051_50511501_12_dialog_content = "I must consult with the Elder Council and the Hall of Justice regarding the matter with House Kartima as soon as possible.",
  ui_story_5051_50511501_13_dialog_content = "Sorry, Joshua.",
  ui_story_5051_50511501_14_dialog_content = "Next time, after I'm done with this, all four of us will sit down for a family dinner, all right?",
  ui_story_5051_50511501_15_dialog_content = "Daniel, can you tell me what they're going to do to House Kartima?",
  ui_story_5051_50511501_16_dialog_content = "Do not even concern yourself with it. The Kartimas will get what they deserve.",
  ui_story_5051_50511501_17_dialog_content = "What about those who knew nothing of it?",
  ui_story_5051_50511501_18_dialog_content = "Will they get caught up in it too?",
  ui_story_5051_50511501_19_dialog_content = "Do not forget, Joshua.",
  ui_story_5051_50511501_20_dialog_content = "Today, those people from House Kartima pointed cold blades at us, at our darling daughters.",
  ui_story_5051_50511501_21_dialog_content = "They never considered our daughters to be innocent when they betrayed us.",
  ui_story_5051_50511501_22_dialog_content = "But...",
  ui_story_5051_50511501_23_dialog_content = "Let me ask you a question, Daniel.",
  ui_story_5051_50511501_24_dialog_content = "Did you find out about Kartima's plot ahead of time?",
  ui_story_5051_50511501_25_dialog_content = "Who told you?",
  ui_story_5051_50511501_26_dialog_content = "It's you, Daniel, you've not been acting yourself lately.",
  ui_story_5051_50511501_27_dialog_content = "Stop the conspiracy theory, would you?",
  ui_story_5051_50511501_28_dialog_content = "But how did you know there would be two waves of Eclipsites?",
  ui_story_5051_50511501_29_dialog_content = "Also, I thought about this...",
  ui_story_5051_50511501_30_dialog_content = "When we were practicing, you could sense a tiny movement fifty meters away.",
  ui_story_5051_50511501_31_dialog_content = "Yet you couldn't react in time to the assassin's glaringly obvious attack?",
  ui_story_5051_50511501_32_dialog_content = "Did you do that... <color=#FFB400>on purpose</color>?",
  ui_story_5051_50511501_33_dialog_content = "Though I couldn't figure out why you did it.",
  ui_story_5051_50511501_34_dialog_content = "Is it to garner public sympathy for the injury and solidify the case against Kartimas?",
  ui_story_5051_50511501_35_dialog_content = "It's not what you think.",
  ui_story_5051_50511501_36_dialog_content = "If I knew their plans, why would I allow you and our children to come along?",
  ui_story_5051_50511501_37_dialog_content = "!!!",
  ui_story_5051_50511501_38_dialog_content = "With Carleen and me by your side, the rebels wouldn't suspect anything and proceed with their plan...",
  ui_story_5051_50511501_39_dialog_content = "You treated us as <color=#FFB400>pawns</color>!",
  ui_story_5051_50511501_40_dialog_content = "...",
  ui_story_5051_50511501_41_dialog_content = "I am the City Lord of Lumopolis, deciding the future of this floating city.",
  ui_story_5051_50511501_42_dialog_content = "To that end, I will turn even myself into a chess piece.",
  ui_story_5051_50511501_43_dialog_content = "Such is the obligation we shoulder, Joshua.",
  ui_story_5051_50511501_44_dialog_content = "I know that everything you did is for fighting off Eclipsites.",
  ui_story_5051_50511501_45_dialog_content = "But why did you not tell me?",
  ui_story_5051_50511501_46_dialog_content = "Maybe we can come up with a perfect plan.",
  ui_story_5051_50511501_47_dialog_content = "I won't complain about you using me as a pawn.",
  ui_story_5051_50511501_48_dialog_content = "But how could you really use our children as chess pieces too?",
  ui_story_5051_50511501_49_dialog_content = "What if Carleen got—",
  ui_story_5051_50511501_50_dialog_content = "I won't let that happen.",
  ui_story_5051_50511501_51_dialog_content = "As a matter of fact, she is quite all right now, isn't she?",
  ui_story_5051_50511501_52_dialog_content = "That was pure luck, but what if?",
  ui_story_5051_50511501_53_dialog_content = "If there's a next time, promise me you'll tell me beforehand?",
  ui_story_5051_50511501_54_dialog_content = "Real-life politics are thousands of times more convoluted than in the books.",
  ui_story_5051_50511501_55_dialog_content = "I love you, Joshua...",
  ui_story_5051_50511501_56_dialog_content = "That‘s why I don't wish to embroil you in the filthy maelstrom.",
  ui_story_5051_50511501_57_dialog_content = "That's not what you told me when we were in school.",
  ui_story_5051_50511501_58_dialog_content = "You said we'll change Lumopolis together.",
  ui_story_5051_50511501_59_dialog_content = "And now you refuse to trust me.",
  ui_story_5051_50511501_60_dialog_content = "I have always trusted you. I have no problem letting you run the family.",
  ui_story_5051_50511501_61_dialog_content = "Likewise, you should trust my decisions in the political arena.",
  ui_story_5051_50511501_62_dialog_content = "Sacrificing a whole family to pave the way for your political domination.",
  ui_story_5051_50511501_63_dialog_content = "If that's your end game...",
  ui_story_5051_50511501_64_dialog_content = "I don't think I know who you are anymore, Daniel...",
  ui_story_5051_50511501_65_dialog_content = "You're starting to do whatever it takes to ensure your seat as the City Lord.",
  ui_story_5051_50511501_66_dialog_content = "No, it's not just whatever it takes.",
  ui_story_5051_50511501_67_dialog_content = "You have a heart more frigid than the snow on Northland peaks!",
  ui_story_5051_50511501_68_dialog_content = "Veronica became an oddity in the public eye because of you...",
  ui_story_5051_50511501_69_dialog_content = "Carleen will probably lose her life one day because of you too...",
  ui_story_5051_50511501_70_dialog_content = "Me, I'll leave you as well and vanish from the world...",
  ui_story_5051_50511501_71_dialog_content = "Joshua... Joshua!",
  ui_story_5051_50511501_72_dialog_content = "My Joshua!",
  ui_story_5051_50511501_73_dialog_content = "Why?",
  ui_story_5051_50511501_74_dialog_content = "<size=45>Why did you leave me?!</size>",
  ui_story_5051_50511501_75_dialog_content = "<anim type=Shake>Gasp... Gasp... Gasp...</anim>",
  ui_story_5051_50511501_76_dialog_content = "Are you all right? Is anything wrong?",
  ui_story_5051_50511501_77_dialog_content = "Joshua!",
  ui_story_5051_50511501_78_dialog_content = "What's the matter, Mr. Soroz?",
  ui_story_5051_50511501_79_dialog_content = "Your grip is cutting off Lady Joshua's hand, FATHER.",
  ui_story_5051_50511501_80_dialog_content = "Oh, I am so sorry.",
  ui_story_5051_50511501_X80_dialog_content = "For some reason it reminds me of the nightmares I often have.",
  ui_story_5051_50511501_81_dialog_content = "I probably need more rest at this old age...",
  ui_story_5051_50511501_82_dialog_content = "Please make yourself comfortable. Meal will be served shortly.",
  ui_story_5051_50511501_83_dialog_content = "You are a great host, Joshua.",
  ui_story_5051_50511501_84_dialog_content = "Supper will be ready soon. Why don't we all go to the dining hall?",
  ui_story_5051_50511501_85_dialog_content = "Not me, I still have business to tend to.",
  ui_story_5051_50511501_86_dialog_content = "Be sure to turn in early after you're done, all of you.",
  ui_story_5051_50511501_87_dialog_content = "You've been busy the whole day, Daniel. You're the one who should turn in.",
  ui_story_5051_50511501_88_dialog_content = "...",
  ui_story_5051_50511501_89_dialog_content = "<size=30>PlayerName, do something to distract them, quickly!</size>",
  ui_story_5051_50511501_90_dialog_content = "<size=30>What? Why?</size>",
  ui_story_5051_50511501_91_dialog_content = "<size=30>Otherwise, we will see a quarrel I do not wish to witness again...</size>",
  ui_story_5051_50511501_92_dialog_content = "I must consult with the Elder Council and the Hall of Justice regarding the matter with House Kartima as soon as possible.",
  ui_story_5051_50511501_93_dialog_content = "Sorry, Joshua.",
  ui_story_5051_50511501_94_dialog_content = "Next time, after I'm done with this, all four of us will sit down for a family dinner, all right?",
  ui_story_5051_50511501_95_dialog_content = "Yeah, I think that's a great idea!",
  ui_story_5051_50511501_96_dialog_content = "Huh?",
  ui_story_5051_50511501_97_dialog_content = "Those who should work ought to work, those who should rest ought to rest.",
  ui_story_5051_50511501_98_dialog_content = "I think... that's best for everyone.",
  ui_story_5051_50511501_99_dialog_content = "Yes, the children and I are famished, given today's activities.",
  ui_story_5051_50511501_100_dialog_content = "Take your time and have some rest, Mr. Soroz. We can chat another day.",
  ui_story_5051_50511501_101_dialog_content = "That is all.",
  ui_story_5051_50511501_102_dialog_content = "...",
  ui_story_5051_50511501_103_dialog_content = "And he leaves just like that.",
  ui_story_5051_50511501_104_dialog_content = "I'm sorry, Mr. Soroz, but I'll need a few minutes.",
  ui_story_5051_50511501_105_dialog_content = "The supper should be ready soon.",
  ui_story_5051_50511501_106_dialog_content = "Thank you.",
  ui_story_5051_50511501_107_dialog_content = "It's impossible for me to imagine you arguing with someone as sweet as Lady Joshua.",
  ui_story_5051_50511501_108_dialog_content = "Did you and Mother... argue on this day?",
  ui_story_5051_50511501_109_dialog_content = "...",
  ui_story_5051_50511501_110_dialog_content = "Are you that much of a coward to admit to what you did?",
  ui_story_5051_50511501_111_dialog_content = "Caleb? Where did you come from?",
  ui_story_5051_50511501_112_dialog_content = "Uncle?",
  ui_story_5051_50511501_113_dialog_content = "I heard Jakine run away and leave you behind, Caleb. When are you going to show some maturity?",
  ui_story_5051_50511501_114_dialog_content = "Don't go off on a tangent, City Lord.",
  ui_story_5051_50511501_115_dialog_content = "Are you really not going to admit to what you did?",
  ui_story_5051_50511501_116_dialog_content = "Then let me refresh your memory.",
  ui_story_5051_50511501_117_dialog_content = "Because of that argument, my sister left Castle Schwartz with Carleen.",
  ui_story_5051_50511501_118_dialog_content = "You two practically never spoke again or had a family meal together...",
  ui_story_5051_50511501_119_dialog_content = "Until my sister brought the dying Veronica back from the battlefield.",
  ui_story_5051_50511501_120_dialog_content = "You pretended to be buried in fighting the Eclipsites, when actually, you didn't want to face her...",
  ui_story_5051_50511501_121_dialog_content = "Then because of your political ambitions, you sent the injured Veronica to that lab in Illumina.",
  ui_story_5051_50511501_122_dialog_content = "Without knowing that the facility was run by merciless lunatics.",
  ui_story_5051_50511501_123_dialog_content = "My sister once again rescued Veronica from the lab, but she was severely hurt and became bedridden...",
  ui_story_5051_50511501_124_dialog_content = "Am I right, brother-in-law?",
  ui_story_5051_50511501_125_dialog_content = "<color=#FFB400>Illumina lab</color>... My head, it hurts.",
  ui_story_5051_50511501_126_dialog_content = "Sit down, Mia. Stop thinking about the past.",
  ui_story_5051_50511501_127_dialog_content = "...",
  ui_story_5051_50511501_128_dialog_content = "Where did you run off to, Caleb?",
  ui_story_5051_50511501_129_dialog_content = "You've been missing for a whole day. It made me think you didn't want to leave!",
  ui_story_5051_50511501_130_dialog_content = "I've been here the whole time, she just didn't recognize me.",
  ui_story_5051_50511501_131_dialog_content = "I didn't want my presence to distract her...",
  ui_story_5051_50511501_132_dialog_content = "But yeah, I can't stay anymore.",
  ui_story_5051_50511501_133_dialog_content = "Take me out of here, Jakine!",
  ui_story_5051_50511501_134_dialog_content = "That's about as blunt as you can get for someone who's been missing.",
  ui_story_5051_50511501_135_dialog_content = "Well, everybody's here, shouldn't we leave now?",
  ui_story_5051_50511501_136_dialog_content = "Didn't you say we have to leave the Crystal of Eternal Memory fast or there would be trouble?",
  ui_story_5051_50511501_137_dialog_content = "Yes, I did say that.",
  ui_story_5051_50511501_138_dialog_content = "Ready to leave, everyone?",
  ui_story_5051_50511501_139_dialog_content = "Mother is still awaiting us for supper...",
  ui_story_5051_50511501_140_dialog_content = "There is still time. We can stay for a while.",
  ui_story_5051_50511501_141_dialog_content = "But weren't you urging us to leave before, City Lord?",
  ui_story_5051_50511501_142_dialog_content = "That is because we were all in danger.",
  ui_story_5051_50511501_143_dialog_content = "But now the greatest threat has passed.",
  ui_story_5051_50511501_144_dialog_content = "And...",
  ui_story_5051_50511501_145_dialog_content = "(Maybe Caleb is right. That quarrel was the beginning of the end.)",
  ui_story_5051_50511501_146_dialog_content = "(While I gained the support of all nobles in Lumopolis that day, I hurt my most beloved deeply.)",
  ui_story_5051_50511501_147_dialog_content = "Father?",
  ui_story_5051_50511501_148_dialog_content = "Not to mention if we leave now...",
  ui_story_5051_50511501_149_dialog_content = "Joshua will be left to spend a stressful night alone as before.",
  ui_story_5051_50511501_150_dialog_content = "Why are you trying to convince with your act, Schwartz?",
  ui_story_5051_50511501_151_dialog_content = "I know you always hated me because of what happened to Joshua, Caleb.",
  ui_story_5051_50511501_152_dialog_content = "It is too late for me to mend the past wrongs.",
  ui_story_5051_50511501_153_dialog_content = "I understand the animosity you feel toward me.",
  ui_story_5051_50511501_154_dialog_content = "If I get another chance, I will not let her...",
  ui_story_5051_50511501_155_dialog_content = "Heh, no use talking about it now.",
  ui_story_5051_50511501_156_dialog_content = "This entire world is fake to the core...",
  ui_story_5051_50511501_157_dialog_content = "Atoning here won't change anything!",
  ui_story_5051_50511501_158_dialog_content = "U-Uncle...",
  ui_story_5051_50511501_159_dialog_content = "I would like to say goodbye to Mother",
  ui_story_5051_50511501_160_dialog_content = "I know this world isn't real, but the emotions certainly are.",
  ui_story_5051_50511501_161_dialog_content = "Please give us this precious last moment.",
  ui_story_5051_50511501_162_dialog_content = "A-Actually, I'd like to say goodbye to someone too.",
  ui_story_5051_50511501_163_dialog_content = "We still got time and no threat for the present...",
  ui_story_5051_50511501_164_dialog_content = "So why doesn't everybody go say their goodbyes?",
  ui_story_5051_50511501_165_dialog_content = "They might not recognize us the next time we come, after all.",
  ui_story_5051_50511501_166_dialog_content = "You people...!",
  ui_story_5051_50511501_167_dialog_content = "Mind accompanying me for my farewell, PlayerName?",
  ui_story_5051_50511501_168_dialog_content = "I'm just a stranger to her now. It will not be proper without you present.",
  ui_story_5051_50511501_169_dialog_content = "But how are you going to say what you want to say when you're supposed to be my father?",
  ui_story_5051_50511501_170_dialog_content = "If only Joshua could recognize you...",
  ui_story_5051_50511501_171_dialog_content = "Hey, Jakine, can't you control the Crystal?",
  ui_story_5051_50511501_172_dialog_content = "Any way to make Joshua recognize our City Lord?",
  ui_story_5051_50511501_173_dialog_content = "Well, not that there's no way...",
  ui_story_5051_50511501_174_dialog_content = "It's just I've never tried it before and I don't want another screw-up.",
  ui_story_5051_50511501_175_dialog_content = "It is all right. Try it.",
  ui_story_5051_50511501_176_dialog_content = "You trust me, City Lord?",
  ui_story_5051_50511501_177_dialog_content = "I guess I'm all out of excuses. I'll help you clear the air!",
  ui_story_5051_50511501_178_dialog_content = "However...",
  ui_story_5051_50511501_179_dialog_content = "Give me time to go through my book first! Heehee.",
  ui_story_5051_50511501_180_dialog_content = "Ahem, will this work, my lord?",
  ui_story_5051_50511501_181_dialog_content = "I have ducked and dodged for more than a decade, young one...",
  ui_story_5051_50511501_182_dialog_content = "To me, coming here may not be purely coincidental.",
  ui_story_5051_50511501_183_dialog_content = "Perhaps the God of Light is guiding me.",
  ui_story_5051_50511501_184_dialog_content = "It is time for me to face my cowardice.",
  ui_story_5051_50511501_185_dialog_content = "I should remind you that the illusion will only last a little while, my lord.",
  ui_story_5051_50511501_186_dialog_content = "Make sure you come back before time's up!",
  ui_story_5051_50511501_187_dialog_content = "I am ready.",
  ui_story_5051_50511501_188_dialog_content = "Let me get started, then!",
  ui_story_5051_50511501_189_dialog_content = "Mutatio! Mutatio! Mutatio!",
  ui_story_5051_50511501_190_dialog_content = "Please change Daniel Schwartz back to his younger day!",
  ui_story_5051_50511501_191_dialog_content = "Abracadabra!",
  ui_story_5051_50511501_192_dialog_content = "<color=#e8d9bb>Bam!</color>",
  ui_story_5051_50511501_193_dialog_content = "Wow!",
  ui_story_5051_50511501_194_dialog_content = "What is going on? Why are you so surprised, PlayerName?",
  ui_story_5051_50511501_195_dialog_content = "You certainly look... memorable when you were young.",
  ui_story_5051_50511501_196_dialog_content = "Boo-hoo...",
  ui_story_5051_50511501_197_dialog_content = "Uh, how come you changed City Lord to look like Judge Jr.?",
  ui_story_5051_50511501_198_dialog_content = "Judge Jr.?!",
  ui_story_5051_50511501_199_dialog_content = "Ahem... Guess I got too excited and didn't quite picture what your young self looked like in my mind...",
  ui_story_5051_50511501_200_dialog_content = "Didn't we meet his younger self just a few minutes ago?",
  ui_story_5051_50511501_201_dialog_content = "Oh, that's right!",
  ui_story_5051_50511501_202_dialog_content = "That should make it easier. Let me try again!",
  ui_story_5051_50511501_203_dialog_content = "Mutatio! Mutatio! Mutatio!",
  ui_story_5051_50511501_204_dialog_content = "Please change Daniel Schwartz back to his younger day!",
  ui_story_5051_50511501_205_dialog_content = "Abracadabra!",
  ui_story_5051_50511501_206_dialog_content = "<color=#e8d9bb>Bam!</color>",
  ui_story_5051_50511501_207_dialog_content = "Is that you at the door, guard?",
  ui_story_5051_50511501_208_dialog_content = "Supper is ready. Would you mind informing everyone for me?",
  ui_story_5051_50511501_209_dialog_content = "...",
  ui_story_5051_50511501_210_dialog_content = "Guard?",
  ui_story_5051_50511501_211_dialog_content = "It's you?",
  ui_story_5051_50511501_212_dialog_content = "...",
  ui_story_5051_50511501_213_dialog_content = "<size=30>Sorry.</size>",
  ui_story_5051_50511501_214_dialog_content = "What did you say?",
  ui_story_5051_50511501_215_dialog_content = "Nothing much.",
  ui_story_5051_50511501_216_dialog_content = "Did you just say sorry, Daniel?",
  ui_story_5051_50511501_217_dialog_content = "Joshua...",
  ui_story_5051_50511501_218_dialog_content = "It's good that you're back.",
  ui_story_5051_50511501_219_dialog_content = "You should come home when you're exhausted.",
  ui_story_5051_50511501_220_dialog_content = "I'm fine. And the children and I will stay with you, always.",
  ui_story_5051_50511501_221_dialog_content = "...",
  ui_story_5051_50511501_222_dialog_content = "Take a break while I get someone to set up another seat at the table.",
  ui_story_5051_50511501_223_dialog_content = "...",
  ui_story_5051_50511501_224_dialog_content = "How am I going to do anything with you holding on to me, Daniel?",
  ui_story_5051_50511501_225_dialog_content = "I have a lot I want to tell you.",
  ui_story_5051_50511501_226_dialog_content = "So you finally remembered there's someone else in the family who will listen to you gripe?",
  ui_story_5051_50511501_227_dialog_content = "What is it, and does it have to be now?",
  ui_story_5051_50511501_228_dialog_content = "Yes.",
  ui_story_5051_50511501_229_dialog_content = "All right, I guess everyone will have to stave off their hunger for a little longer.",
  ui_story_5051_50511501_230_dialog_content = "Let's hear what you have to say!",
  ui_story_5051_50511501_231_dialog_content = "...",
  ui_story_5051_50511501_232_dialog_content = "I... miss you so much.",
  ui_story_5051_50511501_233_dialog_content = "Huh?",
  ui_story_5051_50511501_234_dialog_content = "<color=#e8d9bb>In a corner</color>",
  ui_story_5051_50511501_235_dialog_content = "Hurry up, Jakine!",
  ui_story_5051_50511501_236_dialog_content = "Why does your spell stop working when it's my turn?",
  ui_story_5051_50511501_237_dialog_content = "Hey, don't rush me, okay! You have to be in the mood to cast the spell, you know.",
  ui_story_5051_50511501_238_dialog_content = "Or maybe you preferred the plaster head we just saw!",
  ui_story_5051_50511501_239_dialog_content = "You...!",
  ui_story_5051_50511501_240_dialog_content = "My father... Did he get it off his chest?",
  ui_story_5051_50511501_241_dialog_content = "I think so from the looks of it. Those two still seem pretty chummy.",
  ui_story_5051_50511501_242_dialog_content = "<size=45>Ahhh! What's that hypocrite trying to do to my sister!</size>",
  ui_story_5051_50511501_243_dialog_content = "Why did you just cover my eyes, PlayerName?",
  ui_story_5051_50511501_244_dialog_content = "Isn't it you who covered my eyes, Mia?",
  ui_story_5051_50511501_245_dialog_content = "Geez, every one of you brats...",
  ui_story_5051_50511501_246_dialog_content = "<size=45>No more peeking!</size>",
  ui_story_5051_50511601_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5051_50511601_2_dialog_content = "How can anyone still be out after that hangover cure?",
  ui_story_5051_50511601_3_dialog_content = "But it's all right, this gives me a chance to call you out loud...",
  ui_story_5051_50511601_4_dialog_content = "M-Mama...",
  ui_story_5051_50511601_5_dialog_content = "Heh, what's the matter with me. I feel a little awkward shouting it.",
  ui_story_5051_50511601_6_dialog_content = "I've hoped to see you again ever since you left home a dozen years ago to meditate.",
  ui_story_5051_50511601_7_dialog_content = "I fantasized that one day I could find where you are with divination.",
  ui_story_5051_50511601_8_dialog_content = "And wondered if you still looked the same...",
  ui_story_5051_50511601_9_dialog_content = "Always wearing a veil, being busy in a remote forest cabin by yourself.",
  ui_story_5051_50511601_10_dialog_content = "But years have passed and my memories of you have become a blur.",
  ui_story_5051_50511601_11_dialog_content = "Imagine my surprise when I ran into the younger you in Lumopolis today.",
  ui_story_5051_50511601_12_dialog_content = "What's even more surprising is you seemed so... unreliable!",
  ui_story_5051_50511601_13_dialog_content = "But compared to what I remembered, you were still more outgoing, adorable, brash...",
  ui_story_5051_50511601_14_dialog_content = "After you left, Dad thought about moving us out of Northland.",
  ui_story_5051_50511601_15_dialog_content = "But I feared if we left, you wouldn't find us when you returned, so I stayed behind, alone.",
  ui_story_5051_50511601_16_dialog_content = "But don't you worry, I have lots and lots of friends!",
  ui_story_5051_50511601_17_dialog_content = "I learned spells from the divination book you left behind... Although I'm not very good yet and goofed up a lot.",
  ui_story_5051_50511601_18_dialog_content = "But just you wait!",
  ui_story_5051_50511601_19_dialog_content = "I'll become Boaz's greatest pupil and craft a crystal ball even more powerful than the Crystal of Eternal Memory!",
  ui_story_5051_50511601_20_dialog_content = "Maybe then, I can detect where you're hiding in Northland.",
  ui_story_5051_50511601_21_dialog_content = "Anyway, you'll see when we meet again!",
  ui_story_5051_50511601_22_dialog_content = "My child.",
  ui_story_5051_50511601_23_dialog_content = "What? You're awake?",
  ui_story_5051_50511601_24_dialog_content = "Ahem, I was just jibber-jabbing. Pay no mind to it.",
  ui_story_5051_50511601_25_dialog_content = "Not that you'd comprehend a word I said, anyway... Sorry to wake you up. I just wanted to say goodbye.",
  ui_story_5051_50511601_26_dialog_content = "Oh, you think that poorly of my comprehension?",
  ui_story_5051_50511601_27_dialog_content = "Yeah, since you've been drunk all along...",
  ui_story_5051_50511601_28_dialog_content = "Wait, why are you acting serious now? I'm not used to this!",
  ui_story_5051_50511601_29_dialog_content = "It will take skills far beyond your current level to unlock the Crystal's secrets.",
  ui_story_5051_50511601_30_dialog_content = "Let alone creating one.",
  ui_story_5051_50511601_31_dialog_content = "Are you sure that's what you want to do, Jakine?",
  ui_story_5051_50511601_32_dialog_content = "Yeah, a hundred percent sure!",
  ui_story_5051_50511601_33_dialog_content = "Wait, didn't you refuse to admit I'm your daughter?",
  ui_story_5051_50511601_34_dialog_content = "You, indeed, are not MY daughter Jakine.",
  ui_story_5051_50511601_35_dialog_content = "But I also know you are indeed Jakine.",
  ui_story_5051_50511601_36_dialog_content = "You're finally back, Jakine.",
  ui_story_5051_50511601_37_dialog_content = "Hey, sorry, I had too much to say and forgot the time.",
  ui_story_5051_50511601_38_dialog_content = "What's wrong? Is something bothering you?",
  ui_story_5051_50511601_39_dialog_content = "I-Is there?",
  ui_story_5051_50511601_40_dialog_content = "Oh, Caleb, wanna try again? I guarantee I'll make you look younger!",
  ui_story_5051_50511601_X41_dialog_content = "Forget it. Having the head of a rabbit is not for me.",
  ui_story_5051_50511601_42_dialog_content = "Shhh...",
  ui_story_5051_50511601_43_dialog_content = "Don't let Father and Mother spot us.",
  ui_story_5051_50511601_44_dialog_content = "Is the City Lord still saying goodbye to Lady Joshua?",
  ui_story_5051_50511601_45_dialog_content = "It doesn't look like it's gonna end any time soon...",
  ui_story_5051_50511601_46_dialog_content = "Hmm, how come the children and guests aren't here yet?",
  ui_story_5051_50511601_47_dialog_content = "They're... already asleep.",
  ui_story_5051_50511601_48_dialog_content = "We all have had an exhausting day, but we can't just skip meals!",
  ui_story_5051_50511601_49_dialog_content = "I'll get someone to send food to their rooms...",
  ui_story_5051_50511601_50_dialog_content = "I already gave the order. You do not have to worry about that.",
  ui_story_5051_50511601_51_dialog_content = "Oh? This is unlike you, Daniel.",
  ui_story_5051_50511601_52_dialog_content = "Are you feeling guilty about something?",
  ui_story_5051_50511601_53_dialog_content = "Feeling guilty?",
  ui_story_5051_50511601_54_dialog_content = "Yeah. Otherwise, why would the swamped City Lord suddenly make time for his wife?",
  ui_story_5051_50511601_55_dialog_content = "I just feel...",
  ui_story_5051_50511601_56_dialog_content = "We have not sat down and enjoyed supper like this as a couple for a long time.",
  ui_story_5051_50511601_57_dialog_content = "That's true, but I thought you stopped caring about it.",
  ui_story_5051_50511601_58_dialog_content = "Sorry.",
  ui_story_5051_50511601_59_dialog_content = "Oh, why have you been saying that all the time tonight?",
  ui_story_5051_50511601_60_dialog_content = "What compelled you to apologize to me?",
  ui_story_5051_50511601_61_dialog_content = "I cannot tell you at this moment.",
  ui_story_5051_50511601_62_dialog_content = "Daniel...",
  ui_story_5051_50511601_63_dialog_content = "Is it because of House Kartima?",
  ui_story_5051_50511601_64_dialog_content = "Are you really not going to let every one of them go, Daniel?",
  ui_story_5051_50511601_65_dialog_content = "...",
  ui_story_5051_50511601_66_dialog_content = "Not true.",
  ui_story_5051_50511601_67_dialog_content = "Only the real offenders should be punished.",
  ui_story_5051_50511601_68_dialog_content = "Did you just lie to placate me?",
  ui_story_5051_50511601_69_dialog_content = "That's not it, Joshua!",
  ui_story_5051_50511601_70_dialog_content = "<color=#e8d9bb>Click!</color>",
  ui_story_5051_50511601_71_dialog_content = "Joshua?",
  ui_story_5051_50511601_72_dialog_content = "<anim type=Shake>Lying to me.</anim>",
  ui_story_5051_50511601_73_dialog_content = "Joshua?",
  ui_story_5051_50511601_74_dialog_content = "What's wrong, Joshua?!",
  ui_story_5051_50511601_75_dialog_content = "<anim type=Shake>You... lied... to... me...</anim>",
  ui_story_5051_50511601_76_dialog_content = "Was I to blame for what you became, Joshua?",
  ui_story_5051_50511601_77_dialog_content = "I put everything into disposing of House Kartima...",
  ui_story_5051_50511601_78_dialog_content = "I did not trust your judgment, choosing to ignore your advice...",
  ui_story_5051_50511601_79_dialog_content = "I did not appreciate your effort, tasking you with every family obligation...",
  ui_story_5051_50511601_80_dialog_content = "I did not stand by you when you needed me the most...",
  ui_story_5051_50511601_81_dialog_content = "I am sorry!",
  ui_story_5051_50511601_82_dialog_content = "<color=#e8d9bb>Crack!</color>",
  ui_story_5051_50511601_83_dialog_content = "<anim type=Shake>Daniel...</anim>",
  ui_story_5051_50511601_84_dialog_content = "I am here, I'm here, Joshua!",
  ui_story_5051_50511601_85_dialog_content = "<anim type=Shake>Daniel... Veronica... Carleen...</anim>",
  ui_story_5051_50511601_86_dialog_content = "<anim type=Shake>Ahhhh!!!</anim>",
  ui_story_5051_50511601_87_dialog_content = "Joshua!",
  ui_story_5051_50511601_88_dialog_content = "Mother? What happened to Mother?",
  ui_story_5051_50511601_89_dialog_content = "<color=#e8d9bb>Rumble</color>",
  ui_story_5051_50511601_90_dialog_content = "<color=#e8d9bb>Rumble—!!!</color>",
  ui_story_5051_50511601_91_dialog_content = "That thunderclap noise again?",
  ui_story_5051_50511601_92_dialog_content = "Earthquake? Is it an earthquake?",
  ui_story_5051_50511601_93_dialog_content = "No. No earthquake that night in true history.",
  ui_story_5051_50511601_94_dialog_content = "I don't think I can see anything...",
  ui_story_5051_50511601_95_dialog_content = "Me too! I'm resorting to what little psychic powers I have left to discern direction.",
  ui_story_5051_50511601_96_dialog_content = "Is the time almost up, Jakine?",
  ui_story_5051_50511601_97_dialog_content = "No, we should still have plenty of time until the day's over. This can't be it?!",
  ui_story_5051_50511601_98_dialog_content = "Don't tell me we're about to fall through the cracks between the Crystal and the real world!",
  ui_story_5051_50511601_99_dialog_content = "What are you waiting for, Jakine?",
  ui_story_5051_50511601_100_dialog_content = "Lead all of us out!",
  ui_story_5051_50511601_101_dialog_content = "Gather around me, everyone!",
  ui_story_5051_50511601_102_dialog_content = "But we're missing my father...",
  ui_story_5051_50511601_103_dialog_content = "It's fitting for that self-righteous guy to be trapped here. Forget him, let's go!",
  ui_story_5051_50511601_104_dialog_content = "Even if it's the vilest of scoundrels, we shouldn't leave him behind like this...",
  ui_story_5051_50511601_105_dialog_content = "Call to the City Lord",
  ui_story_5051_50511601_106_dialog_content = "We're over here, Lord Schwartz!",
  ui_story_5051_50511601_107_dialog_content = "Father!",
  ui_story_5051_50511601_108_dialog_content = "Lord Schwartz!",
  ui_story_5051_50511601_109_dialog_content = "Why doesn't he respond...?",
  ui_story_5051_50511601_110_dialog_content = "Contact City Lord mentally",
  ui_story_5051_50511601_111_dialog_content = "Curses...",
  ui_story_5051_50511601_112_dialog_content = "I still can't contact anyone mentally in the Crystal!",
  ui_story_5051_50511601_113_dialog_content = "Oh!",
  ui_story_5051_50511601_114_dialog_content = "What's the matter, Mia?",
  ui_story_5051_50511601_115_dialog_content = "The space behind us... It's slowly collapsing into the void!",
  ui_story_5051_50511601_116_dialog_content = "Gotta hustle, PlayerName!",
  ui_story_5051_50511601_117_dialog_content = "Follow me and head toward where the City Lord was!",
  ui_story_5051_50511601_118_dialog_content = "Jakine, if we still can't see him at the very last second...",
  ui_story_5051_50511601_119_dialog_content = "Take us out of here!",
  ui_story_5051_50511601_120_dialog_content = "Okay!",
  ui_story_5051_50511601_121_dialog_content = "Psst.",
  ui_story_5051_50511601_122_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5051_50511601_123_dialog_content = "Did someone just run by?",
  ui_story_5051_50511601_124_dialog_content = "Who could run that fast under the circumstance?",
  ui_story_5051_50511601_125_dialog_content = "<anim type=Shake><size=30>Daniel... Veronica... Carleen...</size></anim>",
  ui_story_5051_50511601_126_dialog_content = "Someone is calling my name?",
  ui_story_5051_50511601_127_dialog_content = "It's barely audible. I can't tell where it comes from.",
  ui_story_5051_50511601_128_dialog_content = "<anim type=Shake>H-Here?</anim>",
  ui_story_5051_50511601_129_dialog_content = "What...",
  ui_story_5051_50511601_130_dialog_content = "Watch out!",
  ui_story_5051_50511601_131_dialog_content = "Father!",
  ui_story_5051_50511601_132_dialog_content = "Be alert, we have an uninvited visitor here.",
  ui_story_5051_50511601_133_dialog_content = "What a merciless attack... Who would assault us like this?",
  ui_story_5051_50511601_134_dialog_content = "Are we in the rift between the Crystal and the real world already?",
  ui_story_5051_50511601_135_dialog_content = "No! No—!",
  ui_story_5051_50511601_136_dialog_content = "<anim type=Shake>H-Here?</anim>",
  ui_story_5051_50511601_137_dialog_content = "Eek, monster!",
  ui_story_5051_50511601_138_dialog_content = "Only you can tell the direction now, PlayerName.",
  ui_story_5051_50511601_139_dialog_content = "Take the lead!",
  ui_story_5051_50511602_1_dialog_content = "Huff... puff...",
  ui_story_5051_50511602_2_dialog_content = "Pause for a break, Mia!",
  ui_story_5051_50511602_3_dialog_content = "But... no, I want to help you, help everybody...",
  ui_story_5051_50511602_4_dialog_content = "Over here?",
  ui_story_5051_50511602_5_dialog_content = "Activate, crystal ball!",
  ui_story_5051_50511602_6_dialog_content = "Come on, why does the monster keep attacking?",
  ui_story_5051_50511602_7_dialog_content = "How come there's such a monster in the Crystal, Jakine?",
  ui_story_5051_50511602_8_dialog_content = "I-I have no idea either.",
  ui_story_5051_50511602_9_dialog_content = "You sure it's not something that showed up in Lumopolis?",
  ui_story_5051_50511602_10_dialog_content = "...",
  ui_story_5051_50511602_11_dialog_content = "White Night, protect us!",
  ui_story_5051_50511602_12_dialog_content = "There was no such monster in Lumopolis at that time.",
  ui_story_5051_50511602_13_dialog_content = "But do not concede!",
  ui_story_5051_50511602_14_dialog_content = "Compared to before, its powers have obviously diminished and the intervals between attacks are getting longer.",
  ui_story_5051_50511602_15_dialog_content = "Jakine, after it attacks again, take us out during the gap!",
  ui_story_5051_50511602_16_dialog_content = "Got it, Lord Schwartz!",
  ui_story_5051_50511602_17_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5051_50511602_18_dialog_content = "How come everything stopped all of a sudden?",
  ui_story_5051_50511602_19_dialog_content = "Quiet... Did you hear that?",
  ui_story_5051_50511602_20_dialog_content = "<anim type=Shake><size=30>Daniel... Veronica... Carleen...</size></anim>",
  ui_story_5051_50511602_21_dialog_content = "It's calling my name and that of my father and sister?",
  ui_story_5051_50511602_22_dialog_content = "<anim type=Shake>Daniel, Veronica, Carleen.</anim>",
  ui_story_5051_50511602_23_dialog_content = "That voice...",
  ui_story_5051_50511602_24_dialog_content = "<anim type=Shake>And... Caleb.</anim>",
  ui_story_5051_50511602_25_dialog_content = "<color=#FFB400>Joshua</color>?!",
  ui_story_5051_50511602_26_dialog_content = "How can this be?",
  ui_story_5051_50511602_27_dialog_content = "I-It's my sister?",
  ui_story_5051_50511602_28_dialog_content = "No, no, no... Impossible, she can't be here!",
  ui_story_5051_50511602_29_dialog_content = "Could it be...?",
  ui_story_5051_50511602_30_dialog_content = "...",
  ui_story_5051_50511602_31_dialog_content = "Why did it stop?",
  ui_story_5051_50511602_32_dialog_content = "<anim type=Shake>No!</anim>",
  ui_story_5051_50511602_33_dialog_content = "<anim type=Shake>You can't do this!</anim>",
  ui_story_5051_50511602_34_dialog_content = "<anim type=Shake>Why not?</anim>",
  ui_story_5051_50511602_35_dialog_content = "<anim type=Shake>They are the source of all your pain.</anim>",
  ui_story_5051_50511602_36_dialog_content = "<anim type=Shake>The roadblock to fulfilling your dreams!</anim>",
  ui_story_5051_50511602_37_dialog_content = "<anim type=Shake>They are the people I care most about!</anim>",
  ui_story_5051_50511602_38_dialog_content = "<anim type=Shake>Kill them and you're free to leave!</anim>",
  ui_story_5051_50511602_39_dialog_content = "<anim type=Shake>Why wait? They're almost at the end of the rope.</anim>",
  ui_story_5051_50511602_40_dialog_content = "<anim type=Shake>This is annoying!</anim>",
  ui_story_5051_50511602_41_dialog_content = "<anim type=Shake>Get out!</anim>",
  ui_story_5051_50511602_42_dialog_content = "Is it talking to itself?",
  ui_story_5051_50511602_X43_dialog_content = "This is way too weird... it feels like arguing with myself.",
  ui_story_5051_50511602_44_dialog_content = "Joshua, is this really you?",
  ui_story_5051_50511602_45_dialog_content = "Mother...?",
  ui_story_5051_50511602_46_dialog_content = "How dare you impersonate Joshua's voice?",
  ui_story_5051_50511602_47_dialog_content = "I'll show you no mercy!",
  ui_story_5051_50511602_48_dialog_content = "<anim type=Shake>Schwar...</anim>",
  ui_story_5051_50511602_49_dialog_content = "I will shake every star—!!!",
  ui_story_5051_50511602_50_dialog_content = "<anim type=Shake>Ugh...</anim>",
  ui_story_5051_50511602_51_dialog_content = "<anim type=Shake><size=45>I... hate... you...!</size></anim>",
  ui_story_5051_50511602_52_dialog_content = "What?",
  ui_story_5051_50511602_53_dialog_content = "His attack worked!",
  ui_story_5051_50511602_54_dialog_content = "It appears to be in agony, but not exactly the physical type...",
  ui_story_5051_50511602_55_dialog_content = "It can't be her. Impossible. If it is her...",
  ui_story_5051_50511602_56_dialog_content = "Get us out of here now, Jakine. Now!",
  ui_story_5051_50511602_57_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50511602_58_dialog_content = "Is that the sound of a clock?",
  ui_story_5051_50511602_59_dialog_content = "Oh, no no no... The clock is striking twelve!",
  ui_story_5051_50511602_60_dialog_content = "Are we going to be trapped in here?",
  ui_story_5051_50511602_61_dialog_content = "Why... I just find it after all these...",
  ui_story_5051_50511602_62_dialog_content = "Just another minute away...",
  ui_story_5051_50511602_63_dialog_content = "Why?!",
  ui_story_5051_50511602_64_dialog_content = "What's that you hold in your hand, Caleb?",
  ui_story_5051_50511602_65_dialog_content = "Is that the Crystal of Eternal Memory for this world?",
  ui_story_5051_50511602_66_dialog_content = "A Crystal within the Crystal?",
  ui_story_5051_50511602_67_dialog_content = "So what? It's futile even if I found it.",
  ui_story_5051_50511602_68_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5051_50511602_69_dialog_content = "The clock is about to reach twelve!",
  ui_story_5051_50511602_70_dialog_content = "Why were you looking for this in the Crystal, Caleb?",
  ui_story_5051_50511602_71_dialog_content = "I already said, it's futile.",
  ui_story_5051_50511602_72_dialog_content = "No, there might be a way!",
  ui_story_5051_50511602_73_dialog_content = "Give me the Crystal, Caleb!",
  ui_story_5051_50511602_74_dialog_content = "Take it.",
  ui_story_5051_50511602_75_dialog_content = "Mom...",
  ui_story_5051_50511602_76_dialog_content = "You foresaw this happening, didn't you?",
  ui_story_5051_50511602_77_dialog_content = "People like to predict the future through divination.",
  ui_story_5051_50511602_78_dialog_content = "But then I realized we always underestimated how fast we forget things.",
  ui_story_5051_50511602_79_dialog_content = "So in certain regards, what's more unpredictable is the <color=#FFB400>past</color>.",
  ui_story_5051_50511602_80_dialog_content = "That was why I crafted the Crystal of Eternal Memory in the first place.",
  ui_story_5051_50511602_81_dialog_content = "I originally thought it'd be the safest method to review history.",
  ui_story_5051_50511602_82_dialog_content = "But your appearance tipped me off to unforeseen scenarios with the Crystal.",
  ui_story_5051_50511602_83_dialog_content = "Fortunately, there's a failsafe in the world within.",
  ui_story_5051_50511602_84_dialog_content = "... A Crystal within the Crystal.",
  ui_story_5051_50511602_85_dialog_content = "That's the only thing left out in the book.",
  ui_story_5051_50511602_86_dialog_content = "I hope you'll never have to access that information.",
  ui_story_5051_50511602_87_dialog_content = "I won't let you down!",
  ui_story_5051_50511602_88_dialog_content = "Reditus, reditus, reditus!",
  ui_story_5051_50511602_89_dialog_content = "Ad praessence!",
  ui_story_5051_50511602_90_dialog_content = "Rewind to the beginning, let us return to reality!",
  ui_story_5051_50511602_91_dialog_content = "<size=45>Abracadabra!</size>",
  ui_story_5051_50511602_92_dialog_content = "Ugh!",
  ui_story_5051_50511602_93_dialog_content = "Again... The world is spinning around me...",
  ui_story_5051_50511602_94_dialog_content = "Hold on to each other and don't let go!",
  ui_story_5051_50511602_95_dialog_content = "Come to me, Mia and PlayerName!",
  ui_story_5051_50511602_96_dialog_content = "Oh, no, I can't pull Caleb in!",
  ui_story_5051_50511602_97_dialog_content = "I'm sorry, my sister... I won't be around you anymore...",
  ui_story_5051_50511602_98_dialog_content = "We can't... leave anyone behind!",
  ui_story_5051_50511602_99_dialog_content = "PlayerName?!",
  ui_story_5051_50511602_100_dialog_content = "Caleb!",
  ui_story_5051_50511602_101_dialog_content = "Take my hand!",
  ui_story_5051_50511602_102_dialog_content = "Agh!",
  ui_story_5051_50511602_103_dialog_content = "Stop stretching out, PlayerName. My father's losing his grip on you!",
  ui_story_5051_50511602_104_dialog_content = "I can't give up!",
  ui_story_5051_50511602_105_dialog_content = "PlayerName!!!",
  ui_story_5051_50511602_106_dialog_content = "Gotcha! I got Caleb!",
  ui_story_5051_50511602_107_dialog_content = "PlayerName...?",
  ui_story_5051_50511602_108_dialog_content = "<color=#e8d9bb>Crash!</color>",
  ui_story_5051_50511602_109_dialog_content = "(Is that a cup shattering?)",
  ui_story_5051_50511602_110_dialog_content = "(But there's only one cup in the room...)",
  ui_story_5051_50511602_111_dialog_content = "(So that fine wine still couldn't calm Mr. Caleb down, I see...)",
  ui_story_5051_50511602_112_dialog_content = "That was quite a commotion, Ms. Rot.",
  ui_story_5051_50511602_113_dialog_content = "Which honored guest was so careless as to break objects in the City Lord's room?",
  ui_story_5051_50511602_114_dialog_content = "Or should I say which guest infuriated the lord so much that he must resort to throwing objects?",
  ui_story_5051_50511602_115_dialog_content = "I admire your imagination, Duke.",
  ui_story_5051_50511602_116_dialog_content = "However, it is not our business to discuss or speculate the content of the City Lord and his guest's conversation.",
  ui_story_5051_50511602_117_dialog_content = "Humph. You're not the captain of Nightwatch anymore, are you?",
  ui_story_5051_50511602_118_dialog_content = "But I will not be negligent in performing duties for the City Lord.",
  ui_story_5051_50511602_119_dialog_content = "Duties? You're just an interim host for the party.",
  ui_story_5051_50511602_120_dialog_content = "If you like doing this, can I invite you to assist with my son's birthday, Ms. Rot?",
  ui_story_5051_50511602_121_dialog_content = "I think I didn't make myself clear, Duke.",
  ui_story_5051_50511602_122_dialog_content = "I am still working for the City Lord.",
  ui_story_5051_50511602_123_dialog_content = "Whatever you say, he will not be able to grant an audience to your son tonight.",
  ui_story_5051_50511602_124_dialog_content = "Well, I never made such a demand, Ms. Rot.",
  ui_story_5051_50511602_125_dialog_content = "I just wanted to say goodbye to him since it was getting late.",
  ui_story_5051_50511602_126_dialog_content = "But the way you chose to take the low road...",
  ui_story_5051_50511602_127_dialog_content = "That is unbefitting for someone who is working for the City Lord.",
  ui_story_5051_50511602_128_dialog_content = "Well, you can never be too careful.",
  ui_story_5051_50511602_129_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5051_50511602_130_dialog_content = "What?",
  ui_story_5051_50511602_131_dialog_content = "Outside...",
  ui_story_5051_50511602_132_dialog_content = "The wind is rising.",
  ui_story_5051_50511602_133_dialog_content = "<color=#e8d9bb>Meanwhile in Caleb's residence</color>",
  ui_story_5051_50511602_134_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5051_50511602_135_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5051_50511602_136_dialog_content = "<color=#e8d9bb>Rumble—!</color>",
  ui_story_5051_50511602_137_dialog_content = "...",
  ui_story_5051_50511602_138_dialog_content = "...",
  ui_story_5051_50511602_139_dialog_content = "...",
  ui_story_5051_50511602_140_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5051_50511602_141_dialog_content = "<color=#e8d9bb>Rumble—!</color>",
  ui_story_5051_50511602_142_dialog_content = "<color=#e8d9bb>Rumble!!!</color>",
  ui_story_5051_50511602_143_dialog_content = "To be continued..."
}
return config
